[9293] = {name = "[q2]Recipe: Magic Resistance Potion", additional_info = "Requires Alchemy (210)\n\n[q2]Use: Teaches you how to make a Magic Resistance Potion.\nSell Price: \nMagic Resistance Potion\nRequires Level 32\n\n[q2]Use: Increases your resistance to all schools of magic by 50 for 3 min. (2 Min Cooldown)\nSell Price:\nRequires Khadgar's Whisker , Purple Lotus , Crystal Vial"},
[9294] = {name = "[q2]Recipe: Wildvine Potion", additional_info = "Requires Alchemy (225)\n\n[q2]Use: Teaches you how to make a Wildvine potion.\nSell Price:\nWildvine Potion\nRequires Level 35\n\n[q2]Use: Restores 1 to 1500 health and 1 to 1500 mana. (2 Min Cooldown)\nSell Price: \nRequires Wildvine , Purple Lotus , Crystal Vial"},
[9295] = {name = "[q2]Recipe: Invisibility Potion", additional_info = "Requires Alchemy (235)\n\n[q2]Use: Teaches you how to make an Invisibility Potion.\nSell Price:\nInvisibility Potion\nRequires Level 37\n\n[q2]Use: Gives the imbiber invisibility for 18 sec. (10 Min Cooldown)\nSell Price:\nRequires Ghost Mushroom , Sungrass , Crystal Vial"},
[9296] = {name = "[q2]Recipe: Gift of Arthas", additional_info = "Requires Alchemy (240)\n\n[q2]Use: Teaches you how to make a Gift of Arthas.\nSell Price:\nGift of Arthas\nRequires Level 38\n\n[q2]Use: Increases resistance to shadow by 10. If an enemy strikes the imbiber, the attacker has a 30% chance of being inflicted with disease that increases their damage taken by 8 for 3 min. Lasts for 30 min. (Proc chance: 30%) (3 Sec Cooldown)\nSell Price: \nRequires Arthas' Tears , Blindweed , Crystal Vial"},
[9297] = {name = "[q2]Recipe: Elixir of Dream Vision", additional_info = "Requires Alchemy (240)\n\n[q2]Use: Teaches you how to make an Elixir of Dream Vision.\nSell Price:\nElixir of Dream Vision\nRequires Level 38\n\n[q2]Use: Gives you a dream vision that lets you explore areas that are too dangerous to explore in person. (3 Sec Cooldown)\nSell Price:\nRequires Purple Lotus (3), Crystal Vial"},
[9298] = {name = "[q2]Recipe: Elixir of Giants", additional_info = "Requires Alchemy (245)\n\n[q2]Use: Teaches you how to make an Elixir of Giants.\nSell Price: \nElixir of Giants\nRequires Level 38\n\n[q2]Use: Increases your Strength by 25 for 1 hour. (3 Sec Cooldown)\nSell Price:\nRequires Sungrass , Gromsblood , Crystal Vial"},
