[12825] = {name = "[q2]Plans: Blazing Rapier", additional_info = "Requires Blacksmithing (280)\nRequiresMaster Swordsmith\n\n[q2]Use: Teaches you how to make a Blazing Rapier.\nSell Price:\n[q3]Blazing Rapier\nBinds when equipped\n{One-Hand} {Sword}\n{44 - 82 Damage} {Speed 1.70}\n(37.06 damage per second)\nDurability 90 / 90\nRequires Level 51\n[q2]Chance on hit: Burns the enemy for 100 damage over 30 sec.\nSell Price: \nRequires Enchanted Thorium Bar (10), Essence of Fire (4), Heart of Fire (4), Azerothian Diamond (2), Dense Grinding Stone (2)"},
[12827] = {name = "[q2]Plans: Serenity", additional_info = "Requires Blacksmithing (285)\nRequiresMaster Hammersmith\n\n[q2]Use: Teaches you how to make Serenity.\nSell Price:\n[q3]Serenity\nBinds when equipped\n{Main Hand} {Mace}\n{52 - 98 Damage} {Speed 2.00}\n(37.50 damage per second)\nDurability 90 / 90\nRequires Level 52\n[q2]Chance on hit: Dispels a magic effect on the current foe.\nSell Price: \nRequires Enchanted Thorium Bar (6), Arcanite Bar (2), Powerful Mojo (4), Large Opal (2), Blue Sapphire (2), Huge Emerald"},
[12828] = {name = "[q2]Plans: Volcanic Hammer", additional_info = "Requires Blacksmithing (290)\n\n[q2]Use: Teaches you how to make a Volcanic Hammer.\nSell Price:\n[q2]Volcanic Hammer\nBinds when equipped\n{Main Hand} {Mace}\n{60 - 113 Damage} {Speed 2.50}\n(34.60 damage per second)\nDurability 75 / 75\nRequires Level 53\n[q2]Chance on hit: Hurls a fiery ball that causes 100 to 128 Fire damage and an additional 18 damage over 6 sec.\nSell Price: \nRequires Thorium Bar (30), Heart of Fire (4), Star Ruby (4), Rugged Leather (4)"},
[12829] = {name = "Winterfall Crate", additional_info = "Quest Item\nUnique"},
[12830] = {name = "Plans: Corruption", additional_info = "Requires Blacksmithing (290)\nRequiresMaster Swordsmith\n\n[q2]Use: Teaches you how to make Corruption.\nSell Price:\n[q3]Corruption\nBinds when picked up\n{Two-Hand} {Sword}\n{119 - 179 Damage} {Speed 3.00}\n(49.67 damage per second)\n+30 Strength\n+30 Stamina\n-40 Spirit\nDurability 100 / 100\nRequires Level 53\nSell Price: \nRequires Thorium Bar (40), Arcanite Bar (2), Demonic Rune (16), Essence of Undeath (8), Blue Sapphire (2), Dense Grinding Stone (2), Rugged Leather (4)"},
[12833] = {name = "[q3]Plans: Hammer of the Titans", additional_info = "Requires Blacksmithing (300)\nRequiresMaster Hammersmith\n\n[q2]Use: Teaches you how to make a Hammer of the Titans.\nSell Price:\n[q3]Hammer of the Titans\nBinds when equipped\n{Two-Hand} {Mace}\n{163 - 246 Damage} {Speed 3.80}\n(53.82 damage per second)\n+15 Strength\nDurability 100 / 100\nRequires Level 58\n[q2]Chance on hit: Stuns target for 3 sec.\nSell Price: \nRequires Thorium Bar (50), Arcanite Bar (15), Guardian Stone (4), Enchanted Leather (6), Essence of Earth (10)"},
[12834] = {name = "[q3]Plans: Arcanite Champion", additional_info = "Requires Blacksmithing (300)\nRequiresMaster Swordsmith\n\n[q2]Use: Teaches you how to make an Arcanite Champion.\nSell Price:\n[q3]Arcanite Champion\nBinds when equipped\n{Two-Hand} {Sword}\n{129 - 194 Damage} {Speed 3.00}\n(53.83 damage per second)\nDurability 100 / 100\nRequires Level 58\n[q2]Chance on hit: Heal self for 270 to 450 and Increases Strength by 120 for 30 sec.\nSell Price: \nRequires Arcanite Bar (15), Azerothian Diamond (8), Righteous Orb , Large Opal (4), Enchanted Leather (8), Dense Grinding Stone (2)"},
[12835] = {name = "[q3]Plans: Annihilator", additional_info = "Requires Blacksmithing (300)\nRequiresMaster Axesmith\n\n[q2]Use: Teaches you how to make an Annihilator.\nSell Price:\n[q3]Annihilator\nBinds when equipped\n{Main Hand} {Axe}\n{49 - 92 Damage} {Speed 1.70}\n(41.47 damage per second)\nDurability 90 / 90\nRequires Level 58\n[q2]Chance on hit: Reduces an enemy's armor by 200. Stacks up to 3 times.\nSell Price: \nRequires Thorium Bar (40), Arcanite Bar (12), Essence of Undeath (10), Huge Emerald (8), Dense Grinding Stone (2), Enchanted Leather (4)"},
[12836] = {name = "[q3]Plans: Frostguard", additional_info = "Requires Blacksmithing (300)\nRequiresMaster Swordsmith\n\n[q2]Use: Teaches you how to make a Frostguard.\nSell Price:\n[q3]Frostguard\nBinds when equipped\n{Main Hand} {Sword}\n{66 - 124 Damage} {Speed 2.30}\n(41.30 damage per second)\nDurability 90 / 90\nRequires Level 58\n[q2]Chance on hit: Target's movement slowed by 30% and increasing the time between attacks by 25% for 5 sec.\nSell Price: \nRequires Arcanite Bar (18), Blue Sapphire (8), Azerothian Diamond (8), Essence of Water (4), Dense Grinding Stone (2), Enchanted Leather (4)"},
[12837] = {name = "[q3]Plans: Masterwork Stormhammer", additional_info = "Requires Blacksmithing (300)\nRequiresMaster Hammersmith\n\n[q2]Use: Teaches you how to make a Masterwork Stormhammer.\nSell Price:\n[q3]Masterwork Stormhammer\nBinds when equipped\n{Main Hand} {Mace}\n{58 - 108 Damage} {Speed 2.00}\n(41.50 damage per second)\nDurability 90 / 90\nRequires Level 57\n[q2]Chance on hit: Blasts up to 3 targets for 105 to 145 Nature damage.\nSell Price: \nRequires Enchanted Thorium Bar (20), Huge Emerald (8), Large Opal (8), Essence of Earth (6), Enchanted Leather (4)"},
[12838] = {name = "[q3]Plans: Arcanite Reaper", additional_info = "Requires Blacksmithing (300)\nRequiresMaster Axesmith\n\n[q2]Use: Teaches you how to make an Arcanite Reaper.\nSell Price:\n[q3]Arcanite Reaper\nBinds when equipped\n{Two-Hand} {Axe}\n{153 - 256 Damage} {Speed 3.80}\n(53.82 damage per second)\n+13 Stamina\nDurability 100 / 100\nRequires Level 58\n[q2]Equip: +62 Attack Power.\nSell Price: \nRequires Arcanite Bar (20), Enchanted Leather (6), Dense Grinding Stone (2)"},
