[14634] = {name = "[q2]Recipe: Frost Oil", additional_info = "Requires Alchemy (200)\n\n[q2]Use: Teaches you how to make Frost Oil.\nSell Price: \nFrost Oil\nRequires Level 30\n\n[q2]Use: When applied to a melee weapon it gives a 10% chance of casting Frostbolt at the opponent when it hits. Lasts 30 minutes.\nSell Price: \nRequires Khadgar's Whisker (4), Wintersbite (2), Leaded Vial"},
