[18658] = {name = "[q2]Schematic: Ultra-Flash Shadow Reflector", additional_info = "Requires Engineering (300)\n\n[q2]Use: Teaches you how to make a Ultra-Flash Shadow Reflector.\nSell Price:\n[q3]Ultra-Flash Shadow Reflector\nBinds when equipped\nTrinket\n+20 Shadow Resistance\nRequires Level 55\nRequires Engineering (300)\n[q2]Use: Reflects Shadow spells back at their caster for 5 sec. (5 Min Cooldown)\nSell Price: \nRequires Dark Iron Bar (8), Truesilver Transformer (4), Living Essence (6), Essence of Undeath (4), Azerothian Diamond (2), Large Opal (2)"},
[18659] = {name = "[q4]Splinter of Nordrassil", additional_info = "Binds when picked up\nUnique\nRequires Level 60\n\n[q2]Use: Forms Benediction when combined with the Eye of Shadow and the Eye of Divinity.\n[q]\"A tiny fragment of the World Tree\""},
