[19238] = {name = "Sayge's Fortune #3", additional_info = "Binds when picked up\n[q]\"An enemy from your past will soon become an ally.\""},
[19239] = {name = "Sayge's Fortune #4", additional_info = "Binds when picked up\n[q]\"You will be fortunate in everything you put your hands to.\""},
[19240] = {name = "Sayge's Fortune #5", additional_info = "Binds when picked up\n[q]\"Someone is speaking well of you.\""},
[19241] = {name = "Sayge's Fortune #6", additional_info = "Binds when picked up\n[q]\"Be cautious when landing in unfamiliar territory.\""},
[19242] = {name = "Sayge's Fortune #7", additional_info = "Binds when picked up\n[q]\"Avoid taking unnecessary gambles.\""},
[19243] = {name = "Sayge's Fortune #8", additional_info = "Binds when picked up\n[q]\"You will receive a fortune.\""},
[19244] = {name = "Sayge's Fortune #9", additional_info = "Binds when picked up\n[q]\"Your first love and last love is self-love.\""},
[19245] = {name = "Sayge's Fortune #10", additional_info = "Binds when picked up\n[q]\"Rest is a good thing, but boredom is its brother.\""},
[19246] = {name = "Sayge's Fortune #11", additional_info = "Binds when picked up\n[q]\"Those with simple tastes are always satisfied with the best.\""},
[19247] = {name = "Sayge's Fortune #12", additional_info = "Binds when picked up\n[q]\"Let not the tides of war wash you away.\""},
[19248] = {name = "Sayge's Fortune #13", additional_info = "Binds when picked up\n[q]\"You leave your adversaries speechless.\""},
[19249] = {name = "Sayge's Fortune #14", additional_info = "Binds when picked up\n[q]\"You have a good eye for spotting hypocrisy.\""},
[19250] = {name = "Sayge's Fortune #15", additional_info = "Binds when picked up\n[q]\"One learns most when teaching others.\""},
[19251] = {name = "Sayge's Fortune #16", additional_info = "Binds when picked up\n[q]\"The time will soon come for you to make a choice in a pressing matter.\""},
[19252] = {name = "Sayge's Fortune #18", additional_info = "Binds when picked up\n[q]\"Accept the next proposition you hear.\""},
[19253] = {name = "Sayge's Fortune #17", additional_info = "Binds when picked up\n[q]\"Never punt a gnome without due cause.\""},
[19254] = {name = "Sayge's Fortune #21", additional_info = "Binds when picked up\n[q]\"Divine Shields and Hearthstones do not make a hero heroic.\""},
