[191204] = {name = "[q2]Lesser Deathstone", additional_info = "Binds when picked up\n[q2]Use: Turn 100 lesser deathstones into a greater one."},
[191249] = {name = "[q2]Greater Deathstone", additional_info = "Binds when picked up\n[q]\"A vibrant green stone glowing with untold energies.\""},
[191267] = {name = "[q2]Rune of Teleportation: Antechamber", additional_info = "Binds when picked up\nDuration: 7 days\n[q2]Use: Transports you to the Antechamber in Naxxramas."},
[191268] = {name = "[q2]Orb of Corruption", additional_info = "Binds when picked up\nDuration: 7 days\n[q2]Use: Crush the orb, increasing the amount of lesser deathstones absorbed from Kel'Thuzad's minions by 50% for 30 min."},
[191272] = {name = "[q3]Rod of Necromancy", additional_info = "Binds when picked up\nDuration: 7 days\n[q2]Use: Subdues the will of an undead target within Naxxramas, causing them to become charmed for 5 min.\n3 Charges"},
[191280] = {name = "[q3]Fungal Spore Cluster", additional_info = "Binds when picked up\nDuration: 7 days\n[q2]Use: Grants your offensive abilities a chance to summon a spore that affects nearby players with Fungal Bloom when killed. This effect lasts for 1 hour.\n\nFungal Bloom \nInflicts 150 Nature damage every 1 sec while increasing the chance for a melee, ranged, or spell critical by 15%. (Proc chance: 10%, 15s cooldown)"},
[191288] = {name = "[q4]Rune of Teleportation: Frostwyrm's Lair", additional_info = "Binds when picked up\nDuration: 7 days\n[q2]Use: Transports you to Frostwyrm's Lair in Naxxramas."},
[191292] = {name = "[q3]Ritual Dagger", additional_info = "Binds when picked up\nDuration: 7 days\n[q2]Use: Absorb the life force of those around you, increasing stamina by 3 for each target hit. This effect stacks up to 40 and lasts for 1 hour."},
[191312] = {name = "[q4]Failsafe Phylactery", additional_info = "Binds when picked up\nUnique\nDuration: 7 daysTrinket\nRequires Level 60\n[q2]Equip: Prevents an attack that would otherwise kill you. Triggering this effect also grants you 3 sec of damage immunity and shatters the phylactery."},
[191313] = {name = "Mask of Death", additional_info = "Duration: 7 days\n[q2]Use: Adopt the visage of a denizen of Naxxramas."},
[191414] = {name = "[q3]Skeletal Artifact", additional_info = "Binds when picked up\nDuration: 7 days\n[q2]Use: Entraps the soul of the dead target, granting you a beneficial effect. This effect lasts for 1 hour."},
[191458] = {name = "[q0]Shattered Phylactery", additional_info = "Binds when picked up\nUnique\nDuration: 7 daysTrinket\nRequires Level 60\n[q]\"Dull and useless.\""},
[191459] = {name = "[q4]Rune of Fortune", additional_info = "Binds when picked up\nDuration: 7 days\n[q2]Use: Empowers Kel'Thuzad and his lieutenants with necromantic energy, granting them increased health and damage. Empowered foes will yield additional rewards upon defeat.\n\n This effect stacks and lasts for an entire week."},
[191477] = {name = "[q4]Skeletal Hitching Post", additional_info = "Binds when picked up\nUnique\nDuration: 7 days\nRequires Level 60\n\n[q2]Use: Summons a skeletal hitching post.\n\n Party members may use the post to acquire a Skeletal Steed."},
[191480] = {name = "[q4]Skeletal Steed", additional_info = "Binds when picked up\nUnique\nDuration: 1 hour\nMount\nRequires Level 40\n\n[q2]Use: Summons and dismisses a skeletal steed. This steed is obedient to the summoner and can be used as a mount within Naxxramas. Any hostile action towards the rider forces the steed to run away in fear. (3 Sec Cooldown)"},
[191481] = {name = "[q4]Tabard of Mastery", additional_info = "Binds when picked up\nTabard\n[q]\"A testament to mastery.\""},
[191550] = {name = "Book of Deathstones: Mask of Death", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 60\n[q]\"A tome detailing the art of converting deathstones into a mask of death.\""},
[191605] = {name = "[q2]Book of Deathstones: Rune of Teleportation I", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 60\n[q]\"A tome detailing the art of converting deathstones into a rune of teleportation.\""},
[191606] = {name = "[q2]Book of Deathstones: Orb of Corruption", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 60\n[q]\"A tome detailing the art of converting deathstones into an orb of corruption.\""},
[191607] = {name = "[q3]Book of Deathstones: Skeletal Artifact", additional_info = "Binds when picked up\nUnique\nRequires Level 60\n[q]\"A tome detailing the art of converting deathstones into a skeletal artifact.\""},
[191608] = {name = "[q3]Book of Deathstones: Rod of Necromancy", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 60\n[q]\"A tome detailing the art of converting deathstones into a rod of necromancy.\""},
[191609] = {name = "[q3]Book of Deathstones: Fungal Spore Cluster", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 60\n[q]\"A tome detailing the art of converting deathstones into a fungal spore cluster.\""},
[191610] = {name = "[q3]Book of Deathstones: Ritual Dagger", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 60\n[q]\"A tome detailing the art of converting deathstones into a ritual dagger.\""},
[191611] = {name = "[q4]Book of Deathstones: Failsafe Phylactery", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 60\n[q]\"A tome detailing the art of converting deathstones into a failsafe phylactery.\""},
[191612] = {name = "[q4]Book of Deathstones: Rune of Teleportation II", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 60\n[q]\"A tome detailing the art of converting deathstones into a rune of teleportation.\""},
[191613] = {name = "[q4]Book of Deathstones: Rune of Fortune", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 60\n[q]\"A tome detailing the art of converting deathstones into a rune of fortune.\""},
[191614] = {name = "[q4]Book of Deathstones: Skeletal Hitching Post", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 60\n[q]\"A tome detailing the art of converting deathstones into a skeletal hitching post.\""},
[191656] = {name = "[q4]Death's Essence", additional_info = "Binds when picked up\n[q2]<Right Click to Open>"},
[191660] = {name = "[q3]Thaddius' Lightning Bolts", additional_info = "Binds when picked up\nDuration: 7 days\n[q2]Use: Affix the bolts to your neck, applying a positive or negative charge at random that grants 1% increased damage and healing.\n\n This effect stacks while near allies who have a similar charge, and deals Nature damage to allies who have an opposite charge."},
[191661] = {name = "[q3]Monstrous Spider Fang", additional_info = "Binds when picked up\nDuration: 7 days\n[q2]Use: Pierce yourself with the fang, increasing movement speed, attack speed, and cast speed by 15% for 1 hour. (Proc chance: 5%, 30s cooldown)"},
[191664] = {name = "[q3]Book of Deathstones: Thaddius' Lightning Bolts", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 60\n[q]\"A tome detailing the art of converting deathstones into Thaddius' lightning bolts.\""},
[191666] = {name = "[q3]Book of Deathstones: Monstrous Spider Fang", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 60\n[q]\"A tome detailing the art of converting deathstones into a monstrous spider fang.\""},
[202251] = {name = "Bag of Pet Treats", additional_info = "Binds when picked up\n[q2]Use: Open the bag of treats and palm it into your target's pocket, increasing the damage of Beasts against this target by 20. (1 Min Cooldown)\nSell Price:"},
[202256] = {name = "[q2]Privateer's Ornate Pistol", additional_info = "Binds when picked up\n{Ranged} {Gun}\n{6 - 13 Damage} {Speed 1.90}\n(5.00 damage per second)\nDurability 35 / 35\nClasses: Rogue\n[q2]Equip: Gain the Quick Draw ability:\n\n\nDraw your ranged weapon and fire a quick shot at an enemy, causing normal ranged weapon damage and reducing the target's movement speed by 50% for 6 sec. Awards 1 combo point.\n\n Quick Draw benefits from all talents and effects that trigger from or modify Sinister Strike.\nSell Price:"},
[202641] = {name = "Mud-covered notebook", additional_info = "Binds when picked up\nThis Item Begins a Quest\nClasses: Rogue\n[q]\"This book is covered in mud, but has runes inscribed on its pages, and a short note in a some sort of slang.\""},
[203723] = {name = "Cutty's Note", additional_info = "Binds when picked up\nClasses: Rogue\n[q]\"A message written in thieves' cant\"\n[q2]<Right Click to Read>"},
[203726] = {name = "[q2]Cutty's Rune", additional_info = "Classes: Rogue"},
[203745] = {name = "[q2]Spell Notes: Ice Lance", additional_info = "Binds when picked up\nUnique\nClasses: Mage\nRequiresEngraving\n(1)\n\n[q2]Engrave your gloves with the Ice Lance rune:\n\n\nDeals [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 55 / 100 * ( 1 ) ] to [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 65 / 100 * ( 1 ) ] Frost damage to an enemy target. Causes 400% damage against Frozen targets.\n\n When your other frost spells deal damage to a non-player controlled target, they increase the target's damage taken from your next Ice Lance by 20%. This effect stacks up to 5 times and requires the Winter's Chill talent.\n[q]\"Teaches you a new Runecarving ability.\""},
[203746] = {name = "[q2]Spell Notes: Living Flame", additional_info = "Binds when picked up\nUnique\nClasses: Mage\nRequiresEngraving\n(1)\n\n[q2]Engrave your pants with the Living Flame rune:\n\n\nSummons a spellfire flame that moves toward the target, leaving a trail of spellfire. This trail deals [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 100 / 100] Spellfire damage every second to nearby enemies. Lasts 10 sec.\n[q]\"Teaches you a new Runecarving ability.\""},
[203747] = {name = "[q2]Spell Notes: Fingers of Frost", additional_info = "Binds when picked up\nUnique\nClasses: Mage\nRequiresEngraving\n(1)\n\n[q2]Engrave your chest or robe with the Fingers of Frost rune:\n\n\nGives your Chill effects a 25% chance to grant you the Fingers of Frost effect, which treats your next 2 spells cast as if the target were Frozen. Lasts 15 sec.\n[q]\"Teaches you a new Runecarving ability.\""},
[203748] = {name = "[q2]Spell Notes: Burnout", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Engrave your chest with the Burnout rune:\n\n\nIncreases your spell critical strike chance with all spells by 15%, but your non-periodic spell critical strikes now have an additional mana cost of 1% of your base mana.\n[q]\"Teaches you a new Engraving ability.\""},
[203749] = {name = "[q2]Spell Notes: Enlightenment", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Engrave your chest or robe with the Enlightenment rune:\n\n\nYou deal 10% more damage while you have more than 70% mana. While below 30% mana 10% of your mana regeneration continues while casting.\n[q]\"Teaches you a new Engraving ability.\""},
[203750] = {name = "Elwynn Treasure Map", additional_info = "Binds when picked up\nClasses: Rogue\n[q2]Use: Dig up treasure at the marked location (1 Min Cooldown)\n[q]\"West of ridgepoint tower. Near the stump behind the prowler den.\""},
[203751] = {name = "[q2]Spell Notes: CALE ENCI", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Use: Decipher the spell notes with a Comphrehension Primer to learn a new Engraving spell."},
[203752] = {name = "[q2]Spell Notes: MILEGIN VALF", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Use: Decipher the spell notes with a Comprehension Charm to learn a new Engraving spell."},
[203753] = {name = "[q2]Spell Notes: RING SEFF OSTROF", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Use: Decipher the spell notes with a Comprehension Charm to learn a new Engraving spell."},
[203754] = {name = "Archmage Antonidas: The Unabridged Autobiography", additional_info = "Binds when picked up\nUnique\n[q]\"Somewhat self-indulgent, but nevertheless a fine addition to any library's collection.\""},
[203755] = {name = "Archmage Theocritus's Research Journal", additional_info = "Unique\n[q]\"Research notes from the Tower of Azora. A fine addition to any library's collection.\""},
[203756] = {name = "[q2]Azora Apprentice Notes: Page 1", additional_info = "Binds when picked up\nUnique\n[q2]Use: Combine 6 Azora Apprentice Notes to create a new engraving recipe."},
[203784] = {name = "Top-Right Map Piece", additional_info = "[q2]Use: Combine with 3 other pieces to make the full map.\n[q]\"A torn piece of what seems to be a map...\""},
[203785] = {name = "Top-Left Map Piece", additional_info = "[q2]Use: Combine with 3 other pieces to make the full map.\n[q]\"A torn piece of what seems to be a map...\""},
[203786] = {name = "Bottom-Right Map Piece", additional_info = "[q2]Use: Combine with 3 other pieces to make the full map.\n[q]\"A torn piece of what seems to be a map...\""},
[203787] = {name = "Bottom-Left Map Piece", additional_info = "[q2]Use: Combine with 3 other pieces to make the full map.\n[q]\"A torn piece of what seems to be a map...\""},
[203960] = {name = "[q2]Azora Apprentice Notes: Page 2", additional_info = "Binds when picked up\nUnique\n[q2]Use: Combine 6 Azora Apprentice Notes to create a new engraving recipe."},
[203961] = {name = "[q2]Azora Apprentice Notes: Page 3", additional_info = "Binds when picked up\nUnique\n[q2]Use: Combine 6 Azora Apprentice Notes to create a new engraving recipe."},
[203962] = {name = "[q2]Azora Apprentice Notes: Page 4", additional_info = "Binds when picked up\nUnique\n[q2]Use: Combine 6 Azora Apprentice Notes to create a new engraving recipe."},
[203990] = {name = "[q2]Rune of Mutilation", additional_info = "Binds when picked up\nUnique\nClasses: Rogue\n[q2]Engrave your gloves with the Mutilate rune:\n\n\nInstantly attacks with both weapons for 95% weapon damage plus an additional [100 / 100 * (5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 95 / 100] with each weapon. Damage is increased by 20% against Poisoned targets. Awards 2 combo points.\n\n Mutilate benefits from all talents and effects that trigger from or modify Backstab unless otherwise specified.\n[q]\"Teaches you a new Engraving ability.\""},
[203991] = {name = "[q2]Rune of Quick Draw", additional_info = "Binds when picked up\nUnique\nClasses: Rogue\n[q2]Engrave your chest or robe with the Quick Draw rune:\n\n\nDraw your ranged weapon and fire a quick shot at an enemy, causing normal ranged weapon damage and reducing the target's movement speed by 50% for 6 sec. Awards 1 combo point.\n\n Quick Draw benefits from all talents and effects that trigger from or modify Sinister Strike.\n[q]\"Teaches you a new Engraving ability.\""},
[203992] = {name = "[q2]Rune of Trickery", additional_info = "Classes: Rogue\n[q]\"Teaches you a new Engraving ability.\""},
[203993] = {name = "[q2]Rune of Slaughter", additional_info = "Binds when picked up\nUnique\nClasses: Rogue\n[q2]Engrave your chest or robe with the Slaughter from the Shadows rune:\n\n\nReduces the Energy cost of your Backstab and Ambush abilities by 30, and increases the damage they deal to non-player controlled targets by 70%. [ Engrave Gloves - Mutilate : Does not apply to Mutilate / Does not apply to abilities learned from other runes.]\n[q]\"Teaches you a new Engraving ability.\""},
[203994] = {name = "[q2]Rune of Deadly Brew", additional_info = "Binds when picked up\nUnique\nClasses: Rogue\n[q2]Engrave your chest or robe with the Deadly Brew rune:\n\n\nGrants several improvements to your poisons:\n\n When you inflict any other poison on a target, you also inflict Deadly Poison.\n\n If your weapon does not have a poison applied, it has a chance to trigger Instant Poison as if Instant Poison were applied.\n\n Deadly Poison and Instant Poison now gain increased damage from your Attack Power.\n\n Your Deadly Poison can now be active on targets affected by another Rogue's Deadly Poison.\n[q]\"Teaches you a new Engraving ability.\""},
[204174] = {name = "[q2]Rune of Precision", additional_info = "Binds when picked up\nUnique\nClasses: Rogue\n[q2]Engrave your pants with the Between the Eyes rune:\n\n\nRanged Finishing move that causes damage per combo point, increased by Attack Power, and Stuns the target:\n\n 1 point:  [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60))] to [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60))] damage, 1 sec Stun\n 2 points: [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 2)] to [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 2)] damage, 2 sec Stun\n 3 points: [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 3)] to [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 3)] damage, 3 sec Stun\n 4 points: [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 4)] to [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 4)] damage, 4 sec Stun\n 5 points: [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 5)] to [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 5)] damage, 5 sec Stun\n\n Cooldown shared with Kidney Shot.\n[q]\"Teaches you a new Engraving ability.\""},
[204441] = {name = "[q2]Rune of Blood Frenzy", additional_info = "Binds when picked up\nUnique\nClasses: Warrior\n[q2]Engrave your chest with the Blood Frenzy rune:\n\n\nRend can now be used in Berserker stance, Rend's damage is increased by 100%, and Rend deals additional damage equal to 4% of your Attack Power each time it deals damage.\n[q]\"Teaches you a new Engraving ability.\""},
[204476] = {name = "Severed Kobold Head", additional_info = "Binds when picked up\nUnique\n[q]\"A grim trophy. May interest the right collector...\""},
[204477] = {name = "Severed Murloc Head", additional_info = "Binds when picked up\nUnique\n[q]\"A grim trophy. May interest the right collector...\""},
[204478] = {name = "Severed Gnoll Head", additional_info = "Binds when picked up\nUnique\n[q]\"A grim trophy. May interest the right collector...\""},
[204688] = {name = "Monster Hunter's First Rune Fragment", additional_info = "[q2]Use: Combine with 2 other pieces to make the full rune."},
[204689] = {name = "Monster Hunter's Second Rune Fragment", additional_info = "[q2]Use: Combine with 2 other pieces to make the full rune."},
[204690] = {name = "Monster Hunter's Third Rune Fragment", additional_info = "[q2]Use: Combine with 2 other pieces to make the full rune."},
[204703] = {name = "[q2]Rune of Devastate", additional_info = "Binds when picked up\nUnique\nClasses: Warrior\n[q2]Engrave your gloves with the Devastate rune:\n\n\nWhile you are in Defensive Stance and have a shield equipped, Sunder Armor also deals damage equal to 150% of your equipped weapon's damage per second, increased by 15% per application of Sunder Armor already on the target. Devastate damage deals a high amount of threat while you are in Defensive Stance.\n[q]\"Teaches you a new Engraving ability.\""},
[204716] = {name = "[q2]Rune of Frenzied Assault", additional_info = "Binds when picked up\nUnique\nClasses: Warrior\n[q2]Engrave your pants with the Frenzied Assault rune:\n\n\nWhile wielding 2-handed weapons, your attack speed is increased by 40% and your successful melee hits generate 2 additional Rage, or 4 additional Rage if they are critical hits.\n[q]\"Teaches you a new Engraving ability.\""},
[204795] = {name = "[q2]Rune of Shadowstrike", additional_info = "Binds when picked up\nUnique\nClasses: Rogue\n[q2]Engrave your gloves with the Shadowstrike rune:\n\n\nTeleport behind your target and strike, causing 150% weapon damage to the target. Must be stealthed. Awards 1 combo point.\n[q]\"Teaches you a new Engraving ability.\""},
[204806] = {name = "[q2]Rune of Victory Rush", additional_info = "Binds when picked up\nUnique\nClasses: Warrior\n[q2]Engrave your gloves with the Victory Rush rune:\n\n\nInstantly attack the target causing (1 + Attack Power * 45 / 100) damage and healing you for 30% of your maximum health. Only useable within 20 sec after you kill an enemy that yields experience or honor.\n[q]\"Teaches you a new Engraving ability.\""},
[204809] = {name = "[q2]Rune of Furious Thunder", additional_info = "Binds when picked up\nUnique\nClasses: Warrior\n[q2]Engrave your pants with the Furious Thunder rune:\n\n\nThunder Clap now increases the time between attacks by an additional 6%, can be used in any stance, deals 100% increased damage, and deals 75% increased threat.\n[q]\"Teaches you a new Engraving ability.\""},
[204864] = {name = "[q2]Azora Apprentice Notes", additional_info = "Binds when picked up\nUnique (6)\n[q2]Use: Combine 6 Azora Apprentice Notes to create a new engraving recipe."},
[204905] = {name = "Ominous Tome", additional_info = "Binds when picked up\nUnique\n[q2]Use: Summon Soboz\n[q]\"Bring the jaw of a wolf and the blood of a gnoll to the belly of the lamb. Then, begin the incantation.\""},
[204906] = {name = "Gnoll Blood", additional_info = "Unique\n[q]\"A reagent for use in a summoning ritual\""},
[204907] = {name = "Wolf Jawbone", additional_info = "Unique\n[q]\"A reagent for use in a summoning ritual\""},
[204910] = {name = "[q0]Monster - Trident, Naga (Gold)", additional_info = "Binds when picked up\n{Two-Hand} {Polearm}\n{2 - 4 Damage} {Speed 3.00}\n(1.00 damage per second)\nDurability 20 / 20\nSell Price:"},
[204912] = {name = "[q2]Rune of Grace", additional_info = "Binds when picked up\nUnique\nClasses: Warlock\n[q2]Engrave your pants with the Demonic Grace rune:\n\n\nSurge with fel energy, increasing your pet's and your own dodge chance by 20%, and your chance to critically strike with all attacks by 20%. Lasts 6 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[205019] = {name = "Tainted Soul Shard", additional_info = "Binds when picked up\nUnique"},
[205020] = {name = "Pure Soul Shard", additional_info = "Binds when picked up\nUnique"},
[205022] = {name = "[q2]Rune of Soul Siphon", additional_info = "Binds when picked up\nUnique\nClasses: Warlock\n[q2]Engrave your cloak with the Soul Siphon rune:\n\n\nCauses your Drain Soul to to deal damage 3 times faster and increases the amount drained by your Drain Life and Drain Soul spells by an additional 6% for each of your Warlock Shadow effects afflicting the target, up to a maximum of 18% additional effect. When Drain Soul is cast on a target below 20% health, it instead gains 50% per effect, up to a maximum of 150%. In addition, your Drain Soul can now trigger your Nightfall talent.\n[q]\"Teaches you a new Engraving ability.\""},
[205181] = {name = "Unidentified Artifact", additional_info = "Binds when picked up\nUnique\n[q]\"Some esoteric magical object. A more experienced Warlock could probably tell you more.\""},
[205182] = {name = "Powerless Artifact", additional_info = "Binds when picked up\nUnique\n[q2]Use: Offer your blood to power the artifact."},
[205183] = {name = "Fel-Powered Artifact", additional_info = "Binds when picked up\nUnique"},
[205184] = {name = "Acolyte's Note", additional_info = "Binds when picked up\nUnique\n[q2]<Right Click to Read>"},
[205215] = {name = "[q2]Rune of Tactics", additional_info = "Binds when picked up\nUnique\nClasses: Warlock\n[q2]Engrave your chest or robe with the Demonic Tactics rune:\n\n\nIncreases the melee and spell critical strike chance of you and your pet by 10%.\n[q]\"Teaches you a new Engraving ability.\""},
[205218] = {name = "[q2]Libram of Discovery", additional_info = "Binds when picked up\nUnique\n{Relic} {Libram}\nClasses: Paladin\nRequires Level 5\n[q2]Engrave your cloak with the Soul Siphon rune:\n\n\nCauses your Drain Soul to to deal damage 3 times faster and increases the amount drained by your Drain Life and Drain Soul spells by an additional 6% for each of your Warlock Shadow effects afflicting the target, up to a maximum of 18% additional effect. When Drain Soul is cast on a target below 20% health, it instead gains 50% per effect, up to a maximum of 150%. In addition, your Drain Soul can now trigger your Nightfall talent.\n[q]\"Achieve a state of Inspiration by slaying 5 foes, then use to learn a new ability.\""},
[205228] = {name = "[q2]Rune of Chaos Bolt", additional_info = "Binds when picked up\nUnique\nClasses: Warlock\n[q2]Engrave your gloves with the Chaos Bolt rune:\n\n\nSends a bolt of chaotic fire at the enemy, dealing [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 522 / 100] to [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 662 / 100] Chaos damage. Chaos Bolt always hits, cannot be resisted, and its knowledge causes all your Fire spells to pierce through absorption effects. Chaos Bolt gains a high chance to be resisted when used against monsters 4 or more levels above your level.\n[q]\"Teaches you a new Engraving ability.\""},
[205230] = {name = "[q2]Rune of Haunting", additional_info = "Binds when picked up\nUnique\nClasses: Warlock\n[q2]Engrave your gloves with the Haunt rune:\n\n\nUnleash a ghostly soul on an enemy, dealing [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 251 / 100] to [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 295 / 100] damage, and increasing all Shadow damage over time you deal to that target by 40% for 15 sec. When the Haunt ends or is dispelled, you will be healed for all the damage it dealt to your target.\n[q]\"Teaches you a new Engraving ability.\""},
[205364] = {name = "Acolyte's Knapsack", additional_info = "Binds when picked up\nUnique\nClasses: Warlock\n[q2]<Right Click to Open>"},
[205420] = {name = "[q2]Libram of Judgement", additional_info = "Binds when picked up\nUnique\n{Relic} {Libram}\nClasses: Paladin\n[q2]Engrave your gloves with the Crusader Strike rune:\n\n\nAn instant strike that causes 75% weapon damage as Holy and regenerates 5% of your maximum mana. The duration of all Judgement effects on the target is refreshed to 30 sec.\n[q]\"Learn a new ability after unleashing 10 seals onto your enemies\""},
[205683] = {name = "[q2]Rune of Rebuke", additional_info = "Binds when picked up\nUnique\nClasses: Paladin\n[q2]Engrave your pants with the Rebuke\n rune:\n\n\nInterrupts spellcasting and prevents any spell in that school from being cast for 3 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[205685] = {name = "[q2]Rune of Aegis", additional_info = "Binds when picked up\nUnique\nClasses: Paladin\n[q2]Engrave your chest with the Aegis rune:\n\n\nIncreases your block value by 30% and modifies your Redoubt talent. Redoubt now also has a 10% chance to trigger from any melee or ranged attack against you, and always triggers when you deal a melee critical strike. In addition, your Reckoning talent gains a 2% chance per talent point to trigger from any melee or ranged attack against you.\n[q]\"Teaches you a new Engraving ability.\""},
[205863] = {name = "Corrupted Libram", additional_info = "Classes: Paladin"},
[205864] = {name = "Charred Note", additional_info = "Binds when picked up\nUnique\nClasses: Paladin\n[q2]<Right Click to Read>"},
[205897] = {name = "[q2]Rune of Divine Light", additional_info = "Binds when picked up\nUnique\nClasses: Paladin\n[q2]Engrave your cloak with the Divine Light rune:\n\n\nHeals a friendly target for [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 355 / 100] to [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 393 / 100]. 50% of any excess healing on the target is converted into an absorption shield that lasts 15 sec. Multiple casts of Divine Light do not accumulate this shield.\n\n Divine Light benefits from all talents and effects that trigger from or modify Holy Light.\n[q]\"Teaches you a new Engraving ability.\""},
[205905] = {name = "[q2]Memory of a Devout Champion", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Engrave your chest or robe with the Twisted Faith rune:\n\n\nMind Flay and Mind Blast deal 50% increased damage to targets afflicted with your Shadow Word: Pain.\n\n[q2]Use: Focus on the Memory to learn a new spell. Requires a mind cleared by meditating on the spiritual mysteries of Azeroth."},
[205932] = {name = "[q2]Prophecy of a King's Demise", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Engrave your gloves with the Shadow Word: Death rune:\n\n\nA word of dark binding that inflicts [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 320 / 100] to [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 372 / 100] Shadow damage to the target. If the target is not killed by Shadow Word: Death, the caster takes damage equal to 50% of the damage attempted against the target.\n\n[q2]Use: Focus on the Prophecy to learn a new spell. Requires a mind focused by meditating on two spiritual mysteries of Azeroth."},
[205940] = {name = "[q2]Memory of a Dark Purpose", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Engrave your boots with the Void Plague rune:\n\n\nAfflicts the target with a disease that causes [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 129 / 100 * 6] Shadow damage over 18 sec.\n\n[q2]Use: Focus on the Memory to learn a new spell. Requires a mind cleared by meditating on the spiritual mysteries of Azeroth."},
[205942] = {name = "Chimaeric Epiphany", additional_info = "[q2]Engrave your pants with the Prayer of Mending rune:\n\n\nPlaces a spell on the target that heals them for [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 74 / 100] the next time they take damage or receive healing. When the heal occurs, Prayer of Mending jumps to a party or raid member within 20 yards. Jumps up to 5 times and lasts 30 sec after each jump. This spell can only be placed on one target at a time."},
[205943] = {name = "Prophecy of a Desecrated Citadel", additional_info = "Unique\n[q2]Engrave your pants with the Homunculi rune:\n\n\nBreak off splinters of your soul to animate 3 miniature copies of yourself that attempt to attack your current target with a mace, sword, and axe, reducing the attack speed, attack power, and armor respectively of any target they hit.\n\n[q2]Use: Focus on the Prophecy to learn a new spell. Requires a mind focused by meditating on two spiritual mysteries of Azeroth."},
[205944] = {name = "[q2]Reciprocal Epiphany", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Engrave your pants with the Prayer of Mending rune:\n\n\nPlaces a spell on the target that heals them for [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 74 / 100] the next time they take damage or receive healing. When the heal occurs, Prayer of Mending jumps to a party or raid member within 20 yards. Jumps up to 5 times and lasts 30 sec after each jump. This spell can only be placed on one target at a time.\n[q]\"Learn a new Engraving ability.\""},
[205945] = {name = "[q2]Memory of an Imprisoned Savior", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Engrave your pants with the Shared Pain rune:\n\n\nYour Shadow Word: Pain now also afflicts up to 2 additional nearby targets within 15 yards.\n\n[q2]Use: Focus on the Memory to learn a new spell. Requires a mind cleared by meditating on the spiritual mysteries of Azeroth."},
[205946] = {name = "[q2]Memory of a Leader's Betrayal", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Engrave your boots with the Pain Suppression rune:\n\n\nInstantly reduces all damage taken by a friendly target by 40% and increases resistance to Dispel mechanics by 65% for 8 sec.\n\n[q2]Use: Focus on the Memory to learn a new spell. Requires a mind cleared by meditating on the spiritual mysteries of Azeroth."},
[205947] = {name = "[q2]Prophecy of a Desecrated Citadel", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Engrave your pants with the Homunculi rune:\n\n\nBreak off splinters of your soul to animate 3 miniature copies of yourself that attempt to attack your current target with a mace, sword, and axe, reducing the attack speed, attack power, and armor respectively of any target they hit.\n\n[q2]Use: Focus on the Prophecy to learn a new spell. Requires a mind focused by meditating on two spiritual mysteries of Azeroth."},
[205948] = {name = "Anodyne Epiphany", additional_info = "[q2]Engrave your cloak with the Vampiric Touch rune:\n\n\nApplies your Vampiric Embrace talent to your target, causes [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 65 / 100 * 5] Shadow damage over 15 sec to your target, and causes all party members to gain mana equal to 2% of any Shadow spell damage you deal to the target."},
[205949] = {name = "Manifold Epiphany", additional_info = "Classes: Priest\n[q2]Engrave your gloves with the Circle of Healing rune:\n\n\nHeals all of target player's party members within 43.5 yards of target player for [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 130 / 100] to [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 144 / 100].\n[q]\"Teaches you a new Engraving ability.\""},
[205950] = {name = "[q2]Tenebrous Epiphany", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Engrave your gloves with the Mind Sear rune:\n\n\nCauses an explosion of shadow magic damaging the enemy target and other nearby enemies, causing [70 / 100 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60)] to [78 / 100 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60)] Shadow damage every 1 sec for 6 sec to all enemies within 10 yards of the target.\n[q]\"Learn a new Engraving ability.\""},
[205951] = {name = "[q2]Memory of a Troubled Acolyte", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Engrave your gloves with the Penance rune:\n\n\nLaunches a volley of holy light at the target, causing [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 128 / 100] Holy damage to an enemy, or [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 85 / 100] healing to an ally, instantly and every 1 sec for 2 sec.\n\n[q2]Use: Focus on the Memory to learn a new spell. Requires a mind cleared by meditating on the spiritual mysteries of Azeroth."},
[205952] = {name = "Memory of a Shattered World", additional_info = "[q2]Use: Focus on the Memory to learn a new spell. Requires a mind cleared by meditating on the spiritual mysteries of Azeroth."},
[205953] = {name = "[q2]Prophecy of a Broken Vow", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Engrave your belt with the Mind Spike rune:\n\n\nBlasts the target for [122 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] to [142 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] Shadowfrost damage, and increases the critical strike chance of your next Mind Blast on the target by 30%, stacking up to 3 times.\n\n[q2]Use: Focus on the Prophecy to learn a new spell. Requires a mind focused by meditating on two spiritual mysteries of Azeroth."},
[205961] = {name = "Mulgore Bird Meat", additional_info = "Unique\n[q2]Use: Place as bait near a mountain cat's dwelling."},
[205979] = {name = "[q2]Rune of Flanking", additional_info = "Binds when picked up\nUnique\nClasses: Hunter\n[q2]Engrave your pants with the Flanking Strike rune:\n\n\nYou and your pet deal simultaneous instant 100% melee damage. Afterward, you deal 8% increased damage for 10 sec, stacking up to 3 times. Your pet's Basic attacks have a 50% chance to reset the cooldown on Flanking Strike.\n[q]\"Teaches you a new Engraving ability.\""},
[205995] = {name = "Prairie Dog Musk", additional_info = "Classes: Hunter\n[q2]Use: Your Tame Beast ability also works on prairie dogs (as companion pet) (10 Min Cooldown)"},
[206032] = {name = "[q2]Rune of Carve", additional_info = "Binds when picked up\nUnique\nClasses: Hunter\n[q2]Engrave your gloves with the Carve rune:\n\n\nA sweeping attack that strikes all enemies in front of you with your melee weapons for 65% weapon damage. Your primary target takes 50% increased damage.\n[q]\"Teaches you a new Engraving ability.\""},
[206155] = {name = "[q2]Rune of Marksmanship", additional_info = "Binds when picked up\nUnique\nClasses: Hunter\n[q2]Engrave your chest or robe with the Master Marksman rune:\n\n\nIncreases your critical strike chance by 5%, and reduces the Mana cost of all your Shot abilities by 25%.\n[q]\"Teaches you a new Engraving ability.\""},
[206157] = {name = "Seaforium Mining Charge", additional_info = "Quest Item\nUnique (5)"},
[206159] = {name = "Venture Co Disguise", additional_info = "Quest Item\n[q]\"It doesn't seem like much of a disguise...\""},
[206168] = {name = "[q2]Rune of the Chimera", additional_info = "Binds when picked up\nUnique\nClasses: Hunter\n[q2]Engrave your gloves with the Chimera Shot rune:\n\n\nYou deal 135% weapon damage, refreshing the current Sting on your target and triggering an effect:\n\n Serpent Sting - Instantly deals 48% of the damage done by your Serpent Sting.\n\n Viper Sting - Instantly restores mana to you equal to 60% of the total amount drained by your Viper Sting.\n\n Scorpid Sting - Attempts to Disarm the target for 10 sec. This effect cannot occur more than once per 1 minute.\n[q]\"Teaches you a new Engraving ability.\""},
[206169] = {name = "[q2]Rune of Explosive Shot", additional_info = "Binds when picked up\nUnique\nClasses: Hunter\n[q2]Engrave your gloves with the Explosive Shot rune:\n\n\nYou fire an explosive charge into the enemy target, dealing [Ranged Attack Power * 0.039 + 62 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)]-[Ranged Attack Power * 0.039 + 94 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] Fire damage to all enemies within 8 yards. The charge will deal damage again every second for an additional 2 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[206170] = {name = "Windfury Cone", additional_info = "Quest Item"},
[206175] = {name = "Pine Salve", additional_info = "Quest Item\nUnique"},
[206176] = {name = "Mortar and Pestle", additional_info = "Quest Item\nUnique\n[q2]Use: Grind 8 Windfury Cones together to create a venomous weapon salve. In theory."},
[206177] = {name = "Pine Nut Butter", additional_info = "Binds when picked up\n[q2]Use: Restores 61.2 health over 18 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 2 Stamina and Spirit for 15 min.\nSell Price:"},
[206264] = {name = "[q2]Rune of Inspiration", additional_info = "Binds when picked up\nUnique\nClasses: Paladin\n[q2]Engrave your pants with the Inspiration Exemplar rune:\n\n\nYour inspiring presence periodically dispels Fear and Sleep effects on nearby party members.\n[q]\"Teaches you a new Engraving ability.\""},
[206344] = {name = "Knife Set", additional_info = "Quest Item\nUnique\n[q2]Use: Attempt to fillet a Raw Brilliant Smallfish."},
[206345] = {name = "Fish Chunks", additional_info = "Quest Item\nUnique"},
[206376] = {name = "[q2]Bulwark Icon", additional_info = "Binds when picked up\nUnique\n{Relic} {Totem}\nClasses: Shaman\nRequires Level 3\n[q2]Engrave your chest or robe with the Shield Mastery rune:\n\n\nEach time you Block, you regenerate mana equal to 8% of your maximum mana and you gain Armor equal to 30% of your shield's armor value, stacking up to 5 times. You also always gain 10% increased chance to Block and 15% increased Block value.\n\n In addition, each time you use a Shock ability, you gain 4 Spell Damage for each point of your defense skill beyond ( 60 * 5). Lasts 15 sec.\n[q]\"Learn a new ability after hitting enemies 25 times with Rockbiter Weapon.\""},
[206381] = {name = "[q2]Dyadic Icon", additional_info = "Binds when picked up\nUnique\n{Relic} {Totem}\nClasses: Shaman\n[q2]Engrave your chest or robe with the Overload rune:\n\n\nGives your Lightning Bolt, Chain Lightning, Chain Heal, Healing Wave, and Lava Burst spells a 60% chance to cast a second, similar spell on the same target at no additional cost that causes half damage or healing and no threat.\n[q]\"Learn a new ability after receiving Nature damage 10 times.\""},
[206382] = {name = "[q2]Tempest Icon", additional_info = "Binds when picked up\nUnique\n{Relic} {Totem}\nClasses: Shaman\n[q2]Engrave your gloves with the Water Shield rune:\n\n\nThe caster is surrounded by 3 globes of water, granting 1% of your maximum mana per 5 sec. When a spell, melee or ranged attack hits the caster, 4% of maximum mana is restored to the caster. This expends one water globe. Only one globe will activate every few seconds. Lasts 10 min. Only one Elemental Shield can be active on the Shaman at any one time.\n[q]\"Learn a new ability after hitting 10 non-player enemies with 3 different elements (Nature, Frost, Fire).\""},
[206383] = {name = "[q2]Lithic Icon", additional_info = "Binds when picked up\nUnique\n{Relic} {Totem}\nClasses: Shaman\nRequires Level 3\n[q2]Engrave your pants with the Earth Shield rune:\n\n\nProtects the target with an earthen shield, reducing casting or channeling time lost when damaged by 30% and causing attacks to heal the shielded target for [28 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) / 100]. This effect can only occur once every few seconds. 9 charges. Lasts 10 min. Earth Shield can only be placed on one target at a time.\n[q]\"Learn a new ability after blocking 20 attacks with your shield.\""},
[206384] = {name = "[q2]Astral Icon", additional_info = "Binds when picked up\nUnique\n{Relic} {Totem}\nClasses: Shaman\nRequires Level 3\n[q]\"Learn a new ability after hitting enemies 25 times with Rockbiter Weapon.\""},
[206385] = {name = "[q2]Clastic Icon", additional_info = "Binds when picked up\nUnique\n{Relic} {Totem}\nClasses: Shaman\nRequires Level 3\n[q2]Engrave your pants with the Way of Earth rune:\n\n\nWhile Rockbiter Weapon is active on your main hand weapon and you have a shield equipped, you deal 65% increased threat, gain 25% increased health, take 10% reduced damage, gain 6% reduced chance to be critically hit by melee attacks, and Earth Shock taunts targets to attack you and has a separate cooldown from other Shock spells but has its range reduced to melee range. However, the range of your Lightning Bolt, Chain Lightning, Chain Heal, Healing Wave, and Lava Burst spells is reduced by 20 yards.\n[q]\"Learn a new ability after defeating 20 enemies with Earth Shock.\""},
[206386] = {name = "[q2]Galvanic Icon", additional_info = "Binds when picked up\nUnique\n{Relic} {Totem}\nClasses: Shaman\n[q2]Engrave your chest or robe with the Shield Mastery rune:\n\n\nEach time you Block, you regenerate mana equal to 8% of your maximum mana and you gain Armor equal to 30% of your shield's armor value, stacking up to 5 times. You also always gain 10% increased chance to Block and 15% increased Block value.\n\n In addition, each time you use a Shock ability, you gain 4 Spell Damage for each point of your defense skill beyond ( 60 * 5). Lasts 15 sec.\n[q]\"Learn a new ability after defeating enemies 10 times with Lightning Bolt.\""},
[206387] = {name = "[q2]Kajaric Icon", additional_info = "Binds when picked up\nUnique\n{Relic} {Totem}\nClasses: Shaman\n[q2]Engrave your gloves with the Lava Burst rune:\n\n\nYou hurl molten lava at the target, dealing [469 / 100 * (7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60)] to [605 / 100 * (7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60)] Fire damage. If your Flame Shock is on the target, Lava Burst will deal a critical strike.\n[q]\"Learn a new ability after taking damage from lava 5 times. (Reduces damage from some sources of lava)\""},
[206388] = {name = "[q2]Sulfurous Icon", additional_info = "Binds when picked up\nUnique\n{Relic} {Totem}\nClasses: Shaman\n[q2]Engrave your gloves with the Molten Blast rune:\n\n\nBlast up to 10 enemies in a cone in front of you for [(7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60) * 72 / 100 + 5 / 100 * Attack Power] to [(7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60) * 108 / 100 + 5 / 100 * Attack Power] Fire damage. This ability generates a high amount of threat. Flame Shock periodic damage has a 10% chance to reset the cooldown on Molten Blast.\n[q]\"Learn a new ability after defeating 10 enemies with Earth Shock.\""},
[206389] = {name = "[q2]Brimstone Icon", additional_info = "Binds when picked up\nUnique\n{Relic} {Totem}\nClasses: Shaman\nRequires Level 3\n[q2]Engrave your belt with the Fire Nova rune:\n\n\nYour Fire Nova Totem spell is replaced with Fire Nova, which causes your current Fire totem to emit damage at its location.\n[q]\"Learn a new ability after hitting enemies 25 times with Rockbiter Weapon.\""},
[206390] = {name = "[q2]Ichthyan Icon", additional_info = "Binds when picked up\nUnique\n{Relic} {Totem}\nClasses: Shaman\nRequires Level 3\n[q2]Engrave your gloves with the Water Shield rune:\n\n\nThe caster is surrounded by 3 globes of water, granting 1% of your maximum mana per 5 sec. When a spell, melee or ranged attack hits the caster, 4% of maximum mana is restored to the caster. This expends one water globe. Only one globe will activate every few seconds. Lasts 10 min. Only one Elemental Shield can be active on the Shaman at any one time.\n[q]\"Learn a new ability after hitting enemies 25 times with Rockbiter Weapon.\""},
[206391] = {name = "[q2]Syzygic Icon", additional_info = "Binds when picked up\nUnique\n{Relic} {Totem}\nClasses: Shaman\nRequires Level 3\n[q2]Engrave your bracers with the Riptide\n rune:\n\n\nHeals a friendly target for [57 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)] to [63 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)] and another [5 * 12 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)] over 15 sec. Your Chain Heals cast on that primary target within 15 sec will increase the amount of the Chain Heal by 25%. This spell also triggers Ancestral Awakening.\n[q]\"Learn a new ability after hitting enemies 25 times with Rockbiter Weapon.\""},
[206466] = {name = "Prairie Crown", additional_info = "[q2]Use: Awaken a spirit of the plains"},
[206469] = {name = "Prairie Flower", additional_info = "Classes: Druid\n[q2]Use: Combine 3 Prairie Flowers to make a crown."},
[206954] = {name = "[q2]Idol of Ursine Rage", additional_info = "Binds when picked up\nUnique\n{Relic} {Idol}\nClasses: Druid\n[q2]Engrave your gloves with the Mangle rune:\n\n\nMangle the target for 160% normal damage and cause the target to take 30% additional damage from Bleed effects and Shred for 1 min. This ability benefits from and triggers all effects associated with Claw and Maul.\n\n Hitting a target with Mangle (Bear) also grants you 4 Attack Power for each point of your defense skill beyond ( 60 * 5). Lasts 15 sec.\n[q]\"Learn a new ability after keeping your rage in Bear Form at 50 or higher for 60 seconds\""},
[206963] = {name = "[q2]Rune of Natural Potential", additional_info = "Binds when picked up\nUnique\nClasses: Druid\n[q2]Engrave your chest or robe with the Living Seed rune:\n\n\nWhen you critically heal your target with any non-periodic healing spell you plant a Living Seed on the target for 50% of the amount healed. The Living Seed will bloom the next time the target takes damage or receives non-periodic healing. Lasts 15 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[206966] = {name = "Satyrweed Bulb", additional_info = "Binds when picked up\nUnique\n[q]\"The seedling of an invasive plant species.\""},
[206970] = {name = "[q2]Rune of Life", additional_info = "Binds when picked up\nUnique\nClasses: Druid\n[q2]Engrave your pants with the Lifebloom rune:\n\nReduces the global cooldown on your Rejuvenation and Lifebloom abilities by 0.5 sec and you gain the Lifebloom ability:\n\n\nHeals the target for [4 / 100 * 7 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] over 7 sec. When Lifebloom completes its duration or is dispelled, the target instantly heals for [57 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] and the Druid regains half the cost of the spell. This effect can stack up to 3 times on the same target.\n[q]\"Teaches you a new Engraving ability.\""},
[206975] = {name = "Artifact Storage Key", additional_info = "Unique\n[q]\"Opens Artifact Storage chest\""},
[206985] = {name = "[q2]Echo of the Alpha", additional_info = "Binds when picked up\nUnique\nClasses: Shaman\nRequires Level 3\n\n[q2]Engrave your boots with the Spirit of the Alpha rune:\n\n\nInfuses the target with the spirit of an alpha wolf, increasing all threat generated by the target by 45% for 30 min. Limit 1 target. If cast on a target other than self, the Shaman also gains Loyal Beta, increasing Physical damage done by 5% and reducing all threat generated by 30% for 30 min. A target cannot have both Spirit of the Alpha and Loyal Beta at the same time.\n[q]\"Learn a new ability.\""},
[206989] = {name = "[q2]Rune of the Sun", additional_info = "Binds when picked up\nUnique\nClasses: Druid\n[q2]Engrave your gloves with the Sunfire rune:\n\n\nBurns the enemy for [130 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] to [152 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] Nature damage and then an additional [65 * 4 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] Nature damage over 12 sec.\n\n In addition, while in Bear Form, Cat Form, or Dire Bear Form, your Moonfire is replaced with Sunfire (Bear) or Sunfire (Cat). This spell benefits from and triggers all effects associated with Moonfire.\n\n Sunfire (Bear)\nBurns the enemy for [130 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] to [152 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] Nature damage and then an additional [65 * 4 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] Nature damage over 12 sec.\n\n Sunfire (Cat)\nBurns the enemy for [130 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] to [152 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] Nature damage and then an additional [65 * 4 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] Nature damage over 12 sec. Awards 1 combo point.\n[q]\"Teaches you a new Engraving ability.\""},
[206992] = {name = "[q2]Rune of Skull Bash", additional_info = "Binds when picked up\nUnique\nClasses: Druid\n[q2]Engrave your gloves with the Skull Bash rune:\n\n\nCharge to a target within 13 yards and bash the target's skull, interrupting spellcasting and preventing any spell in that school from being cast for 2 sec. Shares a cooldown with Feral Charge.\n[q]\"Teaches you a new Engraving ability.\""},
