[208183] = {name = "[q2]Apothecary Notes", additional_info = "Binds when picked up\nUnique (6)\n[q2]Use: Combine 6 Apothecary Notes to create a new engraving recipe."},
[208185] = {name = "The Apothecary's Metaphysical Primer", additional_info = "Unique\n[q]\"Elementary notes on arcane theory and spell research, compiled by Archmage Rotwick of the Royal Apothecary Society. A fine addition to any library's collection.\""},
