[208220] = {name = "Dun Morogh Treasure Map", additional_info = "Binds when picked up\nClasses: Rogue\n[q2]Use: Dig up treasure at the marked location (1 Min Cooldown)\n[q]\"Beneath the bridge from Kharanos to Ironforge.\""},
[208222] = {name = "[q3]Old Guard Retaliator", additional_info = "Binds when picked up\nUnique\n{Two-Hand} {Axe}\n{163 - 245 Damage} {Speed 3.90}\n(52.31 damage per second)\n+8 Strength\n+10 Agility\n+41 Stamina\nDurability 100 / 100\nClasses: Warrior\nRequires Level 55\n[q2]Equip: On landing a killing blow that grants experience or honor, your next attack will critically strike.\n[q]\"The previous owner immaculately cared for this weapon.\"\nSell Price:"},
[208223] = {name = "Acolyte's Knapsack", additional_info = "Binds when picked up\nUnique\nClasses: Warlock\n[q2]<Right Click to Open>"},
[208224] = {name = "Acolyte's Note", additional_info = "Binds when picked up\nUnique\n[q2]<Right Click to Read>"},
[208414] = {name = "[q2]Lunar Idol", additional_info = "Binds when picked up\nUnique\n{Relic} {Idol}\nClasses: Druid\n[q2]Engrave your chest or robe with the Fury of Stormrage rune:\n\n\nReduces the mana cost of Wrath by 100% and each time you deal damage with Wrath you have a 12% chance for your next cast of Healing Touch within 15 sec to be instant and castable in any shapeshift form. Allows Wrath to be cast while in Tree of Life form.\n[q]\"Defeat 6 creatures affected by your Moonfire, then use to learn a new ability.\""},
[208424] = {name = "[q4]Sun Shades", additional_info = "Binds when picked up\n{Head} {Cloth}\n17 Armor\nDurability 99 / 99\nRequires Astral Perfect Victory\n[q]\"Do not stare directly at bright objects.\"\nSell Price:"},
