[208605] = {name = "Teldrassil Treasure Map", additional_info = "Binds when picked up\nClasses: Rogue\n[q2]Use: Dig up treasure at the marked location (1 Min Cooldown)\n[q]\"The hollow stump of Rut'theran.\""},
