[208682] = {name = "Abandoned Snapjaw Egg", additional_info = "Binds when picked up\nUnique\nClasses: Druid\n[q]\"Needs a new home.\""},
[208687] = {name = "[q2]Rune of Lacerate", additional_info = "Binds when picked up\nUnique\nClasses: Druid\n[q2]Engrave your pants with the Lacerate\n rune:\n\n\nLacerates the enemy target, making them bleed for [(9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) * 20 / 100 * 5] damage over 15 sec plus 20% weapon damage per existing application of Lacerate on the target. Causes a high amount of threat. This effect stacks up to 5 times on the same target.\n[q]\"Teaches you a new Engraving ability.\""},
[208689] = {name = "[q2]Ferocious Idol", additional_info = "Binds when picked up\nUnique\n{Relic} {Idol}\nClasses: Druid\n[q2]Engrave your pants with the Savage Roar rune:\n\n\nFinishing move that increases physical damage done by 30% while in Cat Form. Lasts longer per combo point:\n 1 point : 14 seconds\n 2 points: 19 seconds\n 3 points: 24 seconds\n 4 points: 29 seconds\n 5 points: 34 seconds\n[q]\"Deal 20 instances of bleeding damage to humanoids, then use this idol to learn a new ability.\""},
[208701] = {name = "[q2]Rune of Beast Mastery", additional_info = "Binds when picked up\nUnique\nClasses: Hunter\n[q2]Engrave your chest or robe with the Beast Mastery rune:\n\n\nYour pet's damage and health are increased by 15%, and its Focus regeneration by 50%. In addition, your pet's Growl now also Taunts the target to attack it for 3 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[208739] = {name = "Horde Warbanner", additional_info = "Binds when picked up\nUnique\nClasses: Warrior\n[q]\"Plant this in the soil of your enemies\""},
[208741] = {name = "[q2]Rune of Endless Rage", additional_info = "Binds when picked up\nUnique\nClasses: Warrior\n[q2]Engrave your helm with the Endless Rage rune:\n\n\nYou generate 25% more Rage from all damage you deal.\n[q]\"Teaches you a new Engraving ability.\""},
[208743] = {name = "Soul of Greed", additional_info = "Binds when picked up\nUnique\nClasses: Warlock"},
[208744] = {name = "[q2]Rune of Shadowbolts", additional_info = "Binds when picked up\nUnique\nClasses: Warlock\n[q2]Engrave your gloves with the Shadow Bolt Volley rune:\n\n\nYour Shadow Bolt now strikes up to 5 targets within a chain distance of 10 yards, but for 30% reduced damage.\n[q]\"Teaches you a new Engraving ability.\""},
[208749] = {name = "Gnarlpine Stash Key", additional_info = "Unique\n[q]\"A tree branch is crudely carved upon the handle.\""},
[208750] = {name = "[q2]Rune of Channeling", additional_info = "Binds when picked up\nUnique\nClasses: Warlock\n[q2]Engrave your chest or robe with the Master Channeler rune:\n\n\nYour Drain Life is no longer channeled, lasts 15 sec with a 15 sec cooldown, costs 100% more mana, and heals you for 50% more each time it deals damage.\n[q]\"Teaches you a new Engraving ability.\""},
[208753] = {name = "[q2]Spell Notes: Regeneration", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Engrave your chest or robe with the Regeneration rune:\n\n\nHeals the target for [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 55 / 100 * 3] health over 3 sec and applies Temporal Beacon for 30 sec.\n\n Temporal Beacon\n\nRecords the subject's space-time position. 70% of all Arcane damage done by the caster will be converted to chronomantic healing on each of the caster's current Temporal Beacon targets. This healing is reduced by 50% on self, and also reduced by 80% when damage is done by Arcane spells that damage multiple targets.\n[q]\"Teaches you a new Engraving ability.\""},
[208754] = {name = "[q2]Spell Notes: TENGI RONEERA", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Use: Decipher the spell notes with a Comprehension Charm to learn a new Engraving spell."},
[208758] = {name = "[q2]Earthen Rune", additional_info = "Binds when picked up\nUnique\nClasses: Shaman\n[q2]Engrave your pants with the Way of Earth rune:\n\n\nWhile Rockbiter Weapon is active on your main hand weapon and you have a shield equipped, you deal 65% increased threat, gain 25% increased health, take 10% reduced damage, gain 6% reduced chance to be critically hit by melee attacks, and Earth Shock taunts targets to attack you and has a separate cooldown from other Shock spells but has its range reduced to melee range. However, the range of your Lightning Bolt, Chain Lightning, Chain Heal, Healing Wave, and Lava Burst spells is reduced by 20 yards.\n[q]\"Teaches you a new Engraving ability.\""},
[208760] = {name = "Glade Crown", additional_info = "[q2]Use: Awaken a spirit of the plains"},
[208764] = {name = "[q2]Rune of the Mind", additional_info = "Unique\nClasses: Priest\n[q2]Engrave your belt with the Mind Spike rune:\n\n\nBlasts the target for [122 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] to [142 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] Shadowfrost damage, and increases the critical strike chance of your next Mind Blast on the target by 30%, stacking up to 3 times."},
[208765] = {name = "[q2]Helping Hand", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q]\"The hand will open for a savior\""},
[208766] = {name = "[q2]Helping Hand", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q]\"The hand has opened for you\"\n[q2]<Right Click to Open>"},
[208767] = {name = "[q2]Rune of Mending", additional_info = "Unique\nClasses: Priest\n[q2]Engrave your pants with the Prayer of Mending rune:\n\n\nPlaces a spell on the target that heals them for [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 74 / 100] the next time they take damage or receive healing. When the heal occurs, Prayer of Mending jumps to a party or raid member within 20 yards. Jumps up to 5 times and lasts 30 sec after each jump. This spell can only be placed on one target at a time.\n[q]\"Teaches you a new Runecarving ability.\""},
[208768] = {name = "Buccaneer's Matchbox", additional_info = "Binds when picked up\nUnique\nClasses: Rogue\n[q]\"Used to ignite flammable materials\""},
[208771] = {name = "[q2]Rune of Blade Dance", additional_info = "Binds when picked up\nUnique\nClasses: Rogue\n[q2]Engrave your pants with the Blade Dance rune:\n\n\nFinishing move that increases your Parry chance by 10% and grants 4 Attack Power for each point of your defense skill beyond ( 60 * 5). Lasts longer per combo point:\n\n 1 point : 14 seconds\n 2 points: 18 seconds\n 3 points: 22 seconds\n 4 points: 26 seconds\n 5 points: 30 seconds\n[q]\"Teaches you a new Engraving ability.\""},
[208772] = {name = "[q2]Rune of Saber Slash", additional_info = "Binds when picked up\nUnique\nClasses: Rogue\n[q2]Engrave your gloves with the Saber Slash rune:\n\n\nViciously slash an enemy for 100% weapon damage, and cause the target to bleed for (Attack Power * 5 / 100) damage every 2 sec for 12 sec, stacking up to 3 times. Each stack also increases damage done by your Saber Slash and Sinister Strike by 50%. Awards 1 combo point.\n\n Saber Slash benefits from all talents and effects that trigger from or modify Sinister Strike.\n[q]\"Teaches you a new Engraving ability.\""},
[208773] = {name = "Fishing Harpoon", additional_info = "Binds when picked up\nClasses: Warrior , Hunter\n[q2]Use: Throw harpoon at target (40 yd. range)\n[q]\"A must-have for the aspiring shark hunter!\""},
[208777] = {name = "[q2]Rune of the Sniper", additional_info = "Binds when picked up\nUnique\nClasses: Hunter\n[q2]Engrave your pants with the Sniper Training rune:\n\n\nYour Shot abilities gain 2% increased critical strike chance while you have not moved for the last 2 sec, stacking every sec up to 5 times. At 2 or more stacks, your Aimed Shot becomes instant. While moving, you will lose 1 stack per sec.\n[q]\"Teaches you a new Engraving ability.\""},
[208778] = {name = "[q2]Rune of Quick Strike", additional_info = "Binds when picked up\nUnique\nClasses: Warrior\n[q2]Engrave your gloves with the Quick Strike rune:\n\n\nA reckless instant melee attack with your two-handed weapon dealing (Attack Power * 30 / 100) to (Attack Power * 40 / 100) physical damage. This ability benefits from and triggers all effects associated with Heroic Strike.\n[q]\"Teaches you a new Engraving ability.\""},
[208799] = {name = "[q2]Spell Notes: Living Bomb", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Engrave your gloves with the Living Bomb rune:\n\n\nThe target becomes a Living Bomb, taking [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 85 / 100 * 4] Fire damage over 12 sec. After 12 sec or when the spell is dispelled, the target explodes dealing [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 171 / 100] Fire damage to all enemies within 10 yards.\n\n Living Bomb benefits from all talents and effects that trigger from or modify Scorch.\n[q]\"Teaches you a new Engraving ability.\""},
[208800] = {name = "Baxtan: On Destructive Magics", additional_info = "Unique\n[q]\"The writings of a notable Goblin mage. A fine addition to any library's collection.\""},
[208823] = {name = "Offering Coin", additional_info = "Binds when picked up\nClasses: Priest\n[q2]Use: Toss into a nearby well to make a wish"},
[208828] = {name = "Memory of a Broken Vow", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Engrave your belt with the Mind Spike rune:\n\n\nBlasts the target for [122 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] to [142 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] Shadowfrost damage, and increases the critical strike chance of your next Mind Blast on the target by 30%, stacking up to 3 times.\n\n[q2]Use: Focus on the Memory to learn a new spell. Requires a mind cleared by meditating on the spiritual mysteries of Azeroth."},
[208833] = {name = "Malevolent Pie", additional_info = "Binds when picked up\nUnique\nClasses: Warlock\n[q]\"A pastry with a sinister energy.\""},
[208838] = {name = "[q2]Dark Iron Lockbox", additional_info = "Binds when picked up\nUnique\n[q0]Locked\n Requires Lockpicking (1)"},
[208843] = {name = "Battle Totem", additional_info = "Binds when picked up\nUnique\nClasses: Warrior\n[q2]Use: Challenge a Tauren to a duel\n[q]\"A symbol of hostility among members of the Horde\""},
[208847] = {name = "Skull-Shaped Geode", additional_info = "Binds when picked up\nUnique\nClasses: Warrior\n[q]\"Could likely be cracked open with a solid thump.\""},
[208848] = {name = "Cracked Skull-Shaped Geode", additional_info = "Binds when picked up\nUnique\nClasses: Warrior\n[q]\"The geode has been cracked open.\"\n[q2]<Right Click to Open>"},
[208849] = {name = "[q2]Libram of Blessings", additional_info = "Binds when picked up\nUnique\n{Relic} {Libram}\nClasses: Paladin\n[q2]Engrave your chest with the Hallowed Ground rune:\n\n\nYour Consecration now also heals party members within its area for 200% of Consecration's damage value.\n[q]\"Learn a new ability after giving blessings to 5 different players\""},
[208851] = {name = "[q2]Libram of Justice", additional_info = "Binds when picked up\nUnique\n{Relic} {Libram}\nClasses: Paladin\n[q2]Engrave your gloves with the Hand of Reckoning rune:\n\n\nTaunts the target to attack you, but has no effect if the target is already attacking you.\n\n While you know this ability, the threat bonus from Righteous Fury is increased to 80% and Righteous Fury causes you to gain mana when healed by others equal to 25% of the amount healed. Additionally, while Righteous Fury is active, damage which takes you below 35% health is reduced by 20%. Righteous Fury will remain active until cancelled.\n[q]\"Learn a new ability after slaying 10 enemies stunned by Hammer of Justice\""},
[208853] = {name = "[q2]Spell Notes: Brain Freeze", additional_info = "Binds when picked up\nUnique\nClasses: Mage\nRequiresEngraving\n(1)\n\n[q2]Engrave your boots with the Brain Freeze rune:\n\n\nYour Frost damage spells with chilling effects have a 20% chance to cause your next Fireball, Spellfrost Bolt, Balefire Bolt, or Frostfire Bolt spell to be instant cast and cost no mana.\n[q]\"Teaches you a new Runecarving ability.\""},
[208854] = {name = "[q2]Chewed Spell Notes", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Use: Decipher the spell notes with a Comprehension Charm to learn a new Engraving spell.\n[q]\"Trogg shamans are truly voracious readers.\""},
[208855] = {name = "Rainbow Fin Albacore Chum", additional_info = "Binds when picked up\nUnique\nClasses: Druid\n[q2]Use: Feed chum to target.\n[q]\"A tasty treat for lake monsters\""},
[208860] = {name = "Rumi of Gnomeregan: The Collected Works", additional_info = "Unique\n[q]\"The writings of a notable Gnome mage. A fine addition to any library's collection.\""},
[209027] = {name = "Crab Treats", additional_info = "Binds when picked up\nUnique\nClasses: Hunter , Druid\n[q2]Use: Feed treat to target.\n[q]\"The furbolgs catch young reef crawlers with these\""},
[209028] = {name = "[q2]Spell Notes: BIVOLG NIMB", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Use: Decipher the spell notes with a Comprehension Charm to learn a new Engraving spell."},
[209029] = {name = "Message from Emily", additional_info = "Binds when picked up\nClasses: Rogue\n[q2]<Right Click to Read>"},
[209030] = {name = "Equipment Stash Key", additional_info = "Binds when picked up\nUnique\nClasses: Rogue"},
[209031] = {name = "Discreet Envelope", additional_info = "Binds when picked up\nUnique\nClasses: Rogue\n[q2]<Right Click to Open>"},
[209041] = {name = "Magic Pumpkin Seeds", additional_info = "Binds when picked up\nUnique\nClasses: Druid\n[q2]Use: Plant Pumpkin Seeds\n[q]\"Needs special soil and food to grow.\""},
[209042] = {name = "Fishy Bonemeal", additional_info = "Binds when picked up\nUnique\nClasses: Druid\n[q]\"As nutritious as it is stinky! Makes for good fertilizer.\""},
[209043] = {name = "Fertile Soil Sample", additional_info = "Binds when picked up\nUnique\nClasses: Druid\n[q]\"Harvested by someone who really knows their dirt.\""},
[209045] = {name = "Soul of the Sea", additional_info = "Binds when picked up\nUnique\nClasses: Warrior , Warlock"},
[209047] = {name = "Gnarled Harpoon", additional_info = "Binds when picked up\nClasses: Warrior , Hunter\n[q2]Use: Throw harpoon at target (40 yd. range)\n[q]\"Only the blood of the largest thresher will slake its thirst\""},
[209056] = {name = "Spare Reaper Parts", additional_info = "Binds when picked up\nUnique\nClasses: Mage , Warlock\n[q2]Use: Combine spare reaper parts with an elemental core to create a prototype engine."},
