[209841] = {name = "Wild Magic Essence", additional_info = "Binds when picked up\nUnique\n[q2]Use: Imbue a Greater Magic Wand with wild magic."},
[209843] = {name = "Nar'thalas Almanac, Vol. 74", additional_info = "Binds when picked up\nUnique\n[q]\"Arcane research of the ancient quel'dorei. A fine addition to any library's collection.\""},
[209844] = {name = "The Dalaran Digest, Vol. 23", additional_info = "Binds when picked up\nUnique\n[q]\"Arcane research of the Kirin Tor. A fine addition to any library's collection.\""},
[209845] = {name = "Bewitchments and Glamours", additional_info = "Binds when picked up\nUnique\n[q]\"Spells for manipulation and deception. A fine addition to any library's collection.\""},
[209846] = {name = "Secrets of the Dreamers", additional_info = "Binds when picked up\nUnique\n[q]\"Observations and insights on the Emerald Dream. A fine addition to any library's collection.\""},
[209847] = {name = "Arcanic Systems Manual", additional_info = "Binds when picked up\nUnique\n[q]\"Poorly-organized troubleshooting tips for goblin technology. A fine addition to any library's collection.\""},
[209848] = {name = "Goaz Scrolls", additional_info = "Binds when picked up\nUnique\n[q]\"Written in lost Titan script, but nevertheless a fine addition to any library's collection.\""},
[209849] = {name = "Crimes Against Anatomy", additional_info = "Binds when picked up\nUnique\n[q]\"Written by Doctor Krastinov. A questionable addition to any library's collection.\""},
[209850] = {name = "Runes of the Sorcerer-Kings", additional_info = "Binds when picked up\nUnique\n[q]\"A relic of the mighty ogre empires of Draenor. A fine addition to any library's collection.\""},
[209851] = {name = "Fury of the Land", additional_info = "Binds when picked up\nUnique\n[q]\"Closely guarded shamanistic secrets of the Grimtotem clan. A fine addition to any library's collection.\""},
[209852] = {name = "[q2]Rune of Kill Command", additional_info = "Binds when picked up\nUnique\nClasses: Hunter\n[q2]Engrave your pants with the Kill Shot rune:\n\n\nYou attempt to finish off a wounded target, firing a ranged attack dealing 100% weapon damage plus [587 / 100 * 100 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)]. Kill Shot has no minimum range. Kill Shot's cooldown is reset if used on an enemy that has 20% or less health.\n[q]\"Teaches you a new Engraving ability.\""},
[209872] = {name = "Dragonslayer's Helm", additional_info = "Binds when picked up\nUnique"},
[209873] = {name = "Dragonslayer's Shield", additional_info = "Binds when picked up\nUnique"},
[209874] = {name = "Dragonslayer's Lance", additional_info = "Binds when picked up\nUnique"},
[210015] = {name = "[q2]Rune of Raging Blow", additional_info = "Binds when picked up\nUnique\nClasses: Warrior\n[q2]Engrave your chest with the Raging Blow rune:\n\n\nA ferocious strike that deals 115% weapon damage, but can only be used while Enrage, Berserker Rage, or Bloodrage is active. Each other melee ability used while Enrage, Berserker Rage, or Bloodrage is active reduces Raging Blow's remaining cooldown by 1 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[210026] = {name = "Symbol of the Third Owl", additional_info = "Binds when picked up\nUnique\nClasses: Druid\n[q]\"You have mastered the domain of the sea.\""},
[210043] = {name = "Symbol of the Second Owl", additional_info = "Binds when picked up\nUnique\nClasses: Druid\n[q]\"Agon's soul is finally at peace.\""},
[210044] = {name = "Symbol of the First Owl", additional_info = "Binds when picked up\nUnique\nClasses: Druid\n[q]\"The mark of a true guardian.\""},
[210045] = {name = "Shadeleaf", additional_info = "Quest Item"},
[210053] = {name = "Dire Wolf Paw", additional_info = "Quest Item"},
[210055] = {name = "Hillsbrad Human Bones", additional_info = "Quest Item"},
[210056] = {name = "Tincture of Waking Death", additional_info = "Quest Item"},
[210080] = {name = "Voodoo Offering", additional_info = "Quest Item\nUnique"},
[210137] = {name = "[q2]Rune of Wild Growth", additional_info = "Binds when picked up\nUnique\nClasses: Druid\n[q2]Engrave your gloves with the Wild Growth rune:\n\n\nHeals all of target player's party members within 43.5 yards of target player for [17 / 100 * 7 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] over 7 sec. The amount healed is applied quickly at first, and slows down as Wild Growth reaches its full duration.\n[q]\"Teaches you a new Engraving ability.\""},
[210138] = {name = "Dark Iron Ordinance", additional_info = nil},
[210146] = {name = "Shredder Turbocharger", additional_info = nil},
[210147] = {name = "Shredder Autosalvage Unit", additional_info = "[q2]Use: Salvage the wreckage of a shredder for spare parts."},
[210177] = {name = "Ataeric: On Arcane Curiosities", additional_info = "Unique\n[q]\"The writings of a notable Kirin Tor archmage. A fine addition to any library's collection.\""},
[210178] = {name = "[q2]Schematic: Shredder Autosalvage Unit", additional_info = "Requires Engineering (135)\nSell Price:"},
[210179] = {name = "[q2]Spell Notes: ILMEGAI SARRBES", additional_info = "Binds when picked up\nUnique\n[q2]Use: Translate the spell notes into a new runecarving recipe. Requires a reference for the author's shorthand."},
[210183] = {name = "Horn of Xelthos", additional_info = "Binds when picked up\nUnique\n[q]\"It emits a soft and haunting tone.\""},
[210186] = {name = "Breaching Charge", additional_info = "Binds when picked up\nUnique\n[q2]Use: Open a heavy gate, goblin-style!"},
[210187] = {name = "Venture Co. Work Order", additional_info = "Binds when picked up\nUnique"},
[210188] = {name = "[q0]Shredded Work Order", additional_info = "Binds when picked up\nUnique\n[q]\"Seems to have been damaged in combat.\""},
[210195] = {name = "[q2]Unbalanced Idol", additional_info = "Binds when picked up\nUnique\n{Relic} {Idol}\nClasses: Druid\nRequires Level 10\n[q2]Use: Balance the Powers of the Moon, Emerald Dream, and Wild to learn a new ability."},
[210209] = {name = "Twin Key", additional_info = "Binds when picked up\nUnique\nClasses: Rogue"},
[210210] = {name = "[q0]Grizzwerks Defense Industries Founder's Certificate", additional_info = "[q]\"The fine print makes it clear this certificate carries no stock value or legal entitlement. If you put your thumb over that part a vendor might buy it.\"\nSell Price:"},
[210212] = {name = "Brother's Half-Key", additional_info = "Binds when picked up\nUnique\n[q2]Use: Combine Brother and Sister Half-Keys."},
[210213] = {name = "Sister's Half-Key", additional_info = "Binds when picked up\nUnique\n[q2]Use: Combine Brother and Sister Half-Keys."},
[210229] = {name = "[q2]Rune of Mutilation", additional_info = "Binds when picked up\nUnique\nClasses: Rogue\n[q2]Engrave your gloves with the Mutilate rune:\n\n\nInstantly attacks with both weapons for 95% weapon damage plus an additional [100 / 100 * (5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 95 / 100] with each weapon. Damage is increased by 20% against Poisoned targets. Awards 2 combo points.\n\n Mutilate benefits from all talents and effects that trigger from or modify Backstab unless otherwise specified.\n[q]\"Teaches you a new Engraving ability.\""},
[210250] = {name = "Engraved Gold Ring", additional_info = "Binds when picked up\nUnique\nFinger\n[q]\"The engraving reads: While __ both __ kneel __ the __ in __ cemetery.\""},
[210251] = {name = "Engraved Silver Ring", additional_info = "Binds when picked up\nUnique\nFinger\n[q]\"The engraving reads: __ wearing __ rings __ before __ statue __ the __\""},
[210252] = {name = "[q2]Rune of Shiving", additional_info = "Binds when picked up\nUnique\nClasses: Rogue\n[q2]Engrave your gloves with the Cutthroat rune:\n\n\nYour Ambush, Backstab, and Garrote abilities no longer require you to be behind your target, and Backstab has a 15% chance to make your next Ambush within 10 sec not require you to be in Stealth.\n[q]\"Teaches you a new Engraving ability.\""},
[210253] = {name = "[q2]Rot Totem", additional_info = "Binds when picked up\nUnique\n[q2]Use: Call to the spirits of the elements.\n[q]\"A traditional totem... twisted and gnarled by dark magic, nearly unrecognizable to those that commune with the elements.\""},
[210322] = {name = "[q2]Rune of Venom", additional_info = "Binds when picked up\nUnique\nClasses: Rogue\n[q2]Engrave your pants with the Envenom rune:\n\n\nFinishing move that deals instant poison damage based on Deadly Poison doses on the target. Following the Envenom attack you have a 75% increased frequency of applying Instant Poison for 1 sec plus an additional 1 sec per combo point. One dose is activated per combo point:\n 1 dose: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) + Attack Power * 0.072] damage\n 2 doses: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 2 + Attack Power * 0.144] damage\n 3 doses: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 3 + Attack Power * 0.216] damage\n 4 doses: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 4 + Attack Power * 0.288] damage\n 5 doses: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 5 + Attack Power * 0.36] damage\n[q]\"Teaches you a new Engraving ability.\""},
[210323] = {name = "Safe Combination", additional_info = "Binds when picked up\nUnique\nClasses: Rogue\n[q]\"0-4-5-1\""},
[210329] = {name = "Hillsbrad Treasure Map", additional_info = "Binds when picked up\nUnique\nClasses: Rogue\n[q]\"Follow the river north; past the Alterac Mountains. What you seek lies beneath the falling rapids.\""},
[210330] = {name = "Hot Tip", additional_info = "Binds when picked up\nUnique\n[q]\"Good intel ain't cheap.\"\n[q2]<Right Click to Open>"},
[210410] = {name = "Freshwater Snapper Bait", additional_info = "Classes: Hunter\n[q2]Use: Toss bait. (5 Min Cooldown)\n[q]\"Throw some overboard to lure out a big one!\""},
[210499] = {name = "Marshroom", additional_info = "[q2]Use: Eat (at your own risk)."},
[210500] = {name = "[q2]Rune of the Stars", additional_info = "Binds when picked up\nUnique\nClasses: Druid\n[q2]Engrave your pants with the Starsurge rune:\n\n\nLaunch surging stellar energies that cause [248 / 100 * (9.183105 + 0.616405 * 1 + 0.028608 * 1)] to [304 / 100 * (9.183105 + 0.616405 * 1 + 0.028608 * 1)] Arcane damage, and increases the damage done by your next 1 Starfire cast by 80% for 15 sec.\n\n Starsurge benefits from and triggers most talents and effects that trigger or benefit from Wrath or Starfire.\n[q]\"Teaches you a new Engraving ability.\""},
[210534] = {name = "[q2]Idol of the Wild", additional_info = "Binds when picked up\nUnique\n{Relic} {Idol}\nClasses: Druid\n[q2]Engrave your chest or robe with the Wild Strikes rune:\n\n\nWhile you are in Cat Form, Bear Form, or Dire Bear Form, party or raid members within 100 yards gain increased combat ferocity. Each melee hit has a 20% chance of granting the attacker an extra attack with 20% additional Attack Power. No effect if the target is already benefitting from Windfury Totem.\n[q]\"Heal 10 different beasts, then use this idol to learn a new ability.\""},
[210568] = {name = "Decrepit Phylactery", additional_info = "Binds when picked up\nUnique\n[q]\"A heinous aura eminates from the artifact.\""},
[210569] = {name = "[q2]Rune of Flagellation", additional_info = "Binds when picked up\nUnique\nClasses: Warrior\n[q2]Engrave your chest with the Flagellation rune:\n\n\nYou gain Rage from Physical damage taken as if you were wearing no armor.\n[q]\"Teaches you a new Engraving ability.\""},
[210573] = {name = "[q2]Rune of Consuming Rage", additional_info = "Binds when picked up\nUnique\nClasses: Warrior\n[q2]Engrave your pants with the Consumed by Rage rune:\n\n\nEnrages you (activating abilities which require being Enraged) for 12 sec after you exceed 60 Rage. In addition, Whirlwind also strikes with off-hand melee weapons while you are Enraged.\n[q]\"Teaches you a new Engraving ability.\""},
[210589] = {name = "[q2]Echo of the Ancestors", additional_info = "Binds when picked up\nUnique\nClasses: Shaman\n[q2]Engrave your pants with the Ancestral Guidance rune:\n\n\nFor the next 10 sec, 25% of your damage is converted to healing on up to 3 nearby party members, and 100% of your healing is converted to damage on your most recent Flame Shock target.\n[q]\"Learn a new Engraving ability.\""},
[210596] = {name = "[q2]Rune of Cobra Strikes", additional_info = "Binds when picked up\nUnique\nClasses: Hunter\n[q2]Engrave your chest or robe with the Cobra Strikes rune:\n\n\nYour critical hits with Shot and Strike abilities and with Mongoose Bite cause your pet's next 2 special attacks to critically hit.\n[q]\"Teaches you a new Engraving ability.\""},
[210653] = {name = "[q2]Rune of Main Gauche", additional_info = "Binds when picked up\nUnique\nClasses: Rogue\n[q2]Engrave your gloves with the Main Gauche rune:\n\n\nInstantly strike with your off-hand weapon for normal off-hand weapon damage and increase your chance to parry by 100% for 5 sec or until you successfully parry. For 20 sec after using Main Gauche, Sinister Strike costs 20 less Energy, deals 50% more threat, grants stacks of Rolling with the Punches, and both Sinister Strike and Eviscerate deal 50% more damage. Awards 1 combo point.\n\n Main Gauche benefits from most talents and effects that trigger from or modify Sinister Strike. Main Gauche's effect will not discount or empower Main Gauche.\n[q]\"Teaches you a new Engraving ability.\""},
[210654] = {name = "[q2]Spell Notes: Rewind Time", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Engrave your bracers with the Rewind Time rune:\n\n\nYour current target with your Temporal Beacon instantly heals all damage taken over the last 5 seconds. Ineffective on targets that did not have a Temporal Beacon 5 seconds ago.\n[q]\"Teaches you a new Engraving ability.\""},
[210655] = {name = "[q2]Spell Notes: TERWEM DINI", additional_info = "Binds when picked up\nUnique\n[q2]Use: Decipher the spell notes with a Comprehension Charm to learn a new Engraving spell."},
[210665] = {name = "Mote of Torrential Rage", additional_info = "Binds when picked up\nUnique"},
[210667] = {name = "Mote of Infernal Rage", additional_info = "Binds when picked up\nUnique"},
[210668] = {name = "Mote of Seismic Rage", additional_info = "Binds when picked up\nUnique"},
[210708] = {name = "Elixir of Coalesced Regret", additional_info = "Requires Level 20\n\n[q2]Use: Allows the imbiber to speak with the corpse of an individual with unfinished business in the mortal world. Also may cure indigestion. (3 Sec Cooldown)\nSell Price:"},
[210709] = {name = "[q2]Recipe: Elixir of Coalesced Regret", additional_info = "Requires Alchemy (90)\n\n[q2]Use: Teaches you how to make an Elixir of Coalesced Regret.\nSell Price:\nElixir of Coalesced Regret\nRequires Level 20\n\n[q2]Use: Allows the imbiber to speak with the corpse of an individual with unfinished business in the mortal world. Also may cure indigestion. (3 Sec Cooldown)\nSell Price:\nRequires Stranglekelp (5), Leaded Vial , Grave Moss (5), Soul Dust"},
[210712] = {name = "Elixir of Insight", additional_info = "Binds when picked up\n[q2]Use: Behold a vision at Je'neu's bonfire."},
[210713] = {name = "Tortured Soul", additional_info = "Binds when picked up\nUnique\nClasses: Warlock\n[q2]Use: Make an Offering of Blood to release this Tortured Soul."},
[210724] = {name = "Hirzek's Staff", additional_info = "Binds when picked up"},
[210746] = {name = "[q2]Rune of Earth Shield", additional_info = "Binds when picked up\nUnique\nClasses: Shaman\n[q2]Engrave your pants with the Earth Shield rune:\n\n\nProtects the target with an earthen shield, reducing casting or channeling time lost when damaged by 30% and causing attacks to heal the shielded target for [28 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) / 100]. This effect can only occur once every few seconds. 9 charges. Lasts 10 min. Earth Shield can only be placed on one target at a time.\n[q]\"Teaches you a new Engraving ability.\""},
[210763] = {name = "Bough of Altek", additional_info = "Binds when picked up\nUnique\n[q]\"A splintered fragment of power. It appears this was once half of a great weapon.\""},
[210765] = {name = "Orb of Des", additional_info = "Binds when picked up\nUnique\n[q]\"Flames and dark magic swirl through the orb, mesmerizing yet deeply concerning. It appears this was once half of a great weapon.\""},
[210771] = {name = "[q2]Waylaid Supplies: Copper Bars", additional_info = "Binds when picked up\nUnique: Waylaid Shipment (12)\n[q2]Use: Add 20 Copper Bars to complete the shipment.\nSell Price:"},
[210772] = {name = "[q2]Supply Shipment: Copper Bars", additional_info = "Binds when picked up\nUnique: Supply Shipment (1)\n[q]\"Deliver to a supply officer for a substantial reward.\""},
[210779] = {name = "[q2]Plans: Mantle of the Second War", additional_info = "Binds when picked up\nRequires Blacksmithing (150)\n\n[q2]Use: Teaches you how to craft a Mantle of the Second War.\nSell Price:\n[q3]Mantle of the Second War\nBinds when equipped\n{Shoulder} {Mail}\n163 Armor\n+8 Stamina\nDurability 70 / 70\nRequires Level 25\n[q2]Equip: Increases damage done by Holy spells and effects by up to 11.\nSell Price: \nRequires Bronze Bar (20), Moss Agate (2), Lesser Moonstone (2), Iridescent Pearl (2), Silver Bar (4)"},
[210781] = {name = "[q3]Phoenix Bindings", additional_info = "Binds when equipped\n{Wrist} {Cloth}\n21 Armor\nDurability 30 / 30\nRequires Level 25\n[q2]Equip: Increases damage done by Fire spells and effects by up to 13.\nSell Price:"},
[210811] = {name = "[q2]Rune of Primordial Fury", additional_info = "Binds when picked up\nUnique\nClasses: Shaman\n[q2]Engrave your pants with the Greater Ghost Wolf rune:\n\n\nYour Ghost Wolf ability can now be used indoors, and reduces all damage you take by 10% while active.\n[q]\"Teaches you a new Engraving ability.\""},
[210817] = {name = "[q2]Rune of Survival", additional_info = "Binds when picked up\nUnique\nClasses: Druid\n[q2]Engrave your chest or robe with the Survival of the Fittest rune:\n\n\nReduces the chance you'll be critically hit by melee attacks by 6% and reduces all damage taken by 10%. Damage taken reduced by an additional 10% while in Bear Form or Dire Bear Form.\n[q]\"Teaches you a new Engraving ability.\""},
[210818] = {name = "[q2]Rune of Lone Wolf", additional_info = "Binds when picked up\nUnique\nClasses: Hunter\n[q2]Engrave your chest or robe with the Lone Wolf rune:\n\n\nYou deal 25% increased damage with all attacks while you do not have an active pet.\n[q]\"Teaches you a new Engraving ability.\""},
[210820] = {name = "[q2]Rune of Sacrifice", additional_info = "Binds when picked up\nUnique\nClasses: Paladin\n[q2]Engrave your pants with the Hand of Sacrifice rune:\n\n\nCauses target party or raid member to transfer 30% of damage taken to the caster. Lasts 12 sec or until the caster has transferred 100% of their maximum health.\n[q]\"Teaches you a new Engraving ability.\""},
[210822] = {name = "[q2]Harmonious Epiphany", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Engrave your chest or robe with the Serendipity rune:\n\n\nHealing with Flash Heal reduces the cast time of your next Lesser Heal, Heal, Greater Heal, or Prayer of Healing by 20% for 20 sec, stacking up to 3 times.\n[q]\"Learn a new Engraving ability.\""},
[210823] = {name = "[q2]Rune of Dual Wield Specialization", additional_info = "Binds when picked up\nUnique\nClasses: Shaman\n[q2]Engrave your chest or robe with the Dual Wield Specialization rune:\n\n\nIncreases your chance to hit with both spells and melee attacks by 5% while dual wielding, your Stormstrike ability now hits with both weapons while dual wielding, and increases the damage done by your offhand weapon by 60%.\n[q]\"Teaches you a new Engraving ability.\""},
[210824] = {name = "[q2]Rune of the Pact", additional_info = "Binds when picked up\nUnique\nClasses: Warlock\n[q2]Engrave your pants with the Demonic Pact rune:\n\n\nYour Fire and Shadow spells deal 10% more damage, and your pet's critical strikes apply the Demonic Pact effect to your party or raid members for 45 sec. Demonic Pact increases spell damage and healing by 10% of your spell damage or ( 60 / 2), whichever is higher. Does not work on Subjugated demons.\n[q]\"Teaches you a new Engraving ability.\""},
[210825] = {name = "[q2]Rune of the Warbringer", additional_info = "Binds when picked up\nUnique\nClasses: Warrior\n[q2]Engrave your chest with the Warbringer rune:\n\n\nYour Charge, Intercept, and Intervene abilities are now usable while in combat and in any stance, and will all remove movement impairing effects when activated.\n[q]\"Teaches you a new Engraving ability.\""},
[210953] = {name = "Eye of Bhossca", additional_info = "Binds when picked up\nUnique\n[q]\"Though the eye is inanimate, you feel watched...\""},
[210955] = {name = "Scarlet Initiate's Uniform", additional_info = "Binds when picked up\nUnique\n[q2]Use: Disguise yourself as a member of the Scarlet Crusade. Suspicious activity will break the disguise."},
[210963] = {name = "Scryer's Key", additional_info = "Binds when picked up\nUnique\nClasses: Rogue"},
[210966] = {name = "Blood of the Legion", additional_info = "Quest Item\nUnique (10)\n[q]\"Dark and thick... This blood links back to great commanders of the legion.\""},
[210967] = {name = "Confidential Message", additional_info = "Binds when picked up\nUnique\nClasses: Rogue\n[q2]<Right Click to Read>"},
[210968] = {name = "Reliquary Key", additional_info = "Binds when picked up\nUnique\nClasses: Rogue"},
[210979] = {name = "[q2]Rune of Shadowstep", additional_info = "Binds when picked up\nUnique\nClasses: Rogue\n[q2]Engrave your belt with the Shadowstep rune:\n\n\nAttempts to step through the shadows and reappear behind your enemy and increases movement speed by 70% for 3 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[210980] = {name = "[q2]Rune of Metamorphosis", additional_info = "Binds when picked up\nUnique\nClasses: Warlock\n[q2]Engrave your gloves with the Metamorphosis rune:\n\n\nTransform into a Demon, increasing Armor by 500%, Health by 15%, reducing the chance you will be critically hit by 6%, increasing your threat by 50%, increasing mana gained from Life Tap by 100%, but reducing all damage you deal by 10%. Metamorphosis transforms the functionality of some abilities and grants new ones:\n\n Searing Pain: Now instant.\n\n Shadow Bolt: Becomes Shadow Cleave, a Shadow melee attack that hits up to 10 nearby enemies, but has a 6 sec cooldown.\n\n Fear: Replaced with Menace.\n\n\nTaunts the target to attack you, but has no effect if the target is already attacking you.\n\n Demon Charge\n\n\nCharge an enemy and stun it for 1 sec. Cannot be used in combat.\n\n Demonic Howl\n\n\nForces all nearby enemies to focus attacks on you for 6 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[211205] = {name = "[q2]Rune of Cobra Slayer", additional_info = "Binds when picked up\nUnique\nClasses: Hunter\n[q2]Engrave your gloves with the Cobra Slayer rune:\n\n\nMongoose Bite now has a 10% chance to activate on each of your melee attacks, a 100% chance when an enemy dodges. This chance accumulates, with the chance rising by 10% from each subsequent attack if it does not reset. Mongoose Bite also deals additional damage equal to 45% of your Attack Power.\n[q]\"Teaches you a new Engraving ability.\""},
[211247] = {name = "[q2]Pattern: Phoenix Bindings", additional_info = "Binds when picked up\nRequires Tailoring (125)\n\n[q2]Use: Teaches you how to sew Phoenix Bindings.\nSell Price:\n[q3]Phoenix Bindings\nBinds when equipped\n{Wrist} {Cloth}\n21 Armor\nDurability 30 / 30\nRequires Level 25\n[q2]Equip: Increases damage done by Fire spells and effects by up to 13.\nSell Price: \nRequires Bolt of Woolen Cloth (6), Flask of Oil (2), Fine Thread (2)"},
[211269] = {name = "Primitive Drawing", additional_info = "Binds when picked up\nThis Item Begins a Quest"},
[211272] = {name = "Empty Bait Cage", additional_info = "Binds when picked up\n[q2]Use: Catch a critter to be used as bait."},
[211273] = {name = "Trapped Critter", additional_info = "Binds when picked up\n[q2]Use: Place critter as bait."},
[211293] = {name = "Crimson Trophy Quill", additional_info = "Quest Item\nUnique"},
[211301] = {name = "[q2]Rune of Expose Weakness", additional_info = "Binds when picked up\nClasses: Hunter\n[q2]Engrave your belt with the Expose Weakness rune:\n\n\nYour melee and ranged criticals increase your attack power by 40% of your current Agility for 7 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[211315] = {name = "[q2]Waylaid Supplies: Light Leather", additional_info = "Binds when picked up\nUnique: Waylaid Shipment (12)\n[q2]Use: Add 14 Light Leather to complete the shipment.\nSell Price:"},
[211316] = {name = "[q2]Waylaid Supplies: Peacebloom", additional_info = "Binds when picked up\nUnique: Waylaid Shipment (12)\n[q2]Use: Add 20 Peacebloom to complete the shipment.\nSell Price:"},
[211317] = {name = "[q2]Waylaid Supplies: Silverleaf", additional_info = "Binds when picked up\nUnique: Waylaid Shipment (12)\n[q2]Use: Add 20 Silverleaf to complete the shipment.\nSell Price:"},
[211318] = {name = "[q2]Waylaid Supplies: Minor Healing Potions", additional_info = "Binds when picked up\nUnique: Waylaid Shipment (12)\n[q2]Use: Add 20 Minor Healing Potions to complete the shipment.\nSell Price:"},
[211319] = {name = "[q2]Waylaid Supplies: Copper Shortswords", additional_info = "Binds when picked up\nUnique: Waylaid Shipment (12)\n[q2]Use: Add 6 Copper Shortswords to complete the shipment.\nSell Price:"},
[211320] = {name = "[q2]Waylaid Supplies: Runed Copper Pants", additional_info = "Binds when picked up\nUnique: Waylaid Shipment (12)\n[q2]Use: Add 3 Runed Copper Pants to complete the shipment.\nSell Price:"},
[211321] = {name = "[q2]Waylaid Supplies: Lesser Magic Wands", additional_info = "Binds when picked up\nUnique: Waylaid Shipment (12)\n[q2]Use: Add 2 Lesser Magic Wands to complete the shipment.\nSell Price:"},
[211322] = {name = "[q2]Waylaid Supplies: Minor Wizard Oil", additional_info = "Binds when picked up\nUnique: Waylaid Shipment (12)\n[q2]Use: Add 2 Minor Wizard Oil to complete the shipment.\nSell Price:"},
[211323] = {name = "[q2]Waylaid Supplies: Rough Copper Bombs", additional_info = "Binds when picked up\nUnique: Waylaid Shipment (12)\n[q2]Use: Add 12 Rough Copper Bombs to complete the shipment.\nSell Price:"},
[211324] = {name = "[q2]Waylaid Supplies: Rough Boomsticks", additional_info = "Binds when picked up\nUnique: Waylaid Shipment (12)\n[q2]Use: Add 3 Rough Boomsticks to complete the shipment.\nSell Price:"},
[211325] = {name = "[q2]Waylaid Supplies: Handstitched Leather Belts", additional_info = "Binds when picked up\nUnique: Waylaid Shipment (12)\n[q2]Use: Add 5 Handstitched Leather Belts to complete the shipment.\nSell Price:"},
[211326] = {name = "[q2]Waylaid Supplies: Embossed Leather Vests", additional_info = "Binds when picked up\nUnique: Waylaid Shipment (12)\n[q2]Use: Add 3 Embossed Leather Vests to complete the shipment.\nSell Price:"},
[211327] = {name = "[q2]Waylaid Supplies: Brown Linen Pants", additional_info = "Binds when picked up\nUnique: Waylaid Shipment (12)\n[q2]Use: Add 6 Brown Linen Pants to complete the shipment.\nSell Price:"},
[211328] = {name = "[q2]Waylaid Supplies: Brown Linen Robes", additional_info = "Binds when picked up\nUnique: Waylaid Shipment (12)\n[q2]Use: Add 4 Brown Linen Robes to complete the shipment.\nSell Price:"},
[211329] = {name = "[q2]Waylaid Supplies: Herb Baked Eggs", additional_info = "Binds when picked up\nUnique: Waylaid Shipment (12)\n[q2]Use: Add 20 Herb Baked Eggs to complete the shipment.\nSell Price:"},
[211330] = {name = "[q2]Waylaid Supplies: Spiced Wolf Meat", additional_info = "Binds when picked up\nUnique: Waylaid Shipment (12)\n[q2]Use: Add 20 Spiced Wolf Meat to complete the shipment.\nSell Price:"},
[211331] = {name = "[q2]Waylaid Supplies: Brilliant Smallfish", additional_info = "Binds when picked up\nUnique: Waylaid Shipment (12)\n[q2]Use: Add 20 Brilliant Smallfish to complete the shipment.\nSell Price:"},
[211332] = {name = "[q2]Waylaid Supplies: Heavy Linen Bandages", additional_info = "Binds when picked up\nUnique: Waylaid Shipment (12)\n[q2]Use: Add 10 Heavy Linen Bandages to complete the shipment.\nSell Price:"},
[211365] = {name = "[q2]Supply Shipment", additional_info = "Binds when picked up\n[q]\"Deliver to a supply officer for a substantial reward.\""},
[211367] = {name = "[q2]Supply Shipment", additional_info = "Binds when picked up\n[q]\"Deliver to a supply officer for a substantial reward.\""},
[211368] = {name = "[q2]Supply Shipment", additional_info = "Binds when picked up\n[q]\"Deliver to a supply officer for a substantial reward.\""},
[211385] = {name = "[q2]Rune of Serpent Spread", additional_info = "Binds when picked up\nUnique\nClasses: Hunter\n[q2]Engrave your pants with the Serpent Spread rune:\n\n\nTargets hit by your Multi-Shot are also afflicted by your Serpent Sting for 12 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[211386] = {name = "[q2]Spell Notes: Arcane Surge", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Engrave your pants with the Arcane Surge rune:\n\n\nUnleash all of your remaining mana in a surge of energy focused at the target dealing [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 226 / 100] to [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 264 / 100] Arcane damage, increased by up to 300% based on your mana remaining. Afterward, your normal mana regeneration is activated and increased by 300% for 8 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[211387] = {name = "[q2]Rune of Beckoning Light", additional_info = "Binds when picked up\nUnique\nClasses: Paladin\n[q2]Engrave your gloves with the Beacon of Light rune:\n\n\nThe target becomes a Beacon of Light to all members of your party or raid within a 40 yard radius. Any heals you cast on party or raid members will also heal the Beacon for 75% of the amount healed. Only one target can be the Beacon of Light at a time. Lasts 1 hour.\n[q]\"Teaches you a new Engraving ability.\""},
[211390] = {name = "[q2]Rune of Teasing", additional_info = "Binds when picked up\nUnique\nClasses: Rogue\n[q2]Engrave your chest or robe with the Just a Flesh Wound rune:\n\n\nYou take 20% reduced Physical damage while Blade Dance is active, reduced by an additional 1% for every 12 of your Defense skill beyond ( 60 * 5). Additionally, your chance to Dodge is multiplied by 50%, you have 6% reduced chance to be critically hit by melee attacks, you deal 20% less damage, the threat generated by all your actions is massively increased, and your Feint ability is replaced with Tease, which Taunts the target to attack you.\n\n\nTaunts the target to attack you, but has no effect if the target is already attacking you.\n[q]\"Teaches you a new Engraving ability.\""},
[211391] = {name = "[q2]Rune of Healing Rain", additional_info = "Binds when picked up\nUnique\nClasses: Shaman\n[q2]Engrave your chest or robe with the Healing Rain rune:\n\n\nSelects the area 15 yards around target player, and heals all of target player's party members within that area for [(29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) * 15 / 100] every second.\n[q]\"Teaches you a new Engraving ability.\""},
[211392] = {name = "[q2]Rune of Everlasting Affliction", additional_info = "Binds when picked up\nUnique\nClasses: Warlock\n[q2]Engrave your pants with the Everlasting Affliction rune:\n\n\nDrain Life, Drain Soul, Shadowbolt, Shadow Cleave, Searing Pain, Incinerate, and Haunt refresh the duration of your Corruption on the target back to its maximum duration.\n[q]\"Teaches you a new Engraving ability.\""},
[211393] = {name = "[q2]Rune of Single-Minded Fury", additional_info = "Binds when picked up\nUnique\nClasses: Warrior\n[q2]Engrave your gloves with the Single-Minded Fury rune:\n\n\nWhile dual-wielding, your movement speed is increased by 10% and you gain 4% attack speed each time your melee auto-attack strikes the same target as your previous auto-attack, stacking up to 5 times. Lasts 10 sec or until your auto-attack strikes a different target.\n[q]\"Teaches you a new Engraving ability.\""},
[211419] = {name = "[q2]Handful of Shifting Scales", additional_info = "Binds when picked up\nUnique\n[q]\"These curious scales seem to shimmer slightly, as if they are not fully corporeal. There is clearly wonderous magic at play here... if only you could find someone who knows more about them.\""},
[211427] = {name = "[q3]Soul Vessel", additional_info = "[q]\"Traps demon souls and siphons them for power.\""},
[211447] = {name = "Arms Shipment", additional_info = "Quest Item\nUnique"},
[211448] = {name = "Signed Procurement Contract", additional_info = "Quest Item\nUnique"},
[211471] = {name = "Cliffspring Key", additional_info = "Unique"},
[211472] = {name = "[q2]Libram of Banishment", additional_info = "Binds when picked up\nUnique\n{Relic} {Libram}\nClasses: Paladin\n[q2]Engrave your pants with the Aura Mastery rune:\n\n\nCauses your Concentration Aura to make all affected targets immune to Silence and Interrupt effects and improves the effect of all other auras by 100%. Lasts 6 sec.\n[q]\"Learn a new ability after casting Turn Undead on 5 enemies, and slaying them with Exorcism.\""},
[211476] = {name = "[q2]Rune of Fires Wake", additional_info = "Binds when picked up\nUnique\nClasses: Warlock\n[q2]Engrave your chest or robe with the Lake of Fire rune:\n\n\nYour Rain of Fire is no longer channeled, but gains a 8 sec cooldown.\n[q]\"Teaches you a new Engraving ability.\""},
[211477] = {name = "[q2]Rune of Incinerate", additional_info = "Binds when picked up\nUnique\nClasses: Warlock\n[q2]Engrave your bracers with the Incinerate rune:\n\n\nBurn your enemy for [222 / 100 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60)] to [258 / 100 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60)] damage and increase all Fire damage you deal by 40% for the next 15 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[211482] = {name = "Shatterspear Offering", additional_info = "Binds when picked up\nUnique"},
[211487] = {name = "[q2]Demolition Explosives", additional_info = "Binds when picked up\nUnique\n[q2]Use: Place a bomb with a short fuse on the ground in front of you.\n[q]\"Only seems useful for clearing out debris and rubble.\""},
[211488] = {name = "[q2]Rune of the Avenger", additional_info = "Binds when picked up\nUnique\nClasses: Paladin\n[q2]Engrave your pants with the Avenger's Shield rune:\n\n\nHurls a holy shield at the enemy, dealing [366 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Spell Power + 0.091 * Attack Power] to [448 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Spell Power + 0.091 * Attack Power] Holy damage, Dazing them and then jumping to additional nearby enemies. Affects 3 total targets. Lasts 5 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[211490] = {name = "[q2]Prophecy of a Thousand Lights", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Engrave your gloves with the Circle of Healing rune:\n\n\nHeals all of target player's party members within 43.5 yards of target player for [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 130 / 100] to [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 144 / 100].\n\n[q2]Use: Focus on the Prophecy to learn a new spell. Requires a mind focused by meditating on two spiritual mysteries of Azeroth.\n[q]\"Learn a new Engraving ability.\""},
[211498] = {name = "[q3]Trainee's Sentinel Nightsaber", additional_info = "Binds when picked up\nMount\nRequires any Alliance race\nRequires Level 25\n\n[q2]Use: Summons a Trainee's Sentinel Nightsaber. Only usable in Ashenvale. (3 Sec Cooldown)"},
[211499] = {name = "[q3]Trainee's Outrider Wolf", additional_info = "Binds when picked up\nMount\nRequires any Horde race\nRequires Level 25\n\n[q2]Use: Summons a Trainee's Outrider Wolf. Only usable in Ashenvale. (3 Sec Cooldown)"},
[211500] = {name = "[q3]Resilient Cloth Headband", additional_info = "Binds when picked up\nUnique\n{Head} {Cloth}\n50 Armor\nDurability 50 / 50\nRequires Level 20\n[q2]Equip: Reduces all damage taken and chance to be critically hit by 5% in Warsong Gulch."},
[211514] = {name = "[q2]Spell Notes: Mass Regeneration", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Engrave your pants with the Mass Regeneration rune:\n\n\nHeals all of target player's party members within 43.5 yards of target player for [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 55 / 100 * 3] health over 3 sec and applies Temporal Beacon to each target for 15 sec.\n\n Temporal Beacon\n\nRecords the subject's space-time position. 70% of all Arcane damage done by the caster will be converted to chronomantic healing on each of the caster's current Temporal Beacon targets. This healing is reduced by 50% on self, and also reduced by 80% when damage is done by Arcane spells that damage multiple targets.\n[q]\"Teaches you a new Engraving ability.\""},
[211527] = {name = "[q3]Cozy Sleeping Bag", additional_info = "Binds when picked up\nUnique\n[q2]Use: Unfurl a sleeping bag. Resting inside for at least one minute will provide a bonus to experience earned, stacking up to 3 times. (1 Hour Cooldown)\n[q]\"Old, but still good\"\nSell Price:"},
[211528] = {name = "Dark Insight", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Use: Consider at a certain secluded grave in Duskwood to receive a prophecy."},
[211530] = {name = "[q2]Prophecy of a City Enthralled", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Engrave your bracers with the Power Word: Barrier rune:\n\n\nSummons a holy barrier to protect all party members at the target location for 10 sec, reducing all damage taken by 25% and preventing damage from delaying spellcasting.\n\n[q2]Use: Focus on the Prophecy to learn a new spell. Requires a mind focused by meditating on two spiritual mysteries of Azeroth."},
[211531] = {name = "[q2]Prophecy of Seven Visitors", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Engrave your chest or robe with the Strength of Soul rune:\n\n\nLesser Heal, Heal, Greater Heal, and Flash Heal reduce the remaining duration of Weakened Soul on targets they heal by 2 sec. In addition, targets of your Power Word: Shield will gain Rage from taking damage despite the damage being absorbed, and Righteous Fury will trigger from damage absorbed by your Power Word: Shield as if it were a heal.\n\n[q2]Use: Focus on the Prophecy to learn a new spell. Requires a mind focused by meditating on two spiritual mysteries of Azeroth."},
[211534] = {name = "Primal Insight", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Use: Consider at a Thistlefur dreamcatcher high in the canopy to receive a prophecy."},
[211691] = {name = "[q2]Spell Notes: Arcane Blast", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Engrave your gloves with the Arcane Blast rune:\n\n\nBlasts the target with energy, dealing [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 453 / 100] to [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 527 / 100] Arcane damage. Each time you cast Arcane Blast, the damage of all other Arcane spells is increased by 15% and mana cost of Arcane Blast is increased by 175%. Effect stacks up to 4 times and lasts 6 sec or until any other Arcane damage spell is cast.\n[q]\"Teaches you a new Engraving ability.\""},
[211777] = {name = "Naga Manuscript", additional_info = "Binds when picked up\nClasses: Mage\n[q2]<Right Click to Read>"},
[211779] = {name = "Comprehension Charm", additional_info = "Binds when picked up\nClasses: Mage\n[q]\"Aids the translation of scrolls and spell notes.\""},
[211780] = {name = "Scroll: KWYJIBO", additional_info = "Classes: Mage\n[q2]Use: Decipher the scroll with a Comprehension Charm. Who knows what magic it contains?\nSell Price:"},
[211784] = {name = "Scroll: WUBBA WUBBA", additional_info = "Classes: Mage\n[q2]Use: Decipher the scroll with a Comprehension Charm. Who knows what magic it contains?\nSell Price:"},
