[211787] = {name = "Scroll: LOWER PING WHOMEVER", additional_info = "Classes: Mage\n[q2]Use: Decipher the scroll with a Comprehension Charm. Who knows what magic it contains?\nSell Price:"},
[211799] = {name = "Sack of Stolen Goods", additional_info = "Binds when picked up\nUnique\nClasses: Paladin\n[q]\"Likely taken from the cathedral when Ada ran away.\"\n[q2]<Right Click to Open>"},
[211800] = {name = "Scroll of Reintegration", additional_info = "Classes: Mage\nRequires Level 12\n\n[q2]Use: Brings a dead player back to life with 15% of their health and mana. Cannot be used when in combat.\nSell Price:"},
[211809] = {name = "Comprehension Primer", additional_info = "Quest Item\nClasses: Mage\n[q]\"Aids in translation of elementary spell notes.\""},
[211813] = {name = "[q2]Silverwing Sentinel Charm", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\n[q]\"You acquired this from a fallen Silverwing Sentinel combatant. Perhaps the Far Seer would be interested.\""},
[211814] = {name = "[q2]Warsong Outrider Mark", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\n[q]\"You acquired this from a fallen Warsong Outrider combatant. Perhaps the Priestess of the Moon would be interested.\""},
[211815] = {name = "Silverwing Battle Hymn", additional_info = "Binds when picked up\n[q2]Use: Increases all damage and healing done by 5% for 2 hrs.\n[q]\"A stirring arrangement to rally morale before battle.\""},
