[211845] = {name = "[q2]Blackfathom Sharpening Stone", additional_info = "[q2]Use: While applied to the target weapon increases Hit Chance by 2% for 30 minutes. This has no effect outside of Blackfathom Deeps.\n[q]\"These mysterious enchanted stones seem to glow more brightly the deeper you descend into Blackfathom.\"\nSell Price:"},
[211853] = {name = "Scroll: VOCE WELL", additional_info = "Classes: Mage\n[q2]Use: Decipher the scroll with a Comprehension Charm. Who knows what magic it contains?\nSell Price:"},
