[211934] = {name = "[q2]Waylaid Supplies: Healing Potions", additional_info = "Binds when picked up\nUnique: Waylaid Shipment (12)\n[q2]Use: Add 10 Healing Potions to complete the shipment.\nSell Price:"},
[211935] = {name = "[q2]Waylaid Supplies: Elixir of Firepower", additional_info = "Binds when picked up\nUnique: Waylaid Shipment (12)\n[q2]Use: Add 15 Elixir of Firepower to complete the shipment.\nSell Price:"},
[211940] = {name = "[q3]Ecks'av's Tribal Guardian", additional_info = "Binds when picked up\n{Two-Hand} {Polearm}\n{155 - 231 Damage} {Speed 3.70}\n(52.16 damage per second)\nDurability 100 / 100\nRequires Level 59\n[q2]Equip: Gives 40 additional armor to nearby party members for 4 min. Players may only have one aura on them per paladin at any one time.\nSell Price:"},
[211941] = {name = "[q3]Windwalker's Yari", additional_info = "Binds when picked up\n{Two-Hand} {Polearm}\n{147 - 223 Damage} {Speed 3.60}\n(51.39 damage per second)\nDurability 100 / 100\nRequires Level 58\n[q2]Chance on hit: Blasts enemies in front of you with the power of wind, fire, all that kind of thing!\nSell Price:"},
[211953] = {name = "[q2]Scroll of Arcane Recovery I", additional_info = "Binds when picked up\nClasses: Mage\nRequires Level 20\n\n[q2]Use: Restores 8 mana per 5 sec.\nSell Price:"},
[211954] = {name = "[q2]Scroll of Arcane Accuracy I", additional_info = "Binds when picked up\nClasses: Mage\nRequires Level 20\n\n[q2]Use: Increases your chance to hit with spells by 1%.\nSell Price:"},
[211955] = {name = "[q2]Scroll of Arcane Protection - Fire I", additional_info = "Binds when picked up\nClasses: Mage\nRequires Level 20\n\n[q2]Use: Increases your fire resistance by 20 for 30 min.\nSell Price:"},
[211956] = {name = "[q2]Scroll of Arcane Protection - Frost I", additional_info = "Binds when picked up\nClasses: Mage\nRequires Level 20\n\n[q2]Use: Increases your frost resistance by 20 for 30 min.\nSell Price:"},
[211957] = {name = "[q2]Scroll of Arcane Power I", additional_info = "Binds when picked up\nClasses: Mage\nRequires Level 20\n\n[q2]Use: Increases your chance to crit with spells by 1%.\nSell Price:"},
[212160] = {name = "Chronoboon Displacer", additional_info = "Season of Discovery\n[q2]Use: Alters the fabric of time, suspending beneficial world effects from dragonslaying, Dire Maul, Zul'Gurub, and Felwood. (5 Min Cooldown)\nSell Price:"},
[212225] = {name = "[q3]Neverending Soul Vessel", additional_info = "Binds when picked up\nUnique\n[q2]Use: Your next Soul Shard consuming spell cost no Soul Shards to cast. (5 Min Cooldown)"},
[212230] = {name = "[q3]Schematic: Soul Vessel", additional_info = "Binds when picked up\nRequires Engineering (205)\n\n[q2]Use: Teaches you how to make a Soul Vessel.\nSell Price: \n[q3]Soul Vessel\n[q]\"Traps demon souls and siphons them for power.\"\nRequires Shadowgem (4), Black Vitriol , Demonic Figurine"},
[212347] = {name = "Illari's Key", additional_info = "Binds when picked up\nUnique"},
[212548] = {name = "[q2]Rune of Eclipse", additional_info = "Binds when picked up\nUnique\nClasses: Druid\n[q2]Engrave your belt with the Eclipse rune:\n\n\nStarfire increases the critical strike chance of your next two Wraths by 30%, and Wrath reduces the cast time of your next Starfire by 1.0 sec, both effects stacking up to 4 charges. Both spells also gain 70% chance at all times to not lose casting time when you take damage.\n[q]\"Teaches you a new Engraving ability.\""},
[212549] = {name = "[q2]Rune of the Trapper", additional_info = "Binds when picked up\nClasses: Hunter\n[q2]Engrave your boots with the Trap Launcher rune:\n\n\nYour Freezing, Immolation, and Explosive Traps can now be placed at any location within 35 yards. Additionally, your Fire-based and Frost-based traps now have separate shared cooldowns.\n[q]\"Teaches you a new Engraving ability.\""},
[212551] = {name = "[q2]Rune of Warfare", additional_info = "Binds when picked up\nUnique\nClasses: Paladin\n[q2]Engrave your boots with the The Art of War rune:\n\n\nYour melee critical strikes reduce the remaining cooldown on Exorcism by 2 sec, and the mana cost of Exorcism is reduced by 80%.\n[q]\"Teaches you a new Engraving ability.\""},
[212552] = {name = "[q2]Psychosophic Epiphany", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Engrave your belt with the Mind Spike rune:\n\n\nBlasts the target for [122 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] to [142 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] Shadowfrost damage, and increases the critical strike chance of your next Mind Blast on the target by 30%, stacking up to 3 times.\n[q]\"Teaches you a new Engraving ability.\""},
[212559] = {name = "[q2]Rune of the Poisoned Blade", additional_info = "Binds when picked up\nUnique\nClasses: Rogue\n[q2]Engrave your belt with the Poisoned Knife rune:\n\n\nInstantly throw your off-hand weapon to deal normal off-hand weapon damage with a 100% chance to apply the poison from your off-hand weapon to the target. Awards 1 combo point. Refunds 5 Energy per application of Deadly Poison on the target.\n\n Poisoned Knife benefits from all talents and effects that trigger from or modify Sinister Strike.\n[q]\"Teaches you a new Engraving ability.\""},
[212560] = {name = "[q2]Rune of Ancestral Awakening", additional_info = "Binds when picked up\nUnique\nClasses: Shaman\n[q2]Engrave your boots with the Ancestral Awakening rune:\n\n\nWhen you critically heal with your Healing Wave or Lesser Healing Wave you summon an Ancestral spirit to aid you, instantly healing the lowest percentage health party member within 40 yards for 30% of the amount healed.\n[q]\"Teaches you a new Engraving ability.\""},
[212561] = {name = "[q2]Rune of Burning Darkness", additional_info = "Binds when picked up\nUnique\nClasses: Warlock\n[q2]Engrave your belt with the Shadow and Flame rune:\n\n\nYour critical strikes with Fire and Shadow spells increase your Fire and Shadow damage done by 10% for 10 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[212562] = {name = "[q2]Rune of Healing Rage", additional_info = "Binds when picked up\nUnique\nClasses: Warrior\n[q2]Engrave your boots with the Enraged Regeneration rune:\n\n\nHeals you for 30% of your maximum health over 10 sec, but can only be used while Enrage, Berserker Rage, or Bloodrage is active. Useable while Stunned.\n[q]\"Teaches you a new Engraving ability.\""},
[212568] = {name = "[q3]Wolfshead Trophy", additional_info = "Binds when picked up\nUnique\nClasses: Druid\nRequires Level 40\n\n[q2]Use: Permanently enchant a helm slot item, causing you to gain 20 energy or 5 rage when shapeshifting into Cat or Bear form."},
[212580] = {name = "[q3]Lorekeeper's Staff", additional_info = "Binds when picked up\n{Two-Hand} {Staff}\n{57 - 87 Damage} {Speed 2.90}\n(24.83 damage per second)\n+10 Stamina\n+6 Intellect\nDurability 100 / 100\nRequires Level 25\n[q2]Equip: Restores 4 mana per 5 sec.\nSell Price:"},
[212581] = {name = "[q3]Outrunner's Bow", additional_info = "Binds when picked up\n{Ranged} {Bow}\n{25 - 47 Damage} {Speed 2.40}\n(15.00 damage per second)\nDurability 80 / 80\nRequires Level 25\nSell Price:"},
[212582] = {name = "[q3]Protector's Sword", additional_info = "Binds when picked up\nUnique\n{One-Hand} {Sword}\n{35 - 67 Damage} {Speed 2.70}\n(18.89 damage per second)\n+6 Strength\n+3 Stamina\nDurability 90 / 90\nRequires Level 25\nSell Price:"},
[212583] = {name = "[q3]Sentinel's Blade", additional_info = "Binds when picked up\nUnique\n{One-Hand} {Dagger}\n{22 - 43 Damage} {Speed 1.70}\n(19.12 damage per second)\n+6 Agility\n+3 Stamina\nDurability 65 / 65\nRequires Level 25\nSell Price:"},
[212584] = {name = "[q3]Advisor's Gnarled Staff", additional_info = "Binds when picked up\n{Two-Hand} {Staff}\n{57 - 87 Damage} {Speed 2.90}\n(24.83 damage per second)\n+10 Stamina\n+6 Intellect\nDurability 100 / 100\nRequires Level 25\n[q2]Equip: Restores 4 mana per 5 sec.\nSell Price:"},
[212585] = {name = "[q3]Outrider's Bow", additional_info = "Binds when picked up\n{Ranged} {Bow}\n{25 - 47 Damage} {Speed 2.40}\n(15.00 damage per second)\nDurability 80 / 80\nRequires Level 25\nSell Price:"},
[212586] = {name = "[q3]Legionnaire's Sword", additional_info = "Binds when picked up\nUnique\n{One-Hand} {Sword}\n{35 - 67 Damage} {Speed 2.70}\n(18.89 damage per second)\n+6 Strength\n+3 Stamina\nDurability 90 / 90\nRequires Level 25\nSell Price:"},
[212587] = {name = "[q3]Scout's Blade", additional_info = "Binds when picked up\nUnique\n{One-Hand} {Dagger}\n{22 - 43 Damage} {Speed 1.70}\n(19.12 damage per second)\n+6 Agility\n+3 Stamina\nDurability 65 / 65\nRequires Level 25\nSell Price:"},
[212723] = {name = "Rumbling Essence", additional_info = "Quest Item\nUnique (10)"},
[212724] = {name = "Whirling Essence", additional_info = "Quest Item\nUnique (10)"},
[212726] = {name = "Rushing Essence", additional_info = "Quest Item\nUnique (10)"},
[212748] = {name = "[q2]Tattered Note", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 30"},
[212792] = {name = "[q3]Eye of the Tempest", additional_info = "Quest Item\nUnique"},
[212982] = {name = "Squall-breakers Potion", additional_info = "Quest Item\nUnique\nRequires Level 30\n\n[q2]Use: Protect yourself against the elements as long as you survive. (5 Min Cooldown)"},
[213074] = {name = "[q2]Rune of Nourishing", additional_info = "Binds when picked up\nUnique\nClasses: Druid\n[q2]Engrave your belt with the Nourish rune:\n\n\nHeals a friendly target for [161 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] to [189 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)]. Heals for an additional 20% if you have a Rejuvenation, Regrowth, Lifebloom, or Wild Growth effect active on the target. This spell benefits from and triggers all effects associated with Healing Touch or Regrowth.\n[q]\"Teaches you a new Engraving ability.\""},
[213086] = {name = "[q2]Rune of the Storm", additional_info = "Binds when picked up\nUnique\nClasses: Shaman\n[q2]Engrave your belt with the Maelstrom Weapon rune:\n\n\nWhen you deal damage with a melee attack, you have a chance to reduce the cast time and mana cost of your next Lightning Bolt, Chain Lightning, Lesser Healing Wave, or Lava Burst spell by 20%. Chance increased by 50% while your main hand weapon is enchanted with Windfury Weapon and by another 50% if wielding a two-handed weapon. Stacks up to 5 times. Lasts 30 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[213090] = {name = "[q2]Rune of Synergy", additional_info = "Binds when picked up\nUnique\nClasses: Warlock\n[q2]Engrave your belt with the Grimoire of Synergy rune:\n\n\nDamage done by you or your summoned demon has a 10% chance to increase the damage done by the other by 10% for 15 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[213093] = {name = "[q2]Rune of Power", additional_info = "Binds when picked up\nUnique\nClasses: Shaman\n[q2]Engrave your belt with the Power Surge rune:\n\n\nEach time Flame Shock deals damage, it has a 5% chance to reset the cooldown on Lava Burst and Chain Lightning and make your next Lava Burst or Chain Lightning within 10 sec instant. Each time Riptide heals, it has a 5% chance to make your next Chain Heal within 10 sec instant. Additionally, every 5 sec you gain mana equal to 15% of your Intellect.\n[q]\"Teaches you a new Engraving ability.\""},
[213094] = {name = "[q2]Rune of Fire Nova", additional_info = "Binds when picked up\nUnique\nClasses: Shaman\n[q2]Engrave your belt with the Fire Nova rune:\n\n\nYour Fire Nova Totem spell is replaced with Fire Nova, which causes your current Fire totem to emit damage at its location.\n[q]\"Teaches you a new Engraving ability.\""},
[213096] = {name = "[q2]Rune of Decoys", additional_info = "Binds when picked up\nUnique\nClasses: Shaman\n[q2]Engrave your boots with the Decoy Totem rune:\n\n\nSummons a Decoy Totem for 10 sec with 5 health at the feet of the target that will redirect the next melee or ranged attack made against the target to the totem instead. The totem also grants the target immunity to movement impairing effects for 10 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[213098] = {name = "[q2]Rune of Invocation", additional_info = "Binds when picked up\nUnique\nClasses: Warlock\n[q2]Engrave your belt with the Invocation rune:\n\n\nApplying Corruption, Immolate, Curse of Agony, Unstable Affliction, Shadowflame, or Siphon Life will cause you to deal instant damage to the target equal to one tick of the spell's periodic damage. Refreshing any of those spells when it has less than 6 seconds duration remaining will cause you to deal instant damage to the target equal to the spell's remaining periodic damage.\n[q]\"Teaches you a new Engraving ability.\""},
[213100] = {name = "[q2]Rune of Forbidden Knowledge", additional_info = "Binds when picked up\nUnique\nClasses: Warlock\n[q2]Engrave your boots with the Demonic Knowledge rune:\n\n\nIncreases your spell damage and healing by a value equal to 3% of your Demon pet's total Stamina plus Intellect.\n[q]\"Teaches you a new Engraving ability.\""},
[213101] = {name = "[q2]Rune of Shadowflames", additional_info = "Binds when picked up\nUnique\nClasses: Warlock\n[q2]Engrave your boots with the Shadowflame rune:\n\n\nBurns the enemy for [173 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) / 100 * ( ( ( 1 ) ) ) ] Shadowflame damage and then an additional [64 * 5 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) / 100] Shadowflame damage over 15 sec.\n\n Shadowflame triggers and benefits from all effects that modify or interact with Immolate, or with Affliction, Destruction, Fire, or Shadow spells, but only one of Immolate or Shadowflame per Warlock can be active on any target. In addition, Shadowflame can trigger your Improved Shadow Bolt talent and causes it to have 26 additional charges.\n[q]\"Teaches you a new Engraving ability.\""},
[213102] = {name = "[q2]Rune of Wickedness", additional_info = "Binds when picked up\nUnique\nClasses: Warlock\n[q2]Engrave your boots with the Dance of the Wicked rune:\n\n\nYou and your demon pet gain dodge chance equal to 70% of your spell critical strike chance each time you deal a critical strike to an enemy, and also both regain 2% of maximum mana.\n[q]\"Teaches you a new Engraving ability.\""},
[213103] = {name = "[q2]Rune of Blood Surge", additional_info = "Binds when picked up\nUnique\nClasses: Warrior\n[q2]Engrave your belt with the Blood Surge rune:\n\n\nHeroic Strike, Bloodthirst, and Whirlwind have a 30% chance to make your next Slam within 15 sec instant, strike with both melee weapons, and cost no Rage.\n[q]\"Teaches you a new Engraving ability.\""},
[213104] = {name = "[q2]Rune of Ruthless Precision", additional_info = "Binds when picked up\nUnique\nClasses: Warrior\n[q2]Engrave your belt with the Precision Timing rune:\n\n\nSlam is now instant but has a 6 sec cooldown.\n[q]\"Teaches you a new Engraving ability.\""},
[213105] = {name = "[q3]Shawarmageddon", additional_info = "Binds when picked up\n{One-Hand} {Mace}\n{50 - 93 Damage} {Speed 2.60}\n(27.50 damage per second)\nDurability 90 / 90\nClasses: Warrior\nRequires Level 40\n[q2]Use: Increase attack speed by 4%, and give all melee attacks a chance to deal 7 additional fire damage. (2 Min Cooldown)\nSell Price:"},
[213109] = {name = "[q2]Rune of Focused Rage", additional_info = "Binds when picked up\nUnique\nClasses: Warrior\n[q2]Engrave your belt with the Focused Rage rune:\n\n\nReduces the rage cost of your offensive abilities by 3.\n[q]\"Teaches you a new Engraving ability.\""},
[213110] = {name = "[q2]Rune of the Commander", additional_info = "Binds when picked up\nUnique\nClasses: Warrior\n[q2]Engrave your boots with the Rallying Cry rune:\n\n\nLet loose a rallying cry, granting all party and raid members within 40 yards 15% increased maximum health for 10 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[213111] = {name = "[q2]Rune of Intervention", additional_info = "Binds when picked up\nUnique\nClasses: Warrior\n[q2]Engrave your boots with the Intervene rune:\n\n\nRun at high speed towards a party member, intercepting the next melee or ranged attack made against them as well as reducing their total threat by 10%.\n[q]\"Teaches you a new Engraving ability.\""},
[213112] = {name = "[q2]Spell Notes: Missile Barrage", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Engrave your belt with the Missile Barrage rune:\n\n\nGives your Arcane Blast a 40% chance, and your Fireball and Frostbolt spells a 20% chance to reduce the channeled duration of your next Arcane Missiles spell by 50%, reduce the mana cost by 100%, and missiles will fire every 0.5 secs.\n[q]\"Teaches you a new Engraving ability.\""},
[213117] = {name = "[q2]Rune of Berserk", additional_info = "Binds when picked up\nUnique\nClasses: Druid\n[q2]Engrave your belt with the Berserk rune:\n\n\nWhen activated, this ability causes your Mangle (Bear) and Lacerate abilities to hit up to 3 targets, Lacerate to cost no Rage, Mangle (Bear) to have no cooldown, and reduces the energy cost of all your Cat Form abilities by 50%. Lasts 15 sec. Requires Bear Form, Cat Form, or Dire Bear Form to activate.\n\n Clears the effect of Fear and makes you immune to Fear for the duration.\n[q]\"Teaches you a new Engraving ability.\""},
[213118] = {name = "[q2]Rune of the Jungle King", additional_info = "Binds when picked up\nUnique\nClasses: Druid\n[q2]Engrave your boots with the King of the Jungle rune:\n\n\nTiger's Fury now increases all physical damage you deal by 15% instead of by a flat value, and instantly grants you 60 Energy. It is no longer on the global cooldown, but it now has its own 30 sec cooldown. Additionally, Tiger's Fury will persist while not in Cat Form, but will cancel upon entering Bear Form or Dire Bear Form.\n[q]\"Teaches you a new Engraving ability.\""},
[213119] = {name = "[q2]Rune of Instinct", additional_info = "Binds when picked up\nUnique\nClasses: Druid\n[q2]Engrave your boots with the Survival Instincts rune:\n\n\nWhen activated, this grants you 30% of your maximum health and increases all non-Physical healing you deal by 20% for 20 sec. After the effect expires, the health is lost. Useable in all forms except Moonkin Form.\n\n In addition, you regenerate 5 rage every time you dodge while in Bear Form or Dire Bear Form, 10 energy while in Cat Form, or 1% of your maximum mana while in any other form.\n[q]\"Teaches you a new Engraving ability.\""},
[213120] = {name = "[q2]Rune of the Dreamer", additional_info = "Binds when picked up\nUnique\nClasses: Druid\n[q2]Engrave your boots with the Dreamstate rune:\n\n\nYour damaging non-periodic spell critical strikes or any damage from Starsurge grant you 50% of your mana regeneration while casting for 8 sec and increase Arcane and Nature damage dealt to non-player targets by 20% for 12 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[213121] = {name = "[q2]Preserved Holly", additional_info = "Requires Level 25\n\n[q2]Use: Transforms your mount into something more festive. (1 Min Cooldown)"},
[213122] = {name = "[q2]Rune of Steady Shot", additional_info = "Binds when picked up\nClasses: Hunter\n[q2]Engrave your belt with the Steady Shot rune:\n\n\nA steady shot that causes 100% ranged weapon damage.\n[q]\"Teaches you a new Engraving ability.\""},
[213123] = {name = "[q2]Rune of Exposure", additional_info = "Binds when picked up\nClasses: Hunter\n[q2]Engrave your belt with the Expose Weakness rune:\n\n\nYour melee and ranged criticals increase your attack power by 40% of your current Agility for 7 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[213124] = {name = "[q2]Rune of Close Combat", additional_info = "Binds when picked up\nClasses: Hunter\n[q2]Engrave your belt with the Melee Specialist rune:\n\n\nYour Raptor Strike is now instant, and Mongoose Bite and Raptor Strike have a 40% chance on each attack to reset the cooldowns of Mongoose Bite and Raptor Strike.\n[q]\"Teaches you a new Engraving ability.\""},
[213125] = {name = "[q2]Rune of Invigoration", additional_info = "Binds when picked up\nClasses: Hunter\n[q2]Engrave your boots with the Wyvern Strike rune:\n\n\nReplaces your Wyvern Sting ability with Wyvern Strike, a vicious strike that deals 140% weapon damage and causes the target to Bleed for damage over time.\n\n Wyvern Strike requires you to have the Wyvern Sting talent, and replaces the Wyvern Sting abilities found in the Survival spellbook.\n[q]\"Teaches you a new Engraving ability.\""},
[213126] = {name = "[q2]Rune of the Scrapper", additional_info = "Binds when picked up\nClasses: Hunter\n[q2]Engrave your boots with the Dual Wield Specialization rune:\n\n\nIncreases the damage done by your offhand weapon by 60% and causes your Raptor Strike to strike with both weapons when you are dual-wielding.\n[q]\"Teaches you a new Engraving ability.\""},
[213127] = {name = "[q2]Spell Notes: PELFRB STOLLOTS", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Use: Decipher the spell notes with a Comprehension Charm to learn a new Engraving spell."},
[213128] = {name = "[q2]Rune of Piety", additional_info = "Binds when picked up\nUnique\nClasses: Paladin\n[q2]Engrave your belt with the Malleable Protection rune:\n\n\nYou can now take actions during Divine Protection and its duration is increased by 50%, but it only reduces damage you take by 50% instead of making you immune. In addition, activating Holy Shield also grants you 4 Attack Power for each point of your defense skill beyond ( 60 * 5), lasting 15 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[213129] = {name = "[q2]Rune of Light's Embrace", additional_info = "Binds when picked up\nUnique\nClasses: Paladin\n[q2]Engrave your belt with the Sheath of Light rune:\n\n\nDealing damage with your melee weapon increases your spell damage by an amount equal to 30% of your attack power for 1 min.\n[q]\"Teaches you a new Engraving ability.\""},
[213130] = {name = "[q2]Rune of Infusions", additional_info = "Binds when picked up\nUnique\nClasses: Paladin\n[q2]Engrave your belt with the Infusion of Light rune:\n\n\nIncreases the damage and healing done by your Holy Shock by 50%, reduces the cooldown on Holy Shock to 6 sec, and your critical strikes with Holy Shock refund its mana cost and reduce its remaining cooldown by 3 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[213131] = {name = "[q2]Rune of Sacred Shields", additional_info = "Binds when picked up\nUnique\nClasses: Paladin\n[q2]Engrave your boots with the Sacred Shield rune:\n\n\nEach time the target takes damage they gain a Sacred Shield, absorbing [36 * (38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) / 100] damage and increasing the Paladin's chance to critically hit with Flash of Light by 50% for up to 6 sec. In addition, causes your Flash of Light to heal targets with Sacred Shield for an additional 100% over 12 sec. They cannot gain this effect more than once every 6 sec. Lasts 1 min. This spell cannot be on more than one target at any one time.\n[q]\"Teaches you a new Engraving ability.\""},
[213132] = {name = "[q2]Rune of the Guardian", additional_info = "Binds when picked up\nUnique\nClasses: Paladin\n[q2]Engrave your boots with the Guarded by the Light rune:\n\n\nEach time you hit a target with your melee weapon, you gain 5% of your maximum mana per 3 sec for 15 sec, but the amount healed by your Healing spells is reduced by 50% during this mana regeneration.\n[q]\"Teaches you a new Engraving ability.\""},
[213136] = {name = "[q2]Rune of Subtlety", additional_info = "Binds when picked up\nUnique\nClasses: Rogue\n[q2]Engrave your boots with the Master of Subtlety rune:\n\n\nAttacks made while stealthed and for 6 seconds after breaking stealth cause an additional 10% damage.\n[q]\"Teaches you a new Engraving ability.\""},
[213137] = {name = "[q2]Rune of the Assailant", additional_info = "Binds when picked up\nUnique\nClasses: Rogue\n[q2]Engrave your boots with the Waylay rune:\n\n\nYour Ambush and Backstab hits unbalance your target, increasing the time between their melee attacks by 10%, and reducing movement speed by 50% for 8 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[213138] = {name = "[q2]Rune of the Southpaw", additional_info = "Binds when picked up\nUnique\nClasses: Rogue\n[q2]Engrave your boots with the Rolling with the Punches rune:\n\n\nEach time you Dodge or Parry, you gain 5% increased Health, stacking up to 5 times.\n[q]\"Teaches you a new Engraving ability.\""},
[213139] = {name = "[q2]Rune of the Assassin", additional_info = "Binds when picked up\nUnique\nClasses: Rogue\n[q2]Engrave your belt with the Shuriken Toss rune:\n\n\nThrow a shuriken at your enemy dealing damage equal to 50% of your Attack Power, and also strike up to 4 additional nearby targets. Awards 1 combo point per target hit.\n[q]\"Teaches you a new Engraving ability.\""},
[213140] = {name = "[q2]Prophecy of the Quickened Path", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Engrave your belt with the Empowered Renew rune:\n\n\nYour Renew now heals one extra time immediately when applied, and gains 15% increased benefit each time it heals from your bonus healing effects.\n\n In addition, your Renew can now be active on targets affected by another Priest's Renew.\n\n[q2]Use: Focus on the Prophecy to learn a new spell. Requires a mind focused by meditating on two spiritual mysteries of Azeroth."},
[213141] = {name = "[q2]Rune of Hope", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Engrave your belt with the Renewed Hope rune:\n\n\nYour heals from Flash Heal, Lesser Heal, Heal, Greater Heal, and Penance have 20% increased effect when cast on targets with Weakened Soul.\n[q]\"Teaches you a new Engraving ability.\""},
[213142] = {name = "[q2]Prophecy of Imprisoned Malice", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Engrave your boots with the Dispersion\n rune:\n\n\nYou disperse into pure Shadow energy, reducing all damage taken by 90%. You are unable to attack or cast spells, but you regenerate 6% mana every 1 sec for 6 sec. Dispersion can be cast while stunned, feared or silenced and clears all snare and movement impairing effects when cast, and makes you immune to them while dispersed.\n\n[q2]Use: Focus on the Prophecy to learn a new spell. Requires a mind focused by meditating on two spiritual mysteries of Azeroth."},
[213143] = {name = "[q2]Apocryphal Epiphany", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Engrave your boots with the Pain Suppression rune:\n\n\nInstantly reduces all damage taken by a friendly target by 40% and increases resistance to Dispel mechanics by 65% for 8 sec.\n[q]\"Learn a new Engraving ability.\""},
[213144] = {name = "[q2]Luminous Epiphany", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Engrave your boots with the Spirit of the Redeemer rune:\n\n\nActivate to become the Spirit of Redemption for 10 sec. While in this form, you can cast any healing spell free of cost, but you cannot move, attack, be attacked, or be targeted by any spells or effects. Requires Spirit of Redemption talent to activate, and you will no longer enter Spirit of Redemption upon dying.\n[q]\"Teaches you a new Engraving ability.\""},
[213165] = {name = "Basilisks: Should Petrification be Feared?", additional_info = "Binds when picked up\nUnique\n[q]\"Attempted research on the use of basilisk parts as reagents. A fine addition to any library's collection.\""},
[213369] = {name = "[q3]Faintly Glowing Leather", additional_info = "Sell Price:"},
[213370] = {name = "[q2]Irradiated Leather Scraps", additional_info = "Binds when picked up\n[q]\"A skilled leatherworker may be able to fashion this into something useful.\""},
[213371] = {name = "[q2]Crate of Tainted Gniodine Solution", additional_info = "Binds when picked up\n[q]\"A skilled alchemist may be able to fashion this into something useful.\""},
[213373] = {name = "[q2]Reflective Scrapmetal", additional_info = "Binds when picked up\n[q]\"A skilled blacksmith may be able to fashion this into something usable.\""},
[213376] = {name = "[q3]Low-Background Truesilver Plates", additional_info = nil},
[213378] = {name = "[q2]Unstable Microfilament", additional_info = "Binds when picked up\n[q]\"A skilled tailor may be able to fashion this into something useful.\""},
[213379] = {name = "[q3]Hyperconductive Arcano-Filament", additional_info = "Sell Price:"},
[213381] = {name = "[q2]Pile of Tarnished Gears", additional_info = "Binds when picked up\n[q]\"A skilled engineer may be able to fashion this into something useful.\""},
[213383] = {name = "[q3]Polished Truesilver Gears", additional_info = nil},
[213421] = {name = "Singed Note", additional_info = "Binds when picked up\nClasses: Mage\n[q2]<Right Click to Read>"},
[213422] = {name = "Illegible Recipe", additional_info = "Binds when picked up\nThis Item Begins a Quest"},
[213426] = {name = "Ogre Lightning Rod", additional_info = "Binds when picked up\nUnique\n[q2]Use: Plant into Soft Soil."},
[213427] = {name = "[q2]Grime-Encrusted Salvage", additional_info = nil},
[213443] = {name = "Ticking Present", additional_info = "Binds when picked up\n[q2]<Right Click to Open>"},
[213444] = {name = "Tarnished Prayer Bead I", additional_info = "Binds when picked up\nUnique\n[q]\"May those who stand against us know our might.\""},
[213445] = {name = "Tarnished Prayer Bead II", additional_info = "Binds when picked up\nUnique\n[q]\"May the Light shield us when we are wounded.\""},
[213446] = {name = "Tarnished Prayer Bead III", additional_info = "Binds when picked up\nUnique\n[q]\"May the wicked and cowardly be brought to justice\""},
[213452] = {name = "[q2]Dormant Holy Rune", additional_info = "Binds when picked up\nUnique\nClasses: Paladin\n[q]\"First, you must lay down your life for another. Then, before your spirit departs, have your salvation returned in kind.\""},
[213513] = {name = "[q2]Libram of Deliverance", additional_info = "Binds when picked up\nUnique\n{Relic} {Libram}\nClasses: Paladin\nRequires Level 18\n[q2]Engrave your boots with the Sacred Shield rune:\n\n\nEach time the target takes damage they gain a Sacred Shield, absorbing [36 * (38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) / 100] damage and increasing the Paladin's chance to critically hit with Flash of Light by 50% for up to 6 sec. In addition, causes your Flash of Light to heal targets with Sacred Shield for an additional 100% over 12 sec. They cannot gain this effect more than once every 6 sec. Lasts 1 min. This spell cannot be on more than one target at any one time.\n[q]\"Learn a new ability after using Blessing of Freedom to free others from movement impairing effects 5 times.\""},
[213526] = {name = "Hybrid Haunch", additional_info = "Binds when picked up\nUnique\n[q]\"Tastes like beef *and* chicken.\""},
[213527] = {name = "Smuggler's Spice Blend", additional_info = "Binds when picked up\nUnique\n[q]\"The crown jewel of any ship's galley. Could make a boot taste good.\""},
[213528] = {name = "Balmy Brew", additional_info = "Binds when picked up\nUnique\n[q]\"Not exactly a 'cold one' per-se\""},
[213529] = {name = "Viscous Venom", additional_info = "Binds when picked up\nUnique\n[q]\"Eats through swamp critters like they're nothing. Great for marinades!\""},
[213543] = {name = "Scroll: UPDOG", additional_info = "Classes: Mage\n[q2]Use: Decipher the scroll with a Comprehension Charm. Who knows what magic it contains?\nSell Price:"},
[213544] = {name = "Scroll: TOPAZ YORAK", additional_info = "Classes: Mage\n[q2]Use: Decipher the scroll with a Comprehension Charm. Who knows what magic it contains?\nSell Price:"},
[213545] = {name = "Scroll: PEATCHY ATTAX", additional_info = "Classes: Mage\n[q2]Use: Decipher the scroll with a Comprehension Charm. Who knows what magic it contains?\nSell Price:"},
[213546] = {name = "Scroll: SHOOBEEDOOP", additional_info = "Classes: Mage\n[q2]Use: Decipher the scroll with a Comprehension Charm. Who knows what magic it contains?\nSell Price:"},
[213547] = {name = "Scroll: THAW WORDS", additional_info = "Classes: Mage\n[q2]Use: Decipher the scroll with a Comprehension Charm. Who knows what magic it contains?\nSell Price:"},
[213548] = {name = "Scroll of Liminal Passage", additional_info = "Classes: Mage\nRequires Level 6\n\n[q2]Use: Teleport to a party member. Both you and the target must be resting at an inn or city.\nSell Price:"},
[213549] = {name = "Scroll of Arcane Angling", additional_info = "Classes: Mage\nRequires Level 12\nSell Price:"},
[213550] = {name = "Scroll of Polymorph: Odd Melon", additional_info = "Binds when picked up\nClasses: Mage\nRequires Level 16\n\n[q2]Use: Polymorph the target into an Odd Melon. (5 Sec Cooldown)\nSell Price:"},
[213551] = {name = "Scroll of Controlled Displacement", additional_info = "Classes: Mage\nRequires Level 12\nSell Price:"},
[213552] = {name = "Tear of Theradras", additional_info = "Binds when picked up\nUnique\n[q]\"Hoarded and closely guarded by the Gelkis centaur tribe, these are said to grant their wielder the protection of the earthen spirits.\""},
[213553] = {name = "Tear of Theradras", additional_info = "Binds when picked up\nUnique\n[q]\"Hoarded and closely guarded by the Gelkis centaur tribe, these are said to grant their weilder the protection of the earthen spirits.\""},
[213554] = {name = "Vial of Crystal Water", additional_info = "Binds when picked up\nUnique\n[q2]Use: Mix with the Tears of Theradras to create an Elemental Salve capable of purifying corruption.\n[q]\"The water is so crystal clear that the vial seems empty.\""},
[213558] = {name = "Elemental Salve", additional_info = "[q2]Use: Pour over corrupted objects to cleanse them.\n[q]\"A potent salve capable of cleansing deep corruption.\""},
[213562] = {name = "Bug Catching Net", additional_info = "Binds when picked up\n[q2]Use: Catch an exotic bug, and keep it as a specimen. (30 Sec Cooldown)"},
[213563] = {name = "Field Guide", additional_info = "Binds when picked up\n[q2]<Right Click to Read>"},
[213564] = {name = "Scroll of Minor Evocation", additional_info = "Classes: Mage\n[q2]Use: Restores mana. (8 Min Cooldown)\nSell Price:"},
[213565] = {name = "Entomology Starter Kit", additional_info = "Binds when picked up\nUnique\nClasses: Hunter , Druid\n[q2]<Right Click to Open>"},
[213566] = {name = "Arbor Tarantula Specimen", additional_info = "Binds when picked up\nUnique"},
[213567] = {name = "Flesh Picker Specimen", additional_info = "Binds when picked up\nUnique"},
[213568] = {name = "Hay Weevil Specimen", additional_info = "Binds when picked up\nUnique"},
[213583] = {name = "[q2]Brimstone Carving", additional_info = "Binds when picked up\nUnique\n[q]\"It appears the previous owner played with fire one too many times.\""},
[213594] = {name = "[q2]Idol of the Heckler", additional_info = "Binds when picked up\nUnique\n{Relic} {Idol}\nClasses: Druid\nRequires Level 28\n[q2]Engrave your belt with the Berserk rune:\n\n\nWhen activated, this ability causes your Mangle (Bear) and Lacerate abilities to hit up to 3 targets, Lacerate to cost no Rage, Mangle (Bear) to have no cooldown, and reduces the energy cost of all your Cat Form abilities by 50%. Lasts 15 sec. Requires Bear Form, Cat Form, or Dire Bear Form to activate.\n\n Clears the effect of Fear and makes you immune to Fear for the duration.\n[q]\"Taunt 2 or more enemies with Challenging Roar, and kill at least one of them. After 3 kills, use this idol to learn a new ability.\""},
[213599] = {name = "[q2]Unsettling Vision", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Engrave your belt with the Renewed Hope rune:\n\n\nYour heals from Flash Heal, Lesser Heal, Heal, Greater Heal, and Penance have 20% increased effect when cast on targets with Weakened Soul.\n\n[q2]Use: Focus on the Vision to learn a new spell. Requires a glimpse of corrupt knowledge."},
[213632] = {name = "[q2]Partial Spell Notes", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Use: Combine the collected Partial Spell Notes into a scroll that will teach a new Engraving spell.\n[q]\"An incomplete page that appears similar to scrolls that teach Engraving abilities. Two-thirds are missing.\""},
[213633] = {name = "[q2]Partial Spell Notes", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Use: Combine the collected Partial Spell Notes into a scroll that will teach a new Engraving spell.\n[q]\"An incomplete page that appears similar to scrolls that teach Engraving abilities. Two-thirds are missing.\""},
[213634] = {name = "[q2]Partial Spell Notes", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Use: Combine the collected Partial Spell Notes into a scroll that will teach a new Engraving spell.\n[q]\"An incomplete page that appears similar to scrolls that teach Engraving abilities. Two-thirds are missing.\""},
[213701] = {name = "Strong Harpy Feather", additional_info = "Binds when picked up\nUnique (10)\n[q2]Use: Combine 10 Strong Harpy Feathers and 3 Cloud Serpent Fangs with 1 Silken Thread to create an Offering to the Wind Spirit."},
[213709] = {name = "Cloud Serpent Fang", additional_info = "Binds when picked up\nUnique (3)\n[q2]Use: Combine 10 Strong Harpy Feathers and 3 Cloud Serpent Fangs with 1 Silken Thread to create an Offering to the Wind Spirit."},
[213735] = {name = "[q3]Pristine G-7 C.O.R.E. Processor", additional_info = "Binds when picked up\n[q]\"This thing can pre-render over 4 million gigaflops of low-variance relational codebursts. Wow!\""},
[213736] = {name = "[q2]Corroded G-7 C.O.R.E. Processor", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\n[q]\"This processor core is caked with corrosion and a sticky black substance but you can barely make out a model number and a few illegible words through the gunk. You may need a specialist to help restore it.\""},
[213737] = {name = "Offering to the Wind Spirit", additional_info = "Binds when picked up\nUnique\n[q2]Use: Make an Offering to the Wind Spirit and show your faith."},
[214435] = {name = "Cougar Cage Key", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Use: Opens Cougar Cage"},
[215127] = {name = "[q2]High-Yield Radiation Bomb", additional_info = "Requires Level 35\nRequires Engineering (200)\n\n[q2]Use: Inflicts 150 to 250 fire damage to those in the blast radius plus an additional 25 nature damage every 2 sec for 10 seconds. Also reduces the movement speed of affected targets by 25% for until cancelled. (1 Min Cooldown)\nSell Price:"},
[215129] = {name = "[q4]Formula: Enchant Weapon - Dismantle", additional_info = "Binds when picked up\nRequires Enchanting (225)\n\n[q2]Use: Permanently enchant a Weapon to cause all spells and attacks to sometimes deal 60 to 90 additional damage to mechanical creatures.\nSell Price:"},
[215138] = {name = "[q4]Formula: Enchant Chest - Retricutioner", additional_info = "Binds when picked up\nRequires Enchanting (225)\n\n[q2]Use: Teaches you how to permanently enchant a piece of chest armor to reflect 9 damage back to the attacker when the bearer is struck in Melee.\nSell Price:"},
[215141] = {name = "[q2]Enchanted Sigil: Innovation", additional_info = "Binds when picked up\nRequires Enchanting (225)\n\n[q2]Use: Teaches you how to conjure a sigil of innovation.\nSell Price: \n[q2]Enchanted Sigil: Innovation\nBinds when picked up\nUnique (5)\nRequires Level 40\nRequires Enchanting (225)\n\n[q2]Use: Gain an enchanted sigil of innovation, empowering you to deal up to 20 increased damage and healing with spells, and increasing attack power by 20 for 30 min. This can only be applied outside of combat. (30 Min Cooldown)\nRequires Vision Dust (5)"},
[215149] = {name = "[q4]Pattern: Gneuro-Linked Arcano-Filament Monocle", additional_info = "Binds when picked up\nRequires Tailoring (225)\n\n[q2]Use: Teaches you how to craft a Gneuro-Linked Arcano-Filament Monocle.\nSell Price: \n[q4]Gneuro-Linked Arcano-Filament Monocle\nBinds when picked up\n{Head} {Cloth}\n58 Armor\n+10 Stamina\n+11 Intellect\nDurability 60 / 60\nRequires Level 40\nRequires Tailoring (225)\n[q2]Equip: Increases damage and healing done by magical spells and effects by up to 22.\n\n[q2]Equip: Restores 4 mana per 5 sec.\n\n[q2]Use: Harness the latent arcane energy in the nearby air to give you charged inspiration, reducing the mana cost of all spells by 50% and increasing damage and healing done by up to 50 for 12 sec. (10 Min Cooldown)\nSell Price: \nRequires Hyperconductive Arcano-Filament (5), Faintly Glowing Leather , Insulating Gniodine , Vision Dust (10), Bolt of Mageweave (10)"},
[215152] = {name = "[q4]Pattern: Glowing Gneuro-Linked Cowl", additional_info = "Binds when picked up\nRequires Leatherworking (225)\n\n[q2]Use: Teaches you how to craft a Glowing Gneuro-Linked Cowl.\nSell Price: \n[q4]Glowing Gneuro-Linked Cowl\nBinds when picked up\n{Head} {Leather}\n118 Armor\n+14 Agility\n+14 Stamina\nDurability 70 / 70\nRequires Level 40\nRequires Leatherworking (225)\n[q2]Equip: Improves your chance to hit with all spells and attacks by 1%.\n\n[q2]Equip: +3 Weapon Damage.\n\n[q2]Use: Inflicts gneuro-logical shock, instantly dealing 343 to 757 damage to yourself but also increasing your melee and ranged attack speed by 20% for 10 sec. (10 Min Cooldown)\nSell Price: \nRequires Hyperconductive Arcano-Filament , Cured Thick Hide (5), Silken Thread (2), Faintly Glowing Leather (5)"},
[215153] = {name = "[q4]Schematic: Whirling Truesilver Gearwall", additional_info = "Binds when picked up\nRequires Engineering (225)\n\n[q2]Use: Teaches you how to make a Whirling Truesilver Gearwall.\nSell Price: \n[q4]Whirling Truesilver Gearwall\nBinds when picked up\n{Off Hand} {Shield}\n1760 Armor\n29 Block\n+9 Strength\n+10 Stamina\nDurability 120 / 120\nRequires Level 40\nRequires Engineering (225)\n[q2]Equip: Increases your chance to block attacks with a shield by 1%.\n\n[q2]Equip: On a successful block the whirling razor-sharp gears on this shield inflict 5 to 10 physical damage to the attacker and 2 to 10 physical damage to the bearer.\n[q]\"The rotating edges on this shield are surprisingly sharp. This seems just as dangerous for the bearer as it is to the attacker.\"\nSell Price: \nRequires Low-Background Truesilver Plates (3), Polished Truesilver Gears (5), Faintly Glowing Leather (2), Mithril Casing (2), Gyrochronatom (2), Mithril Bar (15)"},
[215155] = {name = "[q4]Plans: Temepered Interference-Negating Helmet", additional_info = "Binds when picked up\nRequires Blacksmithing (225)\n\n[q2]Use: Teaches you how to make a Tempered Interference-Negating Helmet\nSell Price: \n[q4]Tempered Interference-Negating Helmet\nBinds when picked up\n{Head} {Plate}\n426 Armor\n+20 Strength\n+14 Stamina\nDurability 100 / 100\nRequires Level 40\nRequires Blacksmithing (225)\n[q2]Equip: Improves your chance to get a critical strike with all spells and attacks by 1%.\n\n[q2]Use: Gain intense concentration, reducing movement speed by 20%, but also increasing your spell resistance to all schools by 50, and increasing melee attack speed by 20% for 10 sec. (10 Min Cooldown)\n[q]\"Guaranteed to protect your brain from all threats, physical and otherwise!\"\nSell Price: \nRequires Mithril Bar (25), Low-Background Truesilver Plates (4), Hyperconductive Arcano-Filament , Faintly Glowing Leather (2)"},
[215156] = {name = "[q4]Schematic: Hyperconductive Goldwrap", additional_info = "Binds when picked up\nRequires Engineering (225)\n\n[q2]Use: Teaches you how to make a Hyperconductive Goldwap\nSell Price:\n[q4]Hyperconductive Goldwrap\nBinds when picked up\n{Waist} {Cloth}\n40 Armor\n+9 Stamina\nDurability 35 / 35\nRequires Level 40\nRequires Engineering (225)\n[q2]Equip: Improves your chance to get a critical strike with all spells and attacks by 1%.\n\n[q2]Equip: Improves your chance to hit with all spells and attacks by 1%.\n\n[q2]Use: Pull a hyperconductive coin from your belt and flip it. Heads: gain 3% increased critical strike chance with all spells and attacks for 30 sec. Tails: gain 10% movement speed for 30 sec. (15 Min Cooldown)\n[q]\"This belt clinks faintly as you move.\"\nSell Price: \nRequires Polished Truesilver Gears (3), Hyperconductive Arcano-Filament (3), Faintly Glowing Leather , Gold Bar (10)"},
[215163] = {name = "[q4]Recipe: Mildly-Irradiated Rejuvenation Potion", additional_info = "Binds when picked up\nRequires Alchemy (225)\n\n[q2]Use: Teaches you how to brew a Mildly Irradiated Rejuvenation Potion.\nSell Price: \nMildly Irradiated Rejuvenation Potion\nRequires Level 35\n\n[q2]Use: Restores 262 to 438 mana and 340 to 460 health. Also increases attack power by 40 and damage done by all spells by 35 for 20 sec. (2 Min Cooldown)\n[q]\"Side Effects Can Include: Dizzyness, Dry Mouth, Fatigue, Lack of Appetite, Acute Radiation Poisoning, Mutation, and Death. Use as directed.\"\nSell Price: \nRequires Crate of Tainted Gniodine Solution , Minor Rejuvenation Potion , Gnomeregan Fallout (3), Crystal Vial (5)"},
[215168] = {name = "[q2]Ez-Thro Radiation Bomb", additional_info = "Requires Level 40\n\n[q2]Use: Inflicts 112 to 188 fire damage to those in the blast radius plus an additional 10 nature damage every 2 sec for 10 seconds. Also reduces the movement speed of affected targets by 25% for 10 sec. (1 Min Cooldown)\n[q]\"A tune-downed but no less deadly version of its more complex counterpart for those that lack competence but have an abundance of confidence.\"\nSell Price:"},
[215257] = {name = "Scroll of Comprehension", additional_info = "Classes: Mage\n[q2]Use: Create 2 Comprehension Charms, or 4 if you are resting in an inn or city.\nSell Price:"},
[215365] = {name = "[q2]Invoker's Mantle", additional_info = "Binds when equipped\n{Shoulder} {Cloth}\n32 Armor\n+5 Intellect\nDurability 45 / 45\nRequires Level 25\n[q2]Equip: Increases damage and healing done by magical spells and effects by up to 7.\nSell Price:"},
[215366] = {name = "[q2]Invoker's Cord", additional_info = "Binds when equipped\n{Waist} {Cloth}\n24 Armor\n+5 Intellect\nDurability 25 / 25\nRequires Level 25\n[q2]Equip: Increases damage and healing done by magical spells and effects by up to 7.\nSell Price:"},
[215367] = {name = "[q3]Pattern: Faintly Glowing Leather", additional_info = "Binds when picked up\nRequires Leatherworking (200)\n\n[q2]Use: Teaches you how to craft a bundle of Faintly Glowing Leather.\nSell Price: \n[q3]Faintly Glowing Leather\nSell Price: \nRequires Cured Thick Hide , Irradiated Leather Scraps (5)"},
[215368] = {name = "[q3]Pattern: Hyperconductive Arcano-Filament", additional_info = "Binds when picked up\nRequires Tailoring (200)\n\n[q2]Use: Teaches you how to craft a spool of Hyperconductive Arcano-Filament.\nSell Price: \n[q3]Hyperconductive Arcano-Filament\nSell Price: \nRequires Bolt of Mageweave (2), Unstable Microfilament (5), Heavy Silken Thread (5)"},
[215369] = {name = "[q2]Pattern: Invoker's Cord", additional_info = "Requires Tailoring (150)\n\n[q2]Use: Teaches you how to sew Invoker's Cord.\nSell Price: \n[q2]Invoker's Cord\nBinds when equipped\n{Waist} {Cloth}\n24 Armor\n+5 Intellect\nDurability 25 / 25\nRequires Level 25\n[q2]Equip: Increases damage and healing done by magical spells and effects by up to 7.\nSell Price: \nRequires Bolt of Silk Cloth (3), Shadowgem , Fine Thread , Gray Dye"},
[215370] = {name = "[q2]Pattern: Invoker's Mantle", additional_info = "Requires Tailoring (150)\n\n[q2]Use: Teaches you how to sew Invoker's Mantle.\nSell Price: \n[q2]Invoker's Mantle\nBinds when equipped\n{Shoulder} {Cloth}\n32 Armor\n+5 Intellect\nDurability 45 / 45\nRequires Level 25\n[q2]Equip: Increases damage and healing done by magical spells and effects by up to 7.\nSell Price: \nRequires Bolt of Silk Cloth (4), Gray Dye (4), Fine Thread , Blue Dye (4)"},
[215373] = {name = "Silver Hand Training Hammer", additional_info = "{Two-Hand} {Mace}\n{53 - 81 Damage} {Speed 3.40}\n(19.71 damage per second)\nDurability 65 / 65\nRequires Level 26\n[q]\"Recovered from Theramore Isle where its owner was slain in battle against bloodthirsty orcish hordes.\"\nSell Price:"},
[215374] = {name = "Ancestral Sword", additional_info = "{Two-Hand} {Sword}\n{17 - 46 Damage} {Speed 3.10}\n(10.16 damage per second)\nDurability 65 / 65\nRequires Level 26\n[q]\"Passed down by a noble Lordaeron family. Once thought to be lost in the swamps around Kyross along with the last warrior to wield it.\"\nSell Price:"},
[215375] = {name = "Tactician's Staff", additional_info = "{Two-Hand} {Staff}\n{16 - 49 Damage} {Speed 3.50}\n(9.29 damage per second)\nDurability 65 / 65\nRequires Level 26\n[q]\"Its owner's keen grasp of battlefield tactics was matched only by her fearsome command of frost and flame.\"\nSell Price:"},
[215376] = {name = "Crusader's Mace", additional_info = "{Main Hand} {Mace}\n{21 - 36 Damage} {Speed 2.90}\n(9.83 damage per second)\nDurability 65 / 65\nRequires Level 26\n[q]\"Flecked with dried bits of insect carapace.\"\nSell Price:"},
[215383] = {name = "[q4]Plans: Reflective Truesilver Braincage", additional_info = "Binds when picked up\nRequires Blacksmithing (225)\n\n[q2]Use: Teaches you how to make a Reflective Truesilver Braincage.\nSell Price: \n[q4]Reflective Truesilver Braincage\nBinds when picked up\n{Head} {Plate}\n426 Armor\n+14 Stamina\n+15 Intellect\nDurability 100 / 100\nRequires Level 40\nRequires Blacksmithing (225)\n[q2]Equip: Increases damage and healing done by magical spells and effects by up to 21.\n\n[q2]Use: Gain reinforced willpower, preventing Silence, Interrupt effects, and spell pushback for 10 sec. (10 Min Cooldown)\nSell Price: \nRequires Mithril Bar (25), Low-Background Truesilver Plates (4), Hyperconductive Arcano-Filament (2), Polished Truesilver Gears"},
[215384] = {name = "[q3]Plans: Low-Background Truesilver Plates", additional_info = "Binds when picked up\nRequires Blacksmithing (200)\n\n[q2]Use: Teaches you how to make Low-Background Truesilver Plates.\nSell Price:\n[q3]Low-Background Truesilver Plates\nRequires Truesilver Bar , Reflective Scrapmetal (5)"},
