[215420] = {name = "[q2]Waylaid Supplies: Rockscale Cod", additional_info = "Binds when picked up\nUnique: Waylaid Shipment (12)\n[q2]Use: Add 40 Rockscale Cod to complete the shipment.\nSell Price:"},
[215421] = {name = "[q2]Waylaid Supplies: Fire Oil", additional_info = "Binds when picked up\nUnique: Waylaid Shipment (12)\n[q2]Use: Add 7 Fire Oil to complete the shipment.\nSell Price:"},
[215422] = {name = "[q4]Pattern: Glowing Hyperconductive Scale Coif", additional_info = "Binds when picked up\nRequires Leatherworking (225)\n\n[q2]Use: Teaches you how to craft a Glowing Hyperconductive Scale Coif.\nSell Price: \n[q4]Glowing Hyperconductive Scale Coif\nBinds when picked up\n{Head} {Mail}\n242 Armor\n+14 Stamina\n+15 Intellect\nDurability 85 / 85\nRequires Level 40\nRequires Leatherworking (225)\n[q2]Equip: Increases damage and healing done by magical spells and effects by up to 21.\n\n[q2]Use: Inflicts hyperconductive shock, instantly dealing 312 to 688 damage to yourself but also increasing your spell casting speed by 20% for 10 sec. (10 Min Cooldown)\nSell Price: \nRequires Low-Background Truesilver Plates , Thick Murloc Scale (10), Faintly Glowing Leather (5), Insulating Gniodine"},
[215423] = {name = "[q4]Pattern: Gneuro-Conductive Channeler's Hood", additional_info = "Binds when picked up\nRequires Leatherworking (225)\n\n[q2]Use: Teaches you how to craft a Gneuro-Conductive Channeler's Hood.\nSell Price: \n[q4]Gneuro-Conductive Channeler's Hood\nBinds when picked up\n{Head} {Leather}\n118 Armor\n+11 Stamina\n+12 Intellect\n+11 Spirit\nDurability 70 / 70\nRequires Level 40\nRequires Leatherworking (225)\n[q2]Equip: Increases damage and healing done by magical spells and effects by up to 21.\n\n[q2]Use: Gain gneuromantic meditation, allowing 100% of your mana regeneration to continue while casting and increasing damage and healing done by spells by up to 50 for 20 sec. (10 Min Cooldown)\nSell Price: \nRequires Insulating Gniodine , Cured Thick Hide (5), Faintly Glowing Leather (5), Hyperconductive Arcano-Filament"},
[215424] = {name = "[q4]Pattern: Rad-Resistant Scale Hood", additional_info = "Binds when picked up\nRequires Leatherworking (225)\n\n[q2]Use: Teaches you how to craft a Rad-Resistant Scale Hood.\nSell Price: \n[q4]Rad-Resistant Scale Hood\nBinds when picked up\n{Head} {Mail}\n[q2]342 Armor\n+10 Stamina\n+10 Intellect\nDurability 85 / 85\nRequires Level 40\nRequires Leatherworking (225)\n[q2]Equip: Improves your chance to hit with all spells and attacks by 1%.\n\n[q2]Equip: +32 Attack Power.\n\n[q2]Use: Engage the radiation mitigation protocols in this helmet, causing you to immediately remove all active poison effects and gain immunity to all Nature damage for 3 sec. (10 Min Cooldown)\nSell Price: \nRequires Low-Background Truesilver Plates , Cured Thick Hide (5), Faintly Glowing Leather (5), Insulating Gniodine"},
[215425] = {name = "Swamp Echo", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Use: Honor the archivists."},
[215426] = {name = "Graveyard Echo", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Use: Honor the archivists."},
[215427] = {name = "Arathi Echo", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Use: Honor the archivists."},
[215428] = {name = "Theramore Echo", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Use: Honor the archivists."},
[215429] = {name = "[q3]Schematic: Polished Truesilver Gears", additional_info = "Binds when picked up\nRequires Engineering (200)\n\n[q2]Use: Teaches you how to make a set of Polished Truesilver Gears.\nSell Price: \n[q3]Polished Truesilver Gears\nRequires Truesilver Bar , Pile of Tarnished Gears (5)"},
[215430] = {name = "Gnomeregan Fallout", additional_info = "Sell Price:"},
[215431] = {name = "[q4]Schematic: High-Yield Radiation Bomb", additional_info = "Binds when picked up\nRequires Engineering (225)\n\n[q2]Use: Teaches you how to make a bundle of High-Yield Radiation Bombs.\nSell Price: \n[q2]High-Yield Radiation Bomb\nRequires Level 35\nRequires Engineering (200)\n\n[q2]Use: Inflicts 150 to 250 fire damage to those in the blast radius plus an additional 25 nature damage every 2 sec for 10 seconds. Also reduces the movement speed of affected targets by 25% for until cancelled. (1 Min Cooldown)\nSell Price:\nRequires Solid Blasting Powder , Gnomeregan Fallout , Mithril Bar (2)"},
[215432] = {name = "[q4]Schematic: Ez-Thro Radiation Bomb", additional_info = "Binds when picked up\nRequires Engineering (225)\n\n[q2]Use: Teaches you how to make an Ez-Thro Radiation Bombs.\nSell Price: \n[q2]Ez-Thro Radiation Bomb\nRequires Level 40\n\n[q2]Use: Inflicts 112 to 188 fire damage to those in the blast radius plus an additional 10 nature damage every 2 sec for 10 seconds. Also reduces the movement speed of affected targets by 25% for 10 sec. (1 Min Cooldown)\n[q]\"A tune-downed but no less deadly version of its more complex counterpart for those that lack competence but have an abundance of confidence.\"\nSell Price:\nRequires Solid Blasting Powder (2), Gnomeregan Fallout , Mithril Bar (2)"},
[215433] = {name = "[q3]Recipe: Insulating Gniodine", additional_info = "Binds when picked up\nRequires Alchemy (200)\n\n[q2]Use: Teaches you how to distill a vial of Insulating Gniodine.\nSell Price:\n[q3]Insulating Gniodine\nRequires Leaded Vial , Crate of Tainted Gniodine Solution (5)"},
[215441] = {name = "[q2]Broken Hammer", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\n[q]\"This ornate warhammer is stamped with the insigina of the Silver Hand\""},
[215443] = {name = "Shattered Orb Fragment", additional_info = "Binds when picked up\nUnique\n[q]\"The remains of the shattered orb glow faintly and are warm to the touch.\""},
[215450] = {name = "Tabard Project (Aidan)", additional_info = "Binds when picked up\nUnique\nTabard\nRequiresThe League of Arathor\n- Exalted\nSell Price:"},
[215456] = {name = "Singed Message", additional_info = "[q]\"Told you so.\""},
[215458] = {name = "Enclosed Message", additional_info = "Classes: Rogue\n[q]\"Seriously, DO NOT try to open the final box. You already got what you wanted.\""},
[215459] = {name = "Enclosed Message", additional_info = "Classes: Rogue\n[q]\"Stop now. This is your final warning.\""},
[215460] = {name = "Enclosed Message", additional_info = "Classes: Rogue\n[q]\"BEWARE! The box beside this note should never be opened.\""},
[215468] = {name = "Orders from the Grand Crusader", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\n[q]\"The letter is crumpled and there are flecks of dried blood on it.\""},
[215683] = {name = "Geomancy: The Stone-Cold Truth", additional_info = "Binds when picked up\nUnique\n[q]\"Theories on the origin and usage of elemental magic. A fine addition to any library's collection.\""},
[215815] = {name = "Defensive Magics 101", additional_info = "Binds when picked up\nUnique\n[q]\"An introductory guide to defensive magic and barriers. A fine addition to any library's collection.\""},
[215816] = {name = "A Web of Lies: Debunking Myths and Legends", additional_info = "Binds when picked up\nUnique\n[q]\"An incomplete thesis claiming spiders are harmless, but nevertheless a fine addition to any library's collection.\""},
[215817] = {name = "Demons and You", additional_info = "Binds when picked up\nUnique\n[q]\"A strange text defending demons, yet nevertheless a fine addition to any library's collection.\""},
[215820] = {name = "Mummies: A Guide to the Unsavory Undead", additional_info = "Binds when picked up\nUnique\n[q]\"Tales frightening enough to scare even the most hardy of warriors. A fine addition to any library's collection.\""},
[215822] = {name = "RwlRwlRwlRwl!", additional_info = "Binds when picked up\nUnique\n[q]\"The strange passages are faint but somewhat readable despite water damage. A fine addition to any library's collection.\""},
[215824] = {name = "A Ludite's Guide to Caring for Your Demonic Pet", additional_info = "Binds when picked up\nUnique\n[q]\"Contains useful tips for keeping pet imps out of your reagents. A fine addition to any library's collection.\""},
[216483] = {name = "Witherbark Mallet", additional_info = "Unique\n[q2]Use: Strike the gong inside the Witherbark's den."},
[216491] = {name = "Shipment of Stranglethorn Lumber", additional_info = "Binds when picked up\n[q]\"A shipment of lumber from Stranglethorn Vale that can be of use to your faction in Arathi Highlands.\""},
[216492] = {name = "[q3]Whistle of the Mottled Blood Raptor", additional_info = "Binds when picked up\nUnique\nMount\nRequires Level 40\n\n[q2]Use: Summons and dismisses a rideable Raptor. (3 Sec Cooldown)"},
[216523] = {name = "Rusted Cage Key", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Use: Opens Rusted Cage"},
[216606] = {name = "[q2]Rune of Two-Handed Mastery", additional_info = "Binds when picked up\nUnique\nClasses: Shaman\n[q2]Engrave your chest or robe with the Two-Handed Mastery rune:\n\n\nEach time you strike an enemy with a two-handed weapon, you gain 45% attack speed with two-handed weapons, 10% increased Attack Power, and 10% increased chance to hit with spells for 10 sec. This effect is lost if you strike an enemy with a one-handed weapon.\n[q]\"Teaches you a new Engraving ability.\""},
[216610] = {name = "Orders from the Grand Crusader", additional_info = "Quest Item\nUnique\n[q2]<Right Click to Read>"},
[216616] = {name = "Compound Cage Key", additional_info = "Binds when picked up\nUnique"},
