[216618] = {name = "Captain Aransas' Reward", additional_info = "Binds when picked up\nUnique\n[q2]<Right Click to Open>"},
[216619] = {name = "[q2]Student Fodder", additional_info = "Binds when picked up\n[q2]Use: Eat a handful and make up for lost time on the trail! (30 Min Cooldown)\n[q]\"Good ole raisins and peanuts...and more!\""},
[216633] = {name = "Hydraulic Truesilver Strut", additional_info = "Binds when picked up\nUnique"},
[216634] = {name = "GG12-082 Cartridge Fuse", additional_info = "Quest Item"},
[216635] = {name = "[q2]Spent Voidcore", additional_info = "Binds when picked up\nUnique\n[q2]Use: Combine with an appropriate power source to create a Charged Voidcore. (3 Sec Cooldown)\n[q]\"This seems to match the description of the voidcore that Wirdal needs, but it appears to be completely inert. There must be a way to recharge this...\""},
[216636] = {name = "Charged Voidcore", additional_info = "Binds when picked up\nUnique\n[q]\"This object seems to draw in all surrounding light and warmth. It is very cold to the touch.\""},
[216637] = {name = "A Pile of Random Parts", additional_info = "[q]\"Someone somewhere may find this stuff useful, but it just looks like junk to you.\"\nSell Price:"},
[216645] = {name = "[q2]Mote of Darkness", additional_info = "Binds when picked up\nUnique\n[q]\"Dark energy permeates this tiny floating speck of energy. Who knows what sort of amazing magics this could power?\""},
[216696] = {name = "[q2]Hidden Pants", additional_info = "Legs\nSell Price:"},
[216748] = {name = "[q2]Grimoire of Portal of Summoning", additional_info = "Binds when picked up\nUnique\nClasses: Warlock\n[q2]Begins a ritual that creates a summoning portal. The summoning portal can be used by 2 party or raid members to summon a targeted party or raid member. The ritual portal requires the caster and 2 additional party or raid members to complete. In order to participate, all players must be out of combat and right-click the portal and not move until the ritual is complete.\n[q]\"Teaches you Portal of Summoning.\""},
[216879] = {name = "Mysterious Troll Scroll", additional_info = "Unique\nClasses: Mage\n[q2]Use: Decipher the scroll with a Comprehension Charm. Who knows what magic it contains?\nSell Price:"},
