[217345] = {name = "Sebacious Poison", additional_info = "Classes: Rogue\nRequires Level 60\n\n[q2]Use: Coats a weapon with poison that lasts for 30 minutes.\n Each strike has a 30% chance of poisoning the enemy, reducing the enemy's armor by 1700 for 15 sec.\n\n Sebacious Poison benefits from the Improved Expose Armor talent. (Proc chance: 30%)\nSell Price:"},
[217346] = {name = "Numbing Poison", additional_info = "Classes: Rogue\nRequires Level 60\n\n[q2]Use: Coats a weapon with poison that lasts for 30 minutes.\n Each strike has a 30% chance of poisoning the enemy, increasing the time between the enemy's melee attacks by 20% for 15 sec. (Proc chance: 30%)\nSell Price:"},
[217347] = {name = "Atrophic Poison", additional_info = "Classes: Rogue\nRequires Level 60\n\n[q2]Use: Coats a weapon with poison that lasts for 30 minutes.\n Each strike has a 30% chance of poisoning the enemy, reducing the enemy's melee attack power by 205 for 15 sec. (Proc chance: 30%)\nSell Price:"},
[217398] = {name = "Lesser Arcane Elixir", additional_info = "Requires Level 28\n\n[q2]Use: Increases spell damage by up to 14 for 30 min. (3 Sec Cooldown)\nSell Price:"},
[217399] = {name = "[q2]Recipe: Lesser Arcane Elixir", additional_info = "Binds when picked up\nRequires Alchemy (190)\n\n[q2]Use: Teaches you how to make a Lesser Arcane Elixir.\nSell Price:\nLesser Arcane Elixir\nRequires Level 28\n\n[q2]Use: Increases spell damage by up to 14 for 30 min. (3 Sec Cooldown)\nSell Price:\nRequires Kingsblood , Goldthorn , Crystal Vial"},
[217495] = {name = "Scroll of Cryoblast", additional_info = "Classes: Mage\nRequires Level 26\n\n[q2]Use: Inflicts 183 to 247 Frost damage in a 5 yard radius. (1 Min Cooldown)\nSell Price:"},
[217496] = {name = "[q3]Scroll of the Blade", additional_info = "Binds when picked up\nClasses: Mage\nRequires Level 30\n\n[q2]Use: Use on Hypnotic Blade to create a powerful weapon.\nSell Price:"},
[217609] = {name = "Talisman of Kazdor", additional_info = "Binds when picked up\nUnique\n[q]\"The talisman bears a countenance of sheer malice. You avoid staring at it directly.\""},
[217693] = {name = "Invisibility Potion", additional_info = "Quest Item\n[q2]Use: Gives the imbiber invisibility for 30 sec. (2 Min Cooldown)"},
[217717] = {name = "Hollow Emblem", additional_info = "Binds when picked up\nUnique\n[q2]Use: Imbue a hollow emblem with blood magic essence."},
[217718] = {name = "Emblem of Blood Magic", additional_info = "Binds when picked up\nUnique"},
