[217736] = {name = "[q2]Rune of the Coterie", additional_info = "Binds when picked up\nUnique\nClasses: Rogue\n[q2]Engrave your helm with the Honor Among Thieves rune:\n\n\nWhen any player in your party critically hits with a spell or ability, you gain a combo point on your current target. This effect cannot occur more than once every second.\n[q]\"Teaches you a new Engraving ability.\""},
[217737] = {name = "Modified Talisman", additional_info = "Binds when picked up\nUnique"},
[219147] = {name = "[q2]Rune of Grace", additional_info = "Binds when picked up\nUnique\nClasses: Paladin\n[q2]Engrave your bracers with the Light's Grace rune:\n\n\nYour Holy Light spell reduces the cast time of your next Holy Light spell by 0.5 sec. Lasts 15 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[219345] = {name = "[q3]Infernal Lasso", additional_info = "Binds when picked up\nTrinket\nRequires Level 50\n[q2]Use: Roots target Demon or Beast in place and causes 200 Fire damage over 24 sec. Damage caused may interrupt the effect. Lassoed core hounds can be tamed. (1 Min Cooldown)"},
