[220106] = {name = "[q2]Deputization Authorization: Feralas Mission XVIII", additional_info = "Binds when picked up\nUnique\nDuration: 1 hour\n[q2]Use: Deputize a party member, sharing this quest with them so they can complete it with you.\n4 Charges\n[q]\"Allows you to share this mission with party members.\""},
[220164] = {name = "[q2]Rune of the Gladiator", additional_info = "Binds when picked up\nUnique\nClasses: Warrior\n[q2]Engrave your boots with the Gladiator Stance rune:\n\n\nAn aggressive stance that increases damage while you are wearing a shield by 10% and increases block chance by 10%, but reduces armor by 30% and threat generated by 30%. In addition, you gain 50% increased Rage when your auto-attack damages an enemy not targeting you.\n\n While wearing a shield in Gladiator Stance, you may use all abilities that are restricted to other stances.\n[q]\"Teaches you a new Engraving ability.\""},
[220165] = {name = "[q2]Rune of Wrath", additional_info = "Binds when picked up\nUnique\nClasses: Paladin\n[q2]Engrave your helm with the Wrath rune:\n\n\nYour Consecration damage can now be critical strikes, and damage from your Exorcism, Holy Shock, Sunlight, Holy Wrath, and Consecration spells gains additional critical strike chance equal to your melee critical strike chance.\n[q]\"Teaches you a new Engraving ability.\""},
[220166] = {name = "Fiery Infernal Core", additional_info = "Quest Item"},
[220167] = {name = "Shimmering Grave Dust", additional_info = "Quest Item\n[q]\"Grave dust from the resting place of one murdered by those most loved...\""},
[220168] = {name = "Triple-Brewed Molten Lager", additional_info = "Quest Item\nUnique\n[q]\"An elixir of fire, created with steady hands and an unsteady mind...\""},
[220169] = {name = "Symbol of Faith", additional_info = "Quest Item\n[q]\"A symbol of faith, gifted from one with newly discovered purpose...\""},
[220213] = {name = "Fel Lifeblood", additional_info = "Binds when picked up\nUnique"},
[220214] = {name = "Infernal Chain Link", additional_info = "Binds when picked up\nUnique (5)"},
[220216] = {name = "Infernal Lasso", additional_info = "Binds when picked up\n[q2]Use: Weaken Calefactus the Unleashed. (30 Sec Cooldown)"},
[220217] = {name = "[q2]Rune of the Ravenous", additional_info = "Binds when picked up\nClasses: Hunter\n[q2]Engrave your helm with the Rapid Killing rune:\n\n\nReduces the cooldown on Rapid Fire by 80%, Rapid Fire now also grants 40% increased melee attack speed, and your next Shot ability within 20 sec after killing a target worth experience or honor deals 20% increased damage.\n[q]\"Teaches you a new Engraving ability.\""},
[220345] = {name = "Sanguine Sorcery", additional_info = "Binds when picked up\nUnique\n[q]\"Outlines a variety of powerful blood rituals. A controversial addition to any library's collection.\""},
[220346] = {name = "Legends of the Tidesages", additional_info = "Binds when picked up\nUnique\n[q]\"Covered in illegible notes and diagrams scrawled by an unsteady hand. It could still be a decent addition to any library's collection.\""},
[220347] = {name = "The Liminal and the Arcane", additional_info = "Binds when picked up\nUnique\n[q]\"The words swim on the page, defying attempts to read them. A puzzling addition to any library's collection.\""},
[220348] = {name = "Everyday Etiquette", additional_info = "Binds when picked up\nUnique\n[q]\"A guide to the role of elementary magic in polite Highborne society. A fine addition to any library's collection.\""},
[220349] = {name = "Stonewrought Design", additional_info = "Binds when picked up\nUnique\n[q]\"Sturdy architectural techniques capable of withstanding all but the most cataclysmic disasters. A fine addition to any library's collection.\""},
[220350] = {name = "Venomous Journeys", additional_info = "Binds when picked up\nUnique\n[q]\"Notes on the mind-altering properties of various toxins and venoms. A fine addition to any library's collection.\""},
[220351] = {name = "Murky Air Sapta", additional_info = "Binds when picked up\nUnique\n[q2]Use: Allows the shaman to see elemental spirits."},
[220352] = {name = "A Mind of Metal", additional_info = "Binds when picked up\nUnique\n[q]\"Dwarven techniques for applying magic to metallurgy, strip-mining and heavy industry. An informative, if bleak, addition to any library's collection.\""},
[220353] = {name = "Conjurer's Codex", additional_info = "Binds when picked up\nUnique\n[q]\"A pre-war collection of spells and arcane theories that have largely fallen out of modern use. A fine addition to any library's collection.\""},
[220360] = {name = "[q2]Rune of Efflorescence", additional_info = "Binds when picked up\nUnique\nClasses: Druid\n[q2]Engrave your bracers with the Efflorescence rune:\n\n\nYour Swiftmend now also causes Efflorescence, healing all party members within 15 yards of the Swiftmend target's location for [(38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60) * 16 / 100] every 1 sec for 15 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[220375] = {name = "Fragment of Air", additional_info = "Binds when picked up\nUnique\n[q2]Use: Combine the Fragment of Air with Elemental Essences. May help with finding the corrupted shrine."},
[220446] = {name = "[q2]Otherworldly Treasure", additional_info = "Binds when picked up\n[q2]<Right Click to Open>"},
[220510] = {name = "Elemental Essence", additional_info = "Quest Item\nClasses: Shaman"},
[220525] = {name = "Glowing Fragment of Air", additional_info = "Binds when picked up\nUnique"},
[220606] = {name = "[q3]Idol of the Dream", additional_info = "Binds when picked up\nUnique\n{Relic} {Idol}\nRequires Level 50\n[q2]Equip: Increases the damage of Swipe and Shred by 2%.\nSell Price:"},
[220610] = {name = "[q2]Rune of Mental Dexterity", additional_info = "Binds when picked up\nUnique\nClasses: Shaman\n[q2]Engrave your helm with the Mental Dexterity rune:\n\n\nDealing damage with Stormstrike increases your Attack Power by 150% of your Intellect, and your spell damage by 35% of your total Attack Power for 30 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[220612] = {name = "[q2]Rune of Tidal Waves", additional_info = "Binds when picked up\nUnique\nClasses: Shaman\n[q2]Engrave your helm with the Tidal Waves rune:\n\n\nWhen you cast Chain Heal or Riptide you gain 2 charges of Tidal Waves, which reduces the cast time of your Healing Wave by 30%, reduces the cast time of your Chain Heal by 15%, and increases the critical effect chance of your Lesser Healing Wave by 25%.\n[q]\"Teaches you a new Engraving ability.\""},
[220613] = {name = "[q2]Rune of Rolling Thunder", additional_info = "Binds when picked up\nUnique\nClasses: Shaman\n[q2]Engrave your bracers with the Rolling Thunder rune:\n\n\nLightning Bolt and Chain Lightning have a 50% chance to add an additional charge to your active Lightning Shield, up to a maximum of 9 Charges.\n\n Earth Shock now releases all Lightning Shield charges above 3, dealing their damage to the target, and energizing you for 2% of your maximum mana per charge released.\n[q]\"Teaches you a new Engraving ability.\""},
[220614] = {name = "[q2]Rune of Static Shock", additional_info = "Binds when picked up\nUnique\nClasses: Shaman\n[q2]Engrave your bracers with the Static Shock rune:\n\n\nYour Lightning Shield now has 9 charges, and your melee attacks have a 12% chance (6% chance while dual - wielding) to trigger one of those charges, immediately damaging your target.\n[q]\"Teaches you a new Engraving ability.\""},
[220616] = {name = "[q2]Rune of Overcharged", additional_info = "Binds when picked up\nUnique\nClasses: Shaman\n[q2]Engrave your bracers with the Overcharged rune:\n\n\nYour Lightning Shield never loses charges, now has a 3 sec cooldown, and deals damage to all enemies within 8 yards.\n[q]\"Teaches you a new Engraving ability.\""},
[220617] = {name = "[q2]Rune of Pandemic", additional_info = "Binds when picked up\nUnique\nClasses: Warlock\n[q2]Engrave your helm with the Pandemic rune:\n\n\nPeriodic damage from your Corruption, Unstable Affliction, Curse of Agony, Immolate, Curse of Doom, and Siphon Life abilities can now be critical strikes.\n[q]\"Teaches you a new Engraving ability.\""},
[220618] = {name = "[q2]Rune of Immolation Aura", additional_info = "Binds when picked up\nUnique\nClasses: Warlock\n[q2]Engrave your bracers with the Immolation Aura rune:\n\n\nBurns nearby enemies for [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 20 / 100] damage every time an enemy makes a melee attack against you (no more than once per sec), reduces all magic damage taken by 10%, and increases Fire damage done by 10%. Lasts until cancelled.\n[q]\"Teaches you a new Engraving ability.\""},
[220682] = {name = "[q2]Rune of the Unbridled", additional_info = "Binds when picked up\nUnique\nClasses: Warrior\n[q2]Engrave your bracers with the Rampage rune:\n\n\nGo on a rampage, increasing your attack power by 15% for 30 sec. This ability can only be used while Enraged.\n[q]\"Teaches you a new Engraving ability.\""},
[220687] = {name = "[q2]Rune of the Raptor", additional_info = "Binds when picked up\nClasses: Hunter\n[q2]Engrave your bracers with the Raptor Fury rune:\n\n\nRaptor Strike increases damage done by Raptor Strike and Mongoose Bite by 15% for 30 sec, stacking up to 5 times. Subsequent doses do not extend the duration of this effect.\n[q]\"Teaches you a new Engraving ability.\""},
[220754] = {name = "[q2]Rune of the Windstorm", additional_info = "Binds when picked up\nUnique\nClasses: Druid\n[q2]Engrave your helm with the Gale Winds rune:\n\n\nIncreases the damage done by your Hurricane by 100%, it no longer has a cooldown, and its mana cost is reduced by 60%.\n[q]\"Teaches you a new Engraving ability.\""},
[220775] = {name = "[q2]Engineering Exchange Ticket", additional_info = "Binds when picked up\n[q]\"It just says 'I.O.U' with a smiley face next to it.\""},
[220791] = {name = "[q2]Rune of the Jungle Cat", additional_info = "Binds when picked up\nClasses: Hunter\n[q2]Engrave your helm with the Catlike Reflexes rune:\n\n\nIncreases your chance to dodge by 20% and your pet's chance to dodge by 9%. In addition, reduces the cooldown of your Flanking Strike ability by 50%.\n[q]\"Teaches you a new Engraving ability.\""},
[220792] = {name = "[q2]Scroll of Spatial Mending", additional_info = "[q2]Use: Close a targeted Fel portal. May draw unwanted attention from the other side.\nSell Price:"},
