[225675] = {name = "Sooty Obsidian Core", additional_info = "Binds when picked up\nUnique\n[q2]Use: Polish off the soot."},
[225676] = {name = "Molten Obsidian Core", additional_info = "Binds when picked up\nUnique\nDuration: 10 min (real time)\n[q]\"Cool it down before it melts!\""},
[225686] = {name = "[q2]Rune of Decimation", additional_info = "Binds when picked up\nUnique\nClasses: Warlock\n[q2]Engrave your boots with the Decimation rune:\n\n\nYour Soul Fire spell no longer has a cooldown. Additionally, when your Shadow Bolt, Shadow Cleave, Incinerate, or Soul Fire hits a target that is at or below 35% health, the cast time of your Soul Fire spell is reduced by 40% for 10 sec. Soul Fires cast under the effect of Decimation cost no shard.\n[q]\"Teaches you a new Engraving ability.\""},
[225687] = {name = "[q2]Rune of Infernal Armor", additional_info = "Binds when picked up\nUnique\nClasses: Warlock\n[q2]Engrave your cloak with the Infernal Armor rune:\n\n\nYour spirit becomes infused with demonic energy, reducing all Magic damage you take by a percentage equal to 60% of your Physical damage reduction from armor. Lasts 10 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[225688] = {name = "[q2]Rune of Mark of Chaos", additional_info = "Binds when picked up\nUnique\nClasses: Warlock\n[q2]Engrave your cloak with the Mark of Chaos rune:\n\n\nAll your Curses except Curse of Shadow and Curse of the Elements now apply the Mark of Chaos, reducing the target's Arcane, Fire, Frost, Nature, and Shadow resistances by [Max(Min( 56 + 19, 75), 27)] and increasing all spell damage taken from those schools by [Max(Min(( 56 - 8) * 0.125 + 4, 10), 4)]% while they remain cursed.\n[q]\"Teaches you a new Engraving ability.\""},
[225689] = {name = "[q2]Spell Notes: Arcane Barrage", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Engrave your cloak with the Arcane Barrage rune:\n\n\nLaunches several missiles at the enemy target, causing [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 358 / 100] to [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 438 / 100] Arcane damage. This spell also has a 25% to trigger Missile Barrage.\n[q]\"Teaches you a new Engraving ability.\""},
[225690] = {name = "[q2]Spell Notes: Frozen Orb", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Engrave your cloak with the Frozen Orb\n rune:\n\n\nLaunches an orb of swirling ice which rapidly moves forward over 16 sec. While it is moving, every 1 sec the orb deals [90 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) / 100 * ( 1 ) ] Frost Damage and applies a Chill for 30% movement speed reduction to all enemies it passes through. The first time it damages an enemy, its movement will slow and it will have a 100% chance to trigger the Fingers of Frost rune.\n[q]\"Teaches you a new Engraving ability.\""},
[225691] = {name = "[q2]Spell Notes: Overheat", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Engrave your cloak with the Overheat rune:\n\n\nFire Blast will always deal a critical strike, can be cast while casting another spell, and is not affected by the global cooldown, but its cooldown is increased to 15 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[225740] = {name = "[q2]Rune of Composure", additional_info = "Binds when picked up\nUnique\nClasses: Shaman\n[q2]Engrave your cloak with the Coherence rune:\n\n\nCauses your Chain heal effectiveness to only reduce by 35% per jump, and Chain Lightning effectiveness to only reduce by 20% per jump. Each also jumps to 1 additional target.\n[q]\"Teaches you a new Engraving ability.\""},
[225838] = {name = "[q2]Voltaic Icon", additional_info = "Binds when picked up\nUnique\n{Relic} {Totem}\nClasses: Shaman\n[q2]Engrave your cloak with the Storm, Earth, and Fire rune:\n\n\nReduces the cooldown of your Chain Lightning by 25%, causes your Earthbind Totem to root targets for 5 sec when cast, and increases the periodic damage done by your Flame Shock by 60%.\n[q]\"Learn a new ability after defeating 3 enemies with a single cast of Chain Lightning.\""},
[225914] = {name = "[q2]Rune of the Bound Spirit", additional_info = "Binds when picked up\nUnique\nClasses: Shaman\n[q2]Engrave your cloak with the Feral Spirit rune:\n\n\nSummons two Spirit Wolves under the command of the Shaman, lasting 45 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[225929] = {name = "Plagued Soul Shard", additional_info = "Binds when picked up\nUnique (3)"},
[225938] = {name = "[q2]Torn Spell Notes", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Use: Combine the collected Torn Spell Notes into a scroll that will teach a new Engraving spell.\n[q]\"An incomplete page that appears similar to scrolls that teach Engraving abilities. Three-quarters are missing.\""},
[225939] = {name = "[q2]Torn Spell Notes", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Use: Combine the collected Torn Spell Notes into a scroll that will teach a new Engraving spell.\n[q]\"An incomplete page that appears similar to scrolls that teach Engraving abilities. Three-quarters are missing.\""},
[225940] = {name = "[q2]Torn Spell Notes", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Use: Combine the collected Torn Spell Notes into a scroll that will teach a new Engraving spell.\n[q]\"An incomplete page that appears similar to scrolls that teach Engraving abilities. Three-quarters are missing.\""},
[225941] = {name = "[q2]Torn Spell Notes", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Use: Combine the collected Torn Spell Notes into a scroll that will teach a new Engraving spell.\n[q]\"An incomplete page that appears similar to scrolls that teach Engraving abilities. Three-quarters are missing.\""},
[225942] = {name = "Tainted Boar Meat", additional_info = "Binds when picked up\nUnique\n[q2]Use: Coat in ichor.\n[q]\"Probably just needs some sauce.\""},
[225943] = {name = "Rancid Hunk of Flesh", additional_info = "Binds when picked up\nUnique\n[q2]Use: ???\n[q]\"Would make even the lowliest scavenger retch.\""},
[225954] = {name = "[q2]Charred Spell Notes", additional_info = "Binds when picked up\nClasses: Mage\n[q]\"A charred and torn page that once held arcane secrets for Engraving abilities, now burnt beyond use.\""},
[225955] = {name = "[q2]Rune of the Resourceful", additional_info = "Binds when picked up\nUnique\nClasses: Hunter\n[q2]Engrave your cloak with the Resourcefulness rune:\n\n\nReduces the mana cost of your Traps by 100% and their cooldowns by 40%.\n[q]\"Teaches you a new Engraving ability.\""},
[226201] = {name = "Squire Cuthbert's Blade", additional_info = "Quest Item\nUnique\n[q]\"The sword is dented and chipped, but it feels well-balanced in your hand.\""},
[226207] = {name = "Echo of Anastari", additional_info = "Binds when picked up\nUnique\nDuration: 2 hrs (real time)\n[q2]Use: Offer the echo."},
[226208] = {name = "Echo of Barthilas", additional_info = "Binds when picked up\nUnique\nDuration: 2 hrs (real time)\n[q2]Use: Offer the echo."},
