[226252] = {name = "[q2]Rune of the Guerrilla", additional_info = "Binds when picked up\nUnique\nClasses: Hunter\n[q2]Engrave your cloak with the Hit and Run rune:\n\n\nYou gain 30% movement speed for 15 sec after using Raptor Strike.\n\n Your pet's damaging abilities send the target into a Rabid Frenzy, increasing their melee attack power by 91 but reducing armor by 640 for 2 min. Rabid enemies will not flee and will ignore Fear and Horror effects.\n[q]\"Teaches you a new Engraving ability.\""},
[226374] = {name = "Occult Poison I", additional_info = "Classes: Rogue\nRequires Level 54\n\n[q2]Use: Coats a weapon with poison that lasts for 30 minutes. Each strike has a 30% chance of poisoning the enemy for 108 Nature damage over 12 sec and causing the enemy to take 4% increased Arcane, Fire, Frost, Nature, and Shadow damage. Stacks up to 5 times on a single target.\n\n Occult Poison counts as Deadly Poison and benefits from all talents and effects that trigger from or modify Deadly Poison. (Proc chance: 30%)\nSell Price:"},
[226404] = {name = "[q2]Tarnished Undermine Real", additional_info = "Binds when picked up\nUnique (250)\n[q]\"This Lost Isles currency is slowly being phased out of circulation, but it still enjoys a very favorable exchange rate throughout the Eastern Kingdoms and Kalimdor.\""},
[226405] = {name = "[q2]Damaged Undermine Supply Crate", additional_info = "Binds when picked up\nUnique (10)\n[q]\"This dented and damaged crate looks like it quite literally fell off the back of a zeppelin\"\n[q2]<Right Click to Open>"},
[226406] = {name = "[q2]Rune of Sword Specialization", additional_info = "Binds when picked up\nUnique\nClasses: Warrior , Paladin , Hunter , Rogue , Mage , Warlock\n[q2]Engrave your ring with the Sword Specialization rune:\n\n\nSkill with Swords and Two-Handed Swords increased by 5. This effect is not cumulative with racial bonuses or other ring runes.\n[q]\"Teaches you a new Engraving ability.\""},
[226407] = {name = "[q2]Rune of Axe Specialization", additional_info = "Binds when picked up\nUnique\nClasses: Warrior , Paladin , Hunter , Shaman\n[q2]Engrave your ring with the Axe Specialization rune:\n\n\nSkill with Axes and Two-Handed Axes increased by 5. This effect is not cumulative with racial bonuses or other ring runes.\n[q]\"Teaches you a new Engraving ability.\""},
[226408] = {name = "[q2]Rune of Mace Specialization", additional_info = "Binds when picked up\nUnique\nClasses: Warrior , Paladin , Rogue , Priest , Shaman , Druid\n[q2]Engrave your ring with the Mace Specialization rune:\n\n\nSkill with Maces and Two-Handed Maces increased by 5. This effect is not cumulative with racial bonuses or other ring runes.\n[q]\"Teaches you a new Engraving ability.\""},
[226409] = {name = "[q2]Rune of Dagger Specialization", additional_info = "Binds when picked up\nUnique\nClasses: Warrior , Hunter , Rogue , Priest , Shaman , Mage , Warlock , Druid\n[q2]Engrave your ring with the Dagger Specialization rune:\n\n\nSkill with Daggers increased by 5. This effect is not cumulative with racial bonuses or other ring runes.\n[q]\"Teaches you a new Engraving ability.\""},
[226410] = {name = "[q2]Rune of Ranged Weapon Specialization", additional_info = "Binds when picked up\nUnique\nClasses: Warrior , Hunter , Rogue\n[q2]Engrave your ring with the Ranged Weapon Specialization rune:\n\n\nSkill with Bows, Guns, Crossbows, and Thrown weapons increased by 5. This effect is not cumulative with racial bonuses or other ring runes.\n[q]\"Teaches you a new Engraving ability.\""},
[226411] = {name = "[q2]Rune of Fist Weapon Specialization", additional_info = "Binds when picked up\nUnique\nClasses: Warrior , Hunter , Rogue , Shaman , Druid\n[q2]Engrave your ring with the Fist Weapon Specialization rune:\n\n\nSkill with Fist Weapons (Unarmed) increased by 5. This effect is not cumulative with racial bonuses or other ring runes.\n[q]\"Teaches you a new Engraving ability.\""},
[226412] = {name = "[q2]Rune of Pole Weapon Specialization", additional_info = "Binds when picked up\nUnique\nClasses: Warrior , Paladin , Hunter , Priest , Shaman , Mage , Warlock , Druid\n[q2]Engrave your ring with the Pole Weapon Specialization rune:\n\n\nSkill with Staves and Polearms increased by 5. This effect is not cumulative with racial bonuses or other ring runes.\n[q]\"Teaches you a new Engraving ability.\""},
[226413] = {name = "[q2]Rune of Arcane Specialization", additional_info = "Binds when picked up\nUnique\nClasses: Hunter , Mage , Druid\n[q2]Engrave your ring with the Arcane Specialization rune:\n\n\nChance to hit with Arcane spells increased by 6%. Not cumulative with other ring runes.\n[q]\"Teaches you a new Engraving ability.\""},
[226414] = {name = "[q2]Rune of Fire Specialization", additional_info = "Binds when picked up\nUnique\nClasses: Hunter , Shaman , Mage , Warlock\n[q2]Engrave your ring with the Fire Specialization rune:\n\n\nChance to hit with Fire spells increased by 6%. Not cumulative with other ring runes.\n[q]\"Teaches you a new Engraving ability.\""},
[226415] = {name = "[q2]Rune of Frost Specialization", additional_info = "Binds when picked up\nUnique\nClasses: Hunter , Shaman , Mage\n[q2]Engrave your ring with the Frost Specialization rune:\n\n\nChance to hit with Frost spells increased by 6%. Not cumulative with other ring runes.\n[q]\"Teaches you a new Engraving ability.\""},
[226416] = {name = "[q2]Rune of Nature Specialization", additional_info = "Binds when picked up\nUnique\nClasses: Hunter , Rogue , Shaman , Druid\n[q2]Engrave your ring with the Nature Specialization rune:\n\n\nChance to hit with Nature spells increased by 6%. Not cumulative with other ring runes.\n[q]\"Teaches you a new Engraving ability.\""},
[226417] = {name = "[q2]Rune of Shadow Specialization", additional_info = "Binds when picked up\nUnique\nClasses: Priest , Warlock\n[q2]Engrave your ring with the Shadow Specialization rune:\n\n\nChance to hit with Shadow spells increased by 6%. Not cumulative with other ring runes.\n[q]\"Teaches you a new Engraving ability.\""},
[226418] = {name = "[q2]Rune of Holy Specialization", additional_info = "Binds when picked up\nUnique\nClasses: Paladin , Priest\n[q2]Engrave your ring with the Holy Specialization rune:\n\n\nChance to hit with Holy spells increased by 6%. Not cumulative with other ring runes.\n[q]\"Teaches you a new Engraving ability.\""},
[226419] = {name = "[q2]Rune of Feral Combat Specialization", additional_info = "Binds when picked up\nUnique\nClasses: Druid\n[q2]Engrave your ring with the Feral Combat Specialization rune:\n\n\nFeral Combat skill increased by 5. Not cumulative with other ring runes.\n[q]\"Teaches you a new Engraving ability.\""},
[226420] = {name = "[q0]Finely Crafted Bust", additional_info = "Binds when picked up\n[q]\"A finely crafted work of art. This item would not look out of place in a private collection or museum.\"\nSell Price:"},
[226472] = {name = "Stratholme Shadow Jar", additional_info = "Binds when picked up\nUnique\n[q2]Use: Capture the echo of a powerful denizen of Stratholme. Only usable on corpses."},
[226526] = {name = "Busted Gizmo", additional_info = "Binds when picked up\nUnique\n[q]\"Might be salvagable...?\""},
[226546] = {name = "Desert Sonar", additional_info = "Binds when picked up\nUnique\nTrinket\n[q2]Equip: Detect large objects beneath the sand.\n\n[q2]Use: Emit a high-pitched sonar frequency. (30 Sec Cooldown)\nSell Price:"},
[226587] = {name = "[q2]Rune of Shelling", additional_info = "Binds when picked up\nUnique\nClasses: Hunter\n[q2]Engrave your cloak with the Improved Volley rune:\n\n\nReduces the mana cost of your Volley by 50%, reduces its cooldown by 100%, increases its damage by 100%, and it no longer suffers pushback from damaging attacks. Volley also deals 3% of your ranged Attack Power as additional damage each time it deals damage.\n[q]\"Teaches you a new Engraving ability.\""},
[226678] = {name = "[q4]Premonition and Combat Foresight", additional_info = "Binds when picked up\nUnique\nClasses: Warrior\n[q2]Engrave your cloak with the Shockwave\n rune:\n\n\nSends a wave of force in front of the warrior, causing (50 / 100 * Attack Power) damage and stunning all enemy targets within 10 yards in a frontal cone for 4 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[226679] = {name = "[q3]Timeless Wanderer's Insights", additional_info = "Binds when picked up\nUnique\nClasses: Warrior\n[q2]Engrave your cloak with the Sudden Death rune:\n\n\nYour melee hits have a 10% chance to grant Sudden Death. Sudden Death allows one use of Execute regardless of the target's health state. When Execute is enabled by Sudden Death, you will retain 10 rage after using Execute.\n[q]\"Teaches you a new Engraving ability.\""},
[226680] = {name = "[q3]Rune of the First Warrior", additional_info = "Binds when picked up\nUnique\nClasses: Warrior\n[q2]Engrave your cloak with the Fresh Meat\n rune:\n\n\nDamaging a target with Bloodthirst, Mortal Strike, or Shield Slam has a 100% chance the first time and a 10% chance each subsequent time to Enrage you (activating abilities which requiring being Enraged), and cause you to deal 10% increased Physical damage for 12 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[226694] = {name = "[q2]Rune of Defense Specialization", additional_info = "Binds to account\nUnique\nClasses: Warrior , Paladin , Rogue , Shaman , Warlock , Druid\n[q2]Engrave your ring with the Defense Specialization rune:\n\n\nDefense skill increased by 25. Not cumulative with other ring runes.\n[q]\"Teaches you a new Engraving ability.\""},
[226698] = {name = "Vertically Composited Patch Hampler", additional_info = "Quest Item"},
[226699] = {name = "Brass-fitted Flam-Tamp Flange", additional_info = "Quest Item\n[q]\"Includes bracket caps and half-seized sprats\""},
[226772] = {name = "[q3]Feralheart Sash", additional_info = "Binds when picked up\n{Waist} {Leather}\n102 Armor\n+8 Stamina\n+8 Intellect\nDurability 35 / 35\nClasses: Druid\n[q2]Equip: Improves your chance to get a critical strike with all spells and attacks by 1%.\n\n[q2]Equip: Increases damage and healing done by magical spells and effects by up to 18.\n\n[q]Feralheart Raiment (0/8)\n[q0]Feralheart Boots\nFeralheart Chest\nFeralheart Gloves\nFeralheart Helm\nFeralheart Legs\nFeralheart Shoulders\nFeralheart Waist\nFeralheart Wrists\n[q0](2) Set : +40 Attack Power, up to 23 increased damage from spells, and up to 44 increased healing from spells.\n(4) Set : 2% chance on spellcast to energize you for 300 mana, 6% chance on dealing a melee autoattack to energize you for 40 Energy, and 3% chance on being hit by a melee attack to energize you for 10 Rage. (Proc chance: 6%)\n(6) Set : +8 All Resistances.\n(8) Set : +200 Armor.\nSell Price:"},
[226773] = {name = "[q4]Feralheart Cowl", additional_info = "Binds when picked up\n{Head} {Leather}\n150 Armor\n+16 Stamina\n+20 Intellect\nDurability 70 / 70\nClasses: Druid\n[q2]Equip: Improves your chance to hit with all spells and attacks by 1%.\n\n[q2]Equip: Increases damage and healing done by magical spells and effects by up to 33.\n\n[q]Feralheart Raiment (0/8)\n[q0]Feralheart Boots\nFeralheart Chest\nFeralheart Gloves\nFeralheart Helm\nFeralheart Legs\nFeralheart Shoulders\nFeralheart Waist\nFeralheart Wrists\n[q0](2) Set : +40 Attack Power, up to 23 increased damage from spells, and up to 44 increased healing from spells.\n(4) Set : 2% chance on spellcast to energize you for 300 mana, 6% chance on dealing a melee autoattack to energize you for 40 Energy, and 3% chance on being hit by a melee attack to energize you for 10 Rage. (Proc chance: 6%)\n(6) Set : +8 All Resistances.\n(8) Set : +200 Armor.\nSell Price:"},
