[226775] = {name = "[q3]Feralheart Wraps", additional_info = "Binds when picked up\n{Wrist} {Leather}\n79 Armor\n+7 Stamina\n+10 Intellect\nDurability 35 / 35\nClasses: Druid\n[q2]Equip: Improves your chance to hit with all spells and attacks by 1%.\n\n[q2]Equip: Increases damage and healing done by magical spells and effects by up to 13.\n\n[q]Feralheart Raiment (0/8)\n[q0]Feralheart Boots\nFeralheart Chest\nFeralheart Gloves\nFeralheart Helm\nFeralheart Legs\nFeralheart Shoulders\nFeralheart Waist\nFeralheart Wrists\n[q0](2) Set : +40 Attack Power, up to 23 increased damage from spells, and up to 44 increased healing from spells.\n(4) Set : 2% chance on spellcast to energize you for 300 mana, 6% chance on dealing a melee autoattack to energize you for 40 Energy, and 3% chance on being hit by a melee attack to energize you for 10 Rage. (Proc chance: 6%)\n(6) Set : +8 All Resistances.\n(8) Set : +200 Armor.\nSell Price:"},
[226776] = {name = "[q4]Feralheart Vest", additional_info = "Binds when picked up\n{Chest} {Leather}\n185 Armor\n+15 Stamina\n+20 Intellect\nDurability 120 / 120\nClasses: Druid\n[q2]Equip: Improves your chance to hit with all spells and attacks by 1%.\n\n[q2]Equip: Increases damage and healing done by magical spells and effects by up to 32.\n\n[q]Feralheart Raiment (0/8)\n[q0]Feralheart Boots\nFeralheart Chest\nFeralheart Gloves\nFeralheart Helm\nFeralheart Legs\nFeralheart Shoulders\nFeralheart Waist\nFeralheart Wrists\n[q0](2) Set : +40 Attack Power, up to 23 increased damage from spells, and up to 44 increased healing from spells.\n(4) Set : 2% chance on spellcast to energize you for 300 mana, 6% chance on dealing a melee autoattack to energize you for 40 Energy, and 3% chance on being hit by a melee attack to energize you for 10 Rage. (Proc chance: 6%)\n(6) Set : +8 All Resistances.\n(8) Set : +200 Armor.\nSell Price:"},
