[227444] = {name = "[q2]Idol of the Huntress", additional_info = "Binds when picked up\nUnique\n{Relic} {Idol}\nClasses: Druid\n[q2]Engrave your cloak with the Improved Swipe rune:\n\n\nWhile in Cat Form, your Swipe ability becomes Swipe (Cat), and while in Bear Form, your Swipe ability strikes up to 7 additional enemies.\n\n Swipe (Cat)\n\nSwipe nearby enemies, inflicting 250% weapon damage and generating 1 combo point on your current target.\n[q]\"Kill 5 sleeping targets while in Cat Form. Then, use this idol to learn a new ability.\""},
[227451] = {name = "Sending Sigil", additional_info = "Binds when picked up\nUnique\n[q]\"The symbols ' > v ^ < ' are engraved along the border.\""},
[227456] = {name = "[q2]Rune of the Crimson Tempest", additional_info = "Binds when picked up\nUnique\nClasses: Rogue\n[q2]Engrave your cloak with the Crimson Tempest rune:\n\n\nFinishing move that slashes all enemies within 8 yards, causing victims to Bleed over time. Lasts longer and deals more damage per combo point.\n\n 1 point : (Attack Power * 0.30) damage over 4 sec.\n 2 points: (Attack Power * 0.45) damage over 6 sec.\n 3 points: (Attack Power * 0.60) damage over 8 sec.\n 4 points: (Attack Power * 0.75) damage over 10 sec.\n 5 points: (Attack Power * 0.90) damage over 12 sec.\n\n Crimson Tempest benefits from all talents and effects that trigger from or modify Rupture.\n[q]\"Teaches you a new Engraving ability.\""},
[227549] = {name = "Scrap of Parchment", additional_info = "Binds when picked up\nClasses: Rogue\n[q2]<Right Click to Read>"},
[227552] = {name = "[q0]Shredded Parchment", additional_info = "Binds when picked up\nUnique\n[q]\"Seems to have been damaged in combat.\""},
[227658] = {name = "[q2]Shadowsworn Note", additional_info = "Binds when picked up\nClasses: Warlock\n[q2]<Right Click to Read>"},
[227685] = {name = "Modified Shadow Scalpel", additional_info = "Quest Item\n[q2]Use: Focus the Modified Shadow Scalpel on Arkonos the Cursed to dispel his barrier of protection.\n[q]\"Cuthbert has imparted Dalton's final blessing upon this instrument. Hopefully it should function to undo the barrier protecting Arkonos.\""},
[227686] = {name = "Ornate Warhammer", additional_info = "Quest Item\nUnique"},
[227687] = {name = "[q2]Orthas' Favorite Gold Tooth", additional_info = "Binds when picked up\n[q2]Use: Give Orthas' tooth a... rub. Gross. (2 Min Cooldown)\n[q]\"It smells awful.\"\nSell Price:"},
[227689] = {name = "Partially-Digested Plate Armor", additional_info = "Quest Item\nUnique"},
[227690] = {name = "Necrotic Runestone", additional_info = "Quest Item\n[q]\"You feel sick to your stomach when your bare flesh makes contact with this runestone.\""},
[227727] = {name = "[q4]Plans: Sulfuron Hammer", additional_info = "Unique\nRequires Blacksmithing (300)\n\n[q2]Use: Teaches you how to make a Sulfuron Hammer.\nSell Price:\n[q4]Sulfuron Hammer\nBinds when equipped\n{Two-Hand} {Mace}\n{181 - 303 Damage} {Speed 3.80}\n(63.68 damage per second)\n+10 Strength\n+10 Stamina\n+30 Fire Resistance\nDurability 120 / 120\nRequires Level 60\n[q2]Chance on hit: Hurls a fiery ball that causes 83 to 101 Fire damage and an additional 16 damage over 8 sec.\n\n[q2]Equip: Deals 5 Fire damage to anyone who strikes you with a melee attack.\n\n[q2]Equip: +124 Attack Power in Cat, Bear, and Dire Bear forms only.\nSell Price: \nRequires Sulfuron Ingot (8), Dark Iron Bar (20), Arcanite Bar (50), Essence of Fire (25), Blood of the Mountain (10), Lava Core (10), Fiery Core (10)"},
[227730] = {name = "[q4]Thorium Brotherhood Contract", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 60\n[q]\"Bound in Dark Iron Wiring\""},
[227743] = {name = "Obsidian Power Core", additional_info = "Quest Item"},
[227745] = {name = "Family Heirloom", additional_info = "Binds when picked up\nUnique"},
[227746] = {name = "[q2]Rune of the World Tree", additional_info = "Binds when picked up\nUnique\nClasses: Druid\n[q2]Engrave your cloak with the Tree of Life rune:\n\n\nShapeshift into the Tree of Life. While in this form you increase healing received by 10% for all party members within 45 yards, Wild Growth healing is increased by 60%, your heal over time spells cost 20% less, you gain 25% increased Spirit, you gain 200% increased armor, and you cannot cast harmful spells.\n\n The act of shapeshifting frees the caster of Polymorph and Movement Impairing effects.\n[q]\"Teaches you a new Engraving ability.\""},
[227747] = {name = "Family Records", additional_info = "Binds when picked up\nUnique"},
[227748] = {name = "Survivor Journal", additional_info = "Quest Item\nUnique\n[q2]<Right Click to Read>"},
[227749] = {name = "[q2]Rune of the Falling Star", additional_info = "Binds when picked up\nUnique\nClasses: Druid\n[q2]Engrave your cloak with the Starfall\n rune:\n\n\nYou summon a flurry of stars from the sky over 10 sec, striking targets within 30 yards of your location, each dealing [46 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] to [54 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] Arcane damage to its target and [8 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] Arcane damage to all other enemies within 5 yards. Maximum 20 stars.\n\n Shapeshifting or mounting cancels the effect. Any effect which causes you to lose control of your character will suppress the Starfall effect.\n\n Benefits from and triggers most talents and effects that trigger or benefit from Moonfire.\n[q]\"Teaches you a new Engraving ability.\""},
[227767] = {name = "Flamestone Cluster", additional_info = "Quest Item"},
[227768] = {name = "Dreamjuice", additional_info = "Quest Item\nUnique\n[q2]Use: Drink the Dreamjuice to enter a state of waking sleep, allowing you to see hidden enemies. Only usable in Thorium Point. (30 Sec Cooldown)\n3 Charges"},
[227796] = {name = "Mysterious Darnassian Scroll", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Use: Decipher the scroll with a Comprehension Charm. Who knows what magic it contains?"},
[227797] = {name = "Deciphered Darnassian Scroll", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q]\"Weak magic emanates from the scroll. It may have enough to revitalize the one who wrote it.\""},
