[228114] = {name = "[q3]Plans: Refined Arcanite Reaper", additional_info = "Requires Blacksmithing (300)\nRequiresMaster Axesmith\n\n[q2]Use: Teaches you how to make an Arcanite Reaper.\nSell Price:\n[q4]Refined Arcanite Reaper\nBinds when equipped\n{Two-Hand} {Axe}\n{215 - 322 Damage} {Speed 4.00}\n(67.13 damage per second)\n+18 Stamina\nDurability 120 / 120\nRequires Level 60\n[q2]Equip: +84 Attack Power.\nSell Price: \nRequires Arcanite Reaper , Elemental Sharpening Stone (10)"},
[228117] = {name = "[q3]Plans: Refined Arcanite Champion", additional_info = "Requires Blacksmithing (300)\nRequiresMaster Swordsmith\n\n[q2]Use: Teaches you how to make an Arcanite Champion.\nSell Price:\n[q4]Refined Arcanite Champion\nBinds when equipped\n{Two-Hand} {Sword}\n{107 - 161 Damage} {Speed 2.00}\n(67.00 damage per second)\nDurability 100 / 100\nRequires Level 60\n[q2]Chance on hit: Heal self for 270 to 450 and Increases Strength by 120 for 30 sec.\n\n[q2]Chance on hit: Increases damage done by 20 and attack speed by 5% for 15 sec.\nSell Price: \nRequires Arcanite Champion , Elemental Sharpening Stone (10)"},
