[228123] = {name = "[q2]Jubilant Epiphany", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Engrave your cloak with the Binding Heal rune:\n\n\nHeals a friendly target and the caster for [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 161 / 100] to [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 197 / 100]. Low threat. This spell benefits from and triggers all effects associated with Flash Heal.\n[q]\"Teaches you a new Engraving ability.\""},
[228124] = {name = "[q2]Oneiric Epiphany", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Engrave your cloak with the Soul Warding rune:\n\n\nYour Power Word: Shield no longer has a cooldown, costs 15% less mana, gains 10% additional base value, and gains an additional 10% of your healing power.\n[q]\"Teaches you a new Engraving ability.\""},
[228126] = {name = "[q2]Aperitive Epiphany", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Engrave your cloak with the Vampiric Touch rune:\n\n\nApplies your Vampiric Embrace talent to your target, causes [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 65 / 100 * 5] Shadow damage over 15 sec to your target, and causes all party members to gain mana equal to 2% of any Shadow spell damage you deal to the target.\n[q]\"Teaches you a new Engraving ability.\""},
[228130] = {name = "[q2]Altruist Ward", additional_info = "Binds when picked up\nUnique\n[q2]Use: Summons a ward that lasts 30 sec. and periodically heals Horde members in an area around it. (10 Min Cooldown)"},
