[228301] = {name = "[q3]Pattern: Swift Flight Vambraces", additional_info = "Binds when picked up\nRequires Leatherworking (300)\n\n[q2]Use: Teaches you how to craft Swift Flight Bracers.\nSell Price: \n[q3]Swift Flight Vambraces\nBinds when equipped\n{Wrist} {Mail}\n160 Armor\n+7 Agility\nDurability 40 / 40\nRequires Level 57\n[q2]Equip: +41 ranged Attack Power.\nSell Price: \nRequires Rugged Leather (12), Larval Acid (8), Ironfeather (60), Cured Rugged Hide (4), Rune Thread (4)"},
[228303] = {name = "Pattern: Incandescent Mooncloth Robe", additional_info = "Requires Tailoring (300)\n\n[q2]Use: Teaches you how to sew a Mooncloth Robe.\nSell Price:\n[q3]Incandescent Mooncloth Robe\nBinds when equipped\n{Chest} {Cloth}\n89 Armor\n+12 Intellect\n+10 Spirit\nDurability 80 / 80\nRequires Level 58\n[q2]Equip: Increases healing done by spells and effects by up to 62.\nSell Price: \nRequires Bolt of Runecloth (6), Mooncloth (4), Golden Pearl (2), Rune Thread (2)"},
[228309] = {name = "Pattern: Living Green Dragonscale Breastplate", additional_info = "Requires Leatherworking (260)\nRequires Dragonscale Leatherworking\n\n[q2]Use: Teaches you how to craft a Green Dragonscale Breastplate.\nSell Price:\n[q3]Living Green Dragonscale Breastplate\nBinds when equipped\n{Chest} {Mail}\n311 Armor\n+10 Stamina\n+14 Spirit\n+11 Nature Resistance\nDurability 120 / 120\nRequires Level 47\n[q2]Equip: Increases healing done by spells and effects by up to 31.\n\n[q]Green Dragon Mail (0/3)\n[q0]Living Green Dragonscale Breastplate\nLiving Green Dragonscale Gauntlets\nLiving Green Dragonscale Leggings\nSell Price: \nRequires Rugged Leather (20), Green Dragonscale (25), Rune Thread (2)"},
[228310] = {name = "[q3]Plans: Hardened Frostguard", additional_info = "Requires Blacksmithing (300)\nRequiresMaster Swordsmith\n\n[q2]Use: Teaches you how to make a Frostguard.\nSell Price:\n[q4]Hardened Frostguard\nBinds when equipped\n{Main Hand} {Sword}\n{54 - 101 Damage} {Speed 1.50}\n(51.67 damage per second)\n+4 Stamina\nDurability 90 / 90\nRequires Level 60\n[q2]Chance on hit: Target's movement slowed by 30% and increasing the time between attacks by 25% for 5 sec.\n\n[q2]Chance on hit: Inflicts Frost damage to nearby enemies, immobilizing them for up to 8 sec.\nSell Price: \nRequires Frostguard , Elemental Sharpening Stone (10)"},
[228311] = {name = "[q2]Plans: Finely-Enchanted Battlehammer", additional_info = "Requires Blacksmithing (280)\nRequiresMaster Hammersmith\n\n[q2]Use: Teaches you how to make an Enchanted Battlehammer.\nSell Price:\n[q3]Finely-Enchanted Battlehammer\nBinds when equipped\n{Two-Hand} {Mace}\n{106 - 160 Damage} {Speed 2.60}\n(51.15 damage per second)\nDurability 100 / 100\nRequires Level 55\n[q2]Equip: Increased Defense +13.\n\n[q2]Equip: Improves your chance to hit with all spells and attacks by 2%.\n\n[q2]Equip: +109 Attack Power in Cat, Bear, and Dire Bear forms only.\nSell Price: \nRequires Thorium Bar (20), Enchanted Thorium Bar (6), Huge Emerald (2), Powerful Mojo (4), Rugged Leather (4)"},
[228312] = {name = "[q4]Plans: Invincible Mail", additional_info = "Requires Blacksmithing (300)\nRequiresArmorsmith\n\n[q2]Use: Teaches you how to make Invincible Mail.\nSell Price:\n[q4]Invincible Mail\nBinds when equipped\n{Chest} {Mail}\n416 Armor\n+20 Stamina\nDurability 140 / 140\nRequires Level 60\n[q2]Equip: When struck in combat has a 5% chance to make you invulnerable to melee damage for 3 sec. This effect can only occur once every 30 sec. (Proc chance: 5%, 30s cooldown)\n\n[q2]Equip: Increased Defense +13.\nSell Price: \nRequires Arcanite Bar (30), Enchanted Thorium Bar (30), Huge Emerald (6), Azerothian Diamond (6)"},
[228313] = {name = "[q3]Plans: Tempest Gauntlets", additional_info = "Requires Blacksmithing (295)\nRequiresArmorsmith\n\n[q2]Use: Teaches you how to make Tempest Gauntlets.\nSell Price:\n[q3]Tempest Gauntlets\nBinds when equipped\n{Hands} {Mail}\n218 Armor\n+7 Intellect\n+10 Fire Resistance\nDurability 40 / 40\nRequires Level 54\n[q2]Equip: Adds 3 Lightning damage to your melee attacks.\n\n[q2]Equip: Increases damage and healing done by magical spells and effects by up to 18.\nSell Price: \nRequires Thorium Bar (20), Enchanted Thorium Bar (4), Essence of Water (4), Blue Sapphire (4)"},
[228314] = {name = "[q3]Plans: Warcrest of the Great Chief", additional_info = "Requires Blacksmithing (300)\nRequiresArmorsmith\n\n[q2]Use: Teaches you how to make a Warcrest of the Great Chief.\nSell Price: \n[q3]Warcrest of the Great Chief\nBinds when equipped\n{Head} {Mail}\n292 Armor\n+12 Stamina\n+18 Spirit\nDurability 70 / 70\nRequires Level 56\n[q2]Equip: Increases healing done by spells and effects by up to 46.\nSell Price: \nRequires Thorium Bar (40), Enchanted Thorium Bar (4), Jet Black Feather (60), Large Opal (6), Huge Emerald (2)"},
[228315] = {name = "[q4]Plans: Sageblade of the Archmagus", additional_info = "Requires Blacksmithing (300)\nRequiresMaster Swordsmith\n\n[q2]Use: Teaches you how to make a Sageblade of the Archmagus.\nSell Price:\n[q4]Sageblade of the Archmagus\nBinds when equipped\n{Main Hand} {Sword}\n{47 - 103 Damage} {Speed 1.80}\n(41.67 damage per second)\n+14 Stamina\n+10 Intellect\nDurability 105 / 105\nRequires Level 60\n[q2]Equip: Increases damage and healing done by magical spells and effects by up to 41.\n\n[q2]Equip: Decreases the magical resistances of your spell targets by 10.\nSell Price: \nRequires Arcanite Bar (12), Nexus Crystal (2), Flask of Supreme Power (2), Enchanted Leather (4)"},
[228316] = {name = "[q3]Pattern: Incandescent Mooncloth Vest", additional_info = "Requires Tailoring (300)\n\n[q2]Use: Teaches you how to sew a Mooncloth Vest.\nSell Price:\n[q3]Incandescent Mooncloth Vest\nBinds when equipped\n{Chest} {Cloth}\n89 Armor\n+12 Intellect\n+10 Spirit\nDurability 80 / 80\nRequires Level 58\n[q2]Equip: Increases damage and healing done by magical spells and effects by up to 33.\nSell Price: \nRequires Bolt of Runecloth (6), Mooncloth (4), Rune Thread"},
[228317] = {name = "[q3]Pattern: Incandescent Mooncloth Circlet", additional_info = "Requires Tailoring (300)\n\n[q2]Use: Teaches you how to sew a Mooncloth Circlet.\nSell Price: \n[q3]Incandescent Mooncloth Circlet\nBinds when equipped\n{Head} {Cloth}\n71 Armor\n+18 Intellect\n+15 Spirit\nDurability 50 / 50\nRequires Level 57\n[q2]Equip: Increases healing done by spells and effects by up to 48.\nSell Price: \nRequires Bolt of Runecloth (4), Mooncloth (6), Azerothian Diamond , Enchanted Leather (2), Rune Thread (2)"},
[228318] = {name = "[q3]Pattern: Incandescent Mooncloth Leggings", additional_info = "Requires Tailoring (290)\n\n[q2]Use: Teaches you how to sew Mooncloth Leggings.\nSell Price:\n[q3]Incandescent Mooncloth Leggings\nBinds when equipped\n{Legs} {Cloth}\n72 Armor\n+14 Intellect\n+16 Spirit\nDurability 65 / 65\nRequires Level 53\n[q2]Equip: Increases healing done by spells and effects by up to 46.\nSell Price: \nRequires Bolt of Runecloth (6), Mooncloth (4), Rune Thread"},
[228319] = {name = "[q3]Pattern: Girdle of Arcane Insight", additional_info = "Binds when picked up\nRequires Leatherworking (300)\n\n[q2]Use: Teaches you how to craft a Girdle of Insight.\nSell Price: \n[q4]Girdle of Arcane Insight\nBinds when equipped\n{Waist} {Leather}\n107 Armor\n+12 Stamina\n+16 Intellect\nDurability 40 / 40\nRequires Level 57\n[q2]Equip: Improves your chance to hit with all spells and attacks by 1%.\n\n[q2]Equip: Increases damage and healing done by magical spells and effects by up to 22.\nSell Price: \nRequires Rugged Leather (12), Powerful Mojo (12), Cured Rugged Hide (2), Rune Thread (4)"},
[228324] = {name = "[q4]Gold Slaughter Coin", additional_info = "Binds when picked up\n[q]\"An icon of your great service to the Blood Loa.\""},
