[228659] = {name = "[q4]Ancient Rune Etched Stave", additional_info = "Binds when picked up\nUnique\nRequires Level 60\n\n[q2]Use: Forms Rhok'delar, Longbow of the Ancient Keepers, when combined with Enchanted Black Dragon Sinew.\n[q]\"A Gift from the Ancients.\""},
[228695] = {name = "[q4]A Dull and Flat Elven Blade", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest"},
[228696] = {name = "[q4]Heated Ancient Blade", additional_info = "Quest Item\nUnique\nDuration: 20 min\n[q2]Use: Drive into the heart of the brood mother to temper the heated blade."},
[228697] = {name = "[q4]Treated Ancient Blade", additional_info = "Quest Item\nUnique\n[q]\"Tempered in the blood of Onyxia.\""},
[228749] = {name = "[q4]Splinter of Nordrassil", additional_info = "Binds when picked up\nUnique\nRequires Level 60\n\n[q2]Use: Forms Benediction when combined with the Eye of Shadow and the Eye of Divinity.\n[q]\"A tiny fragment of the World Tree\""},
