[228978] = {name = "[q3]Enchanted Sigil: Flowing Waters", additional_info = "Binds when picked up\nRequires Level 60\nRequires Enchanting (290)\n\n[q2]Use: Gain an enchanted sigil of Flowing Waters, empowering your raid to deal up to 30 increased damage and healing with spells, and increasing attack power by 30 for 1 hour. (1 Min Cooldown)"},
[228979] = {name = "[q3]Enchanted Sigil: Flowing Waters", additional_info = "Binds when picked up\nRequires Enchanting (290)\nRequiresHydraxian Waterlords\n- Revered\n\n[q2]Use: Teaches you how to conjure a Sigil of Flowing Waters.\nSell Price: \n[q3]Enchanted Sigil: Flowing Waters\nBinds when picked up\nRequires Level 60\nRequires Enchanting (290)\n\n[q2]Use: Gain an enchanted sigil of Flowing Waters, empowering your raid to deal up to 30 increased damage and healing with spells, and increasing attack power by 30 for 1 hour. (1 Min Cooldown)\nRequires Illusion Dust"},
[228980] = {name = "Conductive Shield Coating", additional_info = "Requires Level 40\n\n[q2]Use: While applied to target shield it increases spell damage and healing by up to 24. Lasts for 30 minutes.\n5 Charges\nSell Price:"},
[228981] = {name = "Formula: Conductive Shield Coating", additional_info = "Binds when picked up\nRequires Enchanting (275)\n\n[q2]Use: Teaches you how to create Conductive Shield Coating.\nSell Price:\nConductive Shield Coating\nRequires Level 40\n\n[q2]Use: While applied to target shield it increases spell damage and healing by up to 24. Lasts for 30 minutes.\n5 Charges\nSell Price:\nRequires Illusion Dust (2), Firebloom , Crystal Vial"},
