[228993] = {name = "[q3]Pattern: Bottomless Bag", additional_info = "Requires Tailoring (300)\n\n[q2]Use: Teaches you how to sew a Bottomless Bag.\nSell Price: \n[q3]Bottomless Bag\nBinds when equipped\n20 Slot Bag\nSell Price:\nRequires Bolt of Runecloth (8), Mooncloth (12), Large Brilliant Shard (2), Core Leather (2), Rune Thread (2)"},
