[231732] = {name = "[q2]Suspicious Supplies", additional_info = "Quest Item\nClasses: Warlock\n[q2]Use: Place and open the strange supplies Xirath gave you.\n[q]\"Strange energy emanates from the bag. Best to not look.\""},
[231778] = {name = "Mountain Spring Water", additional_info = "Conjured Item\nRequires Level 55\n\n[q2]Use: Restores 5100 mana over 30 sec. Must remain seated while drinking."},
