[231828] = {name = "[q2]Rune of Meditation Specialization", additional_info = "Binds to account\nUnique\nClasses: Paladin , Hunter , Priest , Shaman , Mage , Warlock , Druid\n[q2]Engrave your ring with the Meditation Specialization rune:\n\n\nRestores 5 mana per 5 sec. This effect is not cumulative with other ring runes.\n[q]\"Teaches you a new Engraving ability.\""},
[231829] = {name = "[q2]Rune of Healing Specialization", additional_info = "Binds to account\nUnique\nClasses: Paladin , Priest , Shaman , Mage , Druid\n[q2]Engrave your ring with the Healing Specialization rune:\n\n\nIncreases healing done by spells and effects by up to 26. This effect is not cumulative with other ring runes.\n[q]\"Teaches you a new Engraving ability.\""},
[231836] = {name = "[q2]Glowing Scroll of Spatial Mending", additional_info = "Quest Item\n[q2]Use: Close a targeted Fel portal. May draw unwanted attention from the other side."},
[231837] = {name = "[q2]Shadow Carving", additional_info = "Quest Item\nUnique\n[q]\"It appears to attract shadow energy.\""},
[231841] = {name = "[q4]Blood of the Lightbringer", additional_info = "Binds when picked up\nUnique\nClasses: Paladin\nRequires Level 60\n[q]\"This small reliquary is filled with a small sample of blood. There is a partially torn parchment label on the underside that bears a single word: \"Uther\".\""},
[231843] = {name = "First Sigil Fragment", additional_info = "Binds when picked up\nUnique\n[q2]Use: Combine with two other pieces to form the Sigil of the Keeper."},
[231844] = {name = "Second Sigil Fragment", additional_info = "Binds when picked up\nUnique\n[q2]Use: Combine with two other pieces to form the Sigil of the Keeper."},
[231845] = {name = "Third Sigil Fragment", additional_info = "Binds when picked up\nUnique\n[q2]Use: Combine with two other pieces to form the Sigil of the Keeper."},
[231877] = {name = "[q3]Tyler's Balanced Bobble", additional_info = "Binds when picked up\nTrinket\nSell Price:"},
[231901] = {name = "[q4]Truthbearer", additional_info = "Quest Item\nUnique\nClasses: Paladin\nRequires Level 60"},
[231903] = {name = "Scrap of Torn Cloth", additional_info = "Binds when picked up\nUnique\nClasses: Paladin\nRequires Level 60\n[q]\"A small scrap of cloth from Uther the Lightbringer's tunic containing a few flecks of blood.\""},
[231904] = {name = "Tarnished Horn", additional_info = "Quest Item\nUnique\nRequires Level 50\n\n[q2]Use: Sound the horn to call Aeonas back to you should you get separated. This will also cancel any magical disguises you have active. (15 Sec Cooldown)"},
[231909] = {name = "[q4]Crystallized Starlight", additional_info = "Binds when picked up\nUnique\nClasses: Druid\n[q2]Use: Attune with the heavens, allowing you to replace your Moonkin form with a more celestial visage."},
[232312] = {name = "[q4]Blood of the Lightbringer", additional_info = "Binds when picked up\nUnique\nClasses: Paladin\nRequires Level 60\n\n[q2]Use: Apply the Blood of the Lightbringer to consecrate your weapon."},
[232324] = {name = "[q3]Bird Whistle", additional_info = "Binds when picked up\n[q2]Use: Calls forth Pepe to ride on your head as you adventure together.\nSell Price:"},
[232343] = {name = "QAEnchant Shield - Law of Nature", additional_info = "[q2]Use: Permanently enchant a shield to give +2% chance to block."},
[232344] = {name = "[q4]Vick's VIP Pass", additional_info = "Unique\n[q2]Use: Attune yourself to Blackwing Lair! (30 Sec Cooldown)\n[q]\"For close personal friends of Lord Victor Nefarius only!\"\nSell Price:"},
[232358] = {name = "[q4]Empty Reliquary", additional_info = "Binds when picked up\nUnique\nClasses: Paladin\nRequires Level 60"},
[232414] = {name = "[q4]Dragontooth Blade", additional_info = "Quest Item\nUnique\nClasses: Warrior\nRequires Level 60\n\n[q2]Use: Carve a scale from Nefarian's hide. Only usable when Nefarian has been significantly weakened in battle. (10 Sec Cooldown)"},
[232433] = {name = "Dense Runecloth Bandage", additional_info = "Requires Level 50\nRequires First Aid (300)\n\n[q2]Use: Heals 3400 damage over 8 sec.\nSell Price:"},
[232434] = {name = "Manual: Dense Runecloth Bandage", additional_info = "Requires First Aid (300)\n\n[q2]Use: Teaches you how to make a Dense Runecloth Bandage.\nSell Price: \nDense Runecloth Bandage\nRequires Level 50\nRequires First Aid (300)\n\n[q2]Use: Heals 3400 damage over 8 sec.\nSell Price:\nRequires Heavy Runecloth Bandage (2)"},
[232436] = {name = "Darkclaw Bisque", additional_info = "Requires Level 45\n\n[q2]Use: Restores 2148 health over 30 sec. Must remain seated while eating. If you eat for 10 seconds will also increase your Spell Damage by 12 for 10 min.\nSell Price:"},
[232437] = {name = "Recipe: Darkclaw Bisque", additional_info = "Requires Cooking (300)\n\n[q2]Use: Teaches you how to cook Darkclaw Bisque.\nSell Price:\nDarkclaw Bisque\nRequires Level 45\n\n[q2]Use: Restores 2148 health over 30 sec. Must remain seated while eating. If you eat for 10 seconds will also increase your Spell Damage by 12 for 10 min.\nSell Price:\nRequires Darkclaw Lobster , Drinkable Stratholme Holy Water"},
[232438] = {name = "Smoked Redgill", additional_info = "Requires Level 35\n\n[q2]Use: Restores 1392 health over 30 sec. Must remain seated while eating. If you eat for 10 seconds will also increase your Healing done by 22 for 10 min.\nSell Price:"},
[232443] = {name = "Recipe: Smoked Redgill", additional_info = "Requires Cooking (300)\n\n[q2]Use: Teaches you how to cook Smoked Redgill.\nSell Price:\nSmoked Redgill\nRequires Level 35\n\n[q2]Use: Restores 1392 health over 30 sec. Must remain seated while eating. If you eat for 10 seconds will also increase your Healing done by 22 for 10 min.\nSell Price:\nRequires Raw Redgill"},
[232454] = {name = "[q7]Emblem of the Wild Gods", additional_info = "Binds to account\n[q]\"Proof of assisting the Shadowtooth Emissary. Redeemable at the Rune Broker in capital cities.\""},
[232455] = {name = "[q7]Emblem of Dishonor", additional_info = "Binds to account\n[q]\"Proof of confronting Illari Duskfeather. Redeemable at the Rune Broker in capital cities.\""},
[232456] = {name = "[q7]Emblem of the Violet Eye", additional_info = "Binds to account\n[q]\"Proof of victory over the Dark Riders. Redeemable at the Rune Broker in capital cities.\""},
[232457] = {name = "[q7]Emblem of the Worldcore", additional_info = "Binds to account\n[q]\"Proof of atunning to the Leyline Confluxes. Redeemable at the Rune Broker in capital cities.\""},
[232458] = {name = "[q2]Rune of Improved Sanctuary", additional_info = "Binds when picked up\nUnique\nClasses: Paladin\n[q2]Engrave your helm with the Improved Sanctuary rune:\n\n\nIncreases the damage prevented by your Blessing of Sanctuary by 100%, and increases damage done by your Blessing of Sanctuary by 20% of your shield block value.\n[q]\"Teaches you a new Engraving ability.\""},
[232459] = {name = "[q2]Rune of Backdraft", additional_info = "Binds when picked up\nUnique\nClasses: Warlock\n[q2]Engrave your helm with the Backdraft rune:\n\n\nYour Conflagrate ability also grants 30% spellcasting haste for 15 sec and no longer consumes Immolate.\n[q]\"Teaches you a new Engraving ability.\""},
[232460] = {name = "[q2]Rune of Displacement", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Engrave your bracers with the Displacement rune:\n\n\nTeleports back to where you last cast Blink from and resets the cooldown on Blink. Only usable within 10 sec of casting Blink.\n[q]\"Teaches you a new Engraving ability.\""},
[232461] = {name = "[q2]Rune of Despair", additional_info = "Binds when picked up\nUnique\nClasses: Priest\n[q2]Engrave your bracers with the Despair rune:\n\n\nPeriodic damage from your spells can now be critical strikes and all your damaging spell critical strikes deal 200% damage.\n[q]\"Teaches you a new Engraving ability.\""},
[232462] = {name = "[q2]Rune of Purifying Power", additional_info = "Binds when picked up\nUnique\nClasses: Paladin\n[q2]Engrave your bracers with the Purifying Power rune:\n\n\nReduces the cooldown on Exorcism and Holy Wrath by 50%, and Holy Wrath can now be cast at any target and will Stun Undead and Demon targets for 2 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[232549] = {name = "[q2]Logistics Task Briefing VI", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 60"},
[232610] = {name = "Formula: Magnificent Trollshine", additional_info = "Binds when picked up\nRequires Enchanting (300)\nRequiresZandalar Tribe\n- Honored\n\n[q2]Use: Teaches you how to create Magnificent Trollshine.\nSell Price:\nMagnificent Trollshine\nRequires Level 45\n\n[q2]Use: While applied to target shield it increases spell damage and healing by up to 36 and increases Spell Critical chance by 1%. Lasts for 30 minutes.\n5 Charges\nSell Price:\nRequires Flask of Mojo (3), Flask of Big Mojo (3), Large Brilliant Shard (2), Imbued Vial"},
[232611] = {name = "Magnificent Trollshine", additional_info = "Requires Level 45\n\n[q2]Use: While applied to target shield it increases spell damage and healing by up to 36 and increases Spell Critical chance by 1%. Lasts for 30 minutes.\n5 Charges\nSell Price:"},
[232652] = {name = "[q4]Zila Amanemodas", additional_info = "Binds when picked up\nUnique\nClasses: Warlock\n[q2]Use: Attune with the darkness within, allowing you better control over your inner demon."},
[233197] = {name = "[q3]Argent Training Manual", additional_info = "Binds when picked up\nRequires Level 50\n\n[q2]Use: Use the manual to call your Argent Squire for a training lesson in combat with the Silithid. Silithids killed in the squire's presence will increase your reputation with the Argent Dawn. (5 Min Cooldown)\n3 Charges"},
[233198] = {name = "[q3]Horn of the Dawn", additional_info = "Binds when picked up\nRequires Level 50\n\n[q2]Use: Rally your nearby party or raid members, granting them 10% increased spell critical strike chance, 5% increased melee and ranged critical strike chance, and 140 increased attack power. Lasts 2 hrs. Exclusive with similar world effects and unaffected by Chronoboons. (30 Sec Cooldown)"},
[233200] = {name = "[q3]Songflower Seed", additional_info = "Binds when picked up\nRequires Level 50\n\n[q2]Use: Summon a songflower that grants all your party or raid members 5% increased chance for a melee, ranged, or spell critical and 15 increased attributes for 1 hour. Exclusive with similar world effects. Unaffected by Chronoboons. (30 Sec Cooldown)"},
[233209] = {name = "[q3]Firewater Cauldron", additional_info = "Binds when picked up\nRequires Level 50\n\n[q2]Use: Summon a cauldron of Firewater for 10 min, useable by all members of your party or raid to increase melee attack power by 35 and size for 1 hour. (30 Sec Cooldown)"},
[233217] = {name = "[q3]Tunneler's Incense", additional_info = "Binds when picked up\nRequires Level 50\n\n[q2]Use: Inhaling this incense causes you to fade into the shadows, allowing you to sneak around while inside Hive'Ashi, Hive'Regal, or Hive'Zora, but reduces your speed by 50%. Lasts 1 min. (1 Min Cooldown)\n10 Charges\nSell Price:"},
[233250] = {name = "[q3]Ancient Branch", additional_info = "Binds when picked up\nRequires Level 50\n\n[q2]Use: Use the branch to call an Ancient of War to assist you in fighting Silithids. (15 Min Cooldown)\n3 Charges"},
[234012] = {name = "Hive Thistle", additional_info = "Sell Price:"},
[234016] = {name = "[q4]Signet Ring of the Bronze Dragonflight", additional_info = "Binds when picked up\nUnique-Equipped: Signet Ring of the Bronze Dragonflight (1)\nFinger\n+6 Stamina\n+7 Intellect\nRequires Level 60\nRequiresBrood of Nozdormu\n- Neutral\n[q2]Equip: Improves your chance to hit with all spells and attacks by 1%.\n\n[q2]Equip: Increases damage and healing done by magical spells and effects by up to 21.\n\n[q2]Equip: Increases the casting speed of your spells by 2% per piece of Timeworn armor equipped.\n[q]\"The Path of the Invoker\""},
[234017] = {name = "[q4]Signet Ring of the Bronze Dragonflight", additional_info = "Binds when picked up\nUnique-Equipped: Signet Ring of the Bronze Dragonflight (1)\nFinger\n+18 Strength\n+8 Stamina\nRequires Level 60\nRequiresBrood of Nozdormu\n- Neutral\n[q2]Equip: Improves your chance to hit with all spells and attacks by 1%.\n\n[q2]Equip: Gives you 1% chance per piece of Timeworn armor equipped to get an extra attack on melee or ranged hit. (Proc chance: 8%, 200ms cooldown)\n[q]\"The Path of the Dominator\""},
[234018] = {name = "[q4]Signet Ring of the Bronze Dragonflight", additional_info = "Binds when picked up\nUnique-Equipped: Signet Ring of the Bronze Dragonflight (1)\nFinger\n+10 Strength\n+18 Stamina\nRequires Level 60\nRequiresBrood of Nozdormu\n- Neutral\n[q2]Equip: Increased Defense +5.\n\n[q2]Equip: Reduces the chance for your attacks to be dodged or parried by 1% per piece of Timeworn armor equipped.\n[q]\"The Path of the Protector\""},
