[234271] = {name = "[q2]Formula: Scroll: Wrath of the Swarm", additional_info = "Binds when picked up\nRequires Enchanting (300)\nRequiresCenarion Circle\n- Friendly\n\n[q2]Use: Teaches you how to conjure a Scroll: Wrath of the Swarm.\nSell Price: \n[q3]Scroll: Wrath of the Swarm\nBinds when picked up\nRequires Level 60\nRequires Enchanting (300)\n\n[q2]Use: Read from the scroll, evoking the Wrath of the Swarm, empowering your raid to deal up to 40 increased damage and healing with spells, and increasing attack power by 40 for 1 hour. (1 Min Cooldown)\nRequires Greater Eternal Essence , Runecloth"},
[234272] = {name = "[q2]Formula: Enchanted Repellent", additional_info = "Binds when picked up\nRequires Enchanting (300)\nRequiresCenarion Circle\n- Friendly\n\n[q2]Use: Teaches you how to create Enchanted Repellent.\nSell Price: \nEnchanted Repellent\nRequires Level 60\n\n[q2]Use: While applied to target weapon or shield it increases spell damage by up to 45 and increases Spell Critical chance by 1% . Lasts for 30 minutes.\n5 Charges\nSell Price:\nRequires Qiraji Stalker Venom (3), Hive Thistle (3), Illusion Dust (2)"},
[234436] = {name = "[q4]Signet Ring of the Bronze Dragonflight", additional_info = "Binds when picked up\nUnique-Equipped: Signet Ring of the Bronze Dragonflight (1)\nFinger\n+8 Stamina\n+9 Intellect\nClasses: Priest , Warlock , Druid\nRequires Level 60\nRequiresBrood of Nozdormu\n- Exalted\n[q2]Equip: Increases damage and healing done by magical spells and effects by up to 30.\n\n[q2]Equip: Increases the damage dealt by all of your damage over time spells by 3% per piece of Timeworn armor equipped.\n[q]\"The Path of the Subjugator\""},
