[235480] = {name = "[q4]Grand Marshal's Bonecracker", additional_info = "Binds when picked up\n{One-Hand} {Mace}\n{89 - 134 Damage} {Speed 1.80}\n(61.94 damage per second)\n+13 Stamina\nDurability 105 / 105\nRequires Level 60\n[q2]Equip: Improves your chance to get a critical strike with all spells and attacks by 1%.\n\n[q2]Equip: +28 Attack Power.\n\n[q2]Equip: Reduces all damage taken from players and their pets by 5%. This effect cannot be combined from multiple sources.\nSell Price:"},
[235481] = {name = "[q4]Grand Marshal's Hacker", additional_info = "Binds when picked up\n{One-Hand} {Axe}\n{89 - 134 Damage} {Speed 1.80}\n(61.94 damage per second)\n+13 Stamina\nDurability 105 / 105\nRequires Level 60\n[q2]Equip: Improves your chance to get a critical strike with all spells and attacks by 1%.\n\n[q2]Equip: +28 Attack Power.\n\n[q2]Equip: Reduces all damage taken from players and their pets by 5%. This effect cannot be combined from multiple sources.\nSell Price:"},
[235509] = {name = "Satyrweed Tincture", additional_info = "Quest Item\nUnique\n[q2]Use: Purge satyr corruption from a weakened Mosshoof Courser or Thunderhead Skystormer."},
[235510] = {name = "Bramblesnap's Panacea", additional_info = "Quest Item\nUnique"},
[235517] = {name = "Torch", additional_info = "Requires Level 60"},
[235518] = {name = "Timbermaw War Banner", additional_info = "Quest Item\nUnique\n[q2]Use: Call forth Timbermaw reinforcements to face Prince Halanox."},
[235597] = {name = "[q2]Spell Notes: Deep Freeze", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Engrave your helm with the Deep Freeze rune:\n\n\nStuns the target for 5 sec. Only usable on Frozen targets. Deals [462 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) / 100 * ( 1 ) ] to [538 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) / 100 * ( 1 ) ] damage to targets permanently immune to Stun. This damage benefits from, but does not consume, stacks of Glaciate.\n[q]\"Teaches you a new Engraving ability.\""},
[235598] = {name = "[q2]Spell Notes: Icy Veins", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Engrave your pants with the Icy Veins rune:\n\n\nHastens your spellcasting, increasing spell casting speed by 20% and reduces the pushback suffered from damaging attacks while casting by 100%. Lasts 20 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[235599] = {name = "[q2]Spell Notes: Temporal Anomaly", additional_info = "Binds when picked up\nUnique\nClasses: Mage\n[q2]Engrave your helm with the Temporal Anomaly rune:\n\n\nLaunches an orb of temporal energy which slowly moves forward and every 2 sec grants all nearby party members a shield absorbing [100 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) / 100] damage for 15 sec. This shield accumulates additional value if party members remain near the orb.\n[q]\"Teaches you a new Engraving ability.\""},
[235600] = {name = "[q2]Rune of Divine Storm", additional_info = "Binds when picked up\nUnique\nClasses: Paladin\n[q2]Engrave your chest with the Divine Storm rune:\n\n\nAn instant weapon attack that causes 110% of weapon damage to up to 4 enemies within 8 yards. The Divine Storm heals up to 3 party or raid members totaling 25% of the damage caused.\n[q]\"Teaches you a new Engraving ability.\""},
[235601] = {name = "[q2]Rune of Fanaticism", additional_info = "Binds when picked up\nUnique\nClasses: Paladin\n[q2]Engrave your helm with the Fanaticism rune:\n\n\nIncreases your critical strike chance with Holy spells by 18%. In addition, your critical healing spells heal the target for 60% of the healed amount over 12 sec.\n[q]\"Teaches you a new Engraving ability.\""},
[235602] = {name = "[q2]Rune of Hammer of the Righteous", additional_info = "Binds when picked up\nUnique\nClasses: Paladin\n[q2]Engrave your bracers with the Hammer of the Righteous rune:\n\n\nHammer the current target and up to 3 additional nearby targets, causing 4 times your main hand damage per second as Holy damage.\n[q]\"Teaches you a new Engraving ability.\""},
[235603] = {name = "[q2]Rune of Righteous Vengeance", additional_info = "Binds when picked up\nUnique\nClasses: Paladin\n[q2]Engrave your cloak with the Righteous Vengeance rune:\n\n\nWhen your Judgement, Crusader Strike, or Divine Storm deals a critical strike, your target will take 30% additional damage over until cancelled.\n[q]\"Teaches you a new Engraving ability.\""},
[235604] = {name = "[q2]Rune of Shield of Righteousness", additional_info = "Binds when picked up\nUnique\nClasses: Paladin\n[q2]Engrave your cloak with the Shield of Righteousness rune:\n\n\nSlam the target with your shield, causing Holy damage based on your block value plus an additional [179 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100].\n[q]\"Teaches you a new Engraving ability.\""},
[235605] = {name = "[q2]Rune of Shock and Awe", additional_info = "Binds when picked up\nUnique\nClasses: Paladin\n[q2]Engrave your cloak with the Shock and Awe rune:\n\n\nWhile Righteous Fury is not active, dealing Holy Shock damage grants 200% of your Intellect as Spell Damage and reduces the threat you generate by 30% for 1 min.\n\n If Infusion of Light is engraved, gain Sunlight for 10 sec.\n\n\n Sunlight causes Divine Storm, Crusader Strike, and melee attacks against non-player controlled targets to deal bonus Holy damage equal to 60% of your holy spell power.\n[q]\"Teaches you a new Engraving ability.\""},
[235645] = {name = "Legashi Firewater Recipe", additional_info = "Quest Item"},
[235785] = {name = "Deadwind Cage \"Key\"", additional_info = "Quest Item\nUnique\n[q]\"Your astute powers of observation quickly determine that this \"key\" is really just a rock with a sharp edge on it. You suspect that simply bashing this against the lock should open the cage.\""},
[235786] = {name = "[q2]Karazhan Curio", additional_info = "Binds when picked up\nUnique (99)"},
[235787] = {name = "Ancient Ironwood Branch", additional_info = "Quest Item\nUnique"},
[235788] = {name = "Enthusiastic Wisp", additional_info = "Quest Item\nUnique\n[q]\"This thing just won't hold still...\""},
[235789] = {name = "Flame of Life", additional_info = "Quest Item\nUnique"},
[235790] = {name = "[q2]Enchanted Firebrand", additional_info = "Quest Item\nUnique\n[q2]Use: Hold up the Enchanted Torch and attempt to dispel the darkness near Karazhan Crypts. (15 Sec Cooldown)"},
[235852] = {name = "[q2]Violet Satchel", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\n[q]\"This small satchel bears the mark of the Kirin Tor of Dalaran. It seems to contain a few small objects but curiously, you find that you are unable to open the flap to see what is inside.\""},
[235867] = {name = "Scrap of Parchment", additional_info = "Binds when picked up\nUnique\n[q]\"The scrap of parchment appears to have been torn off of a larger poster or flyer. The only words legible on it seem to be a name ...Archmage Tarsis Kir-Moldir\"\nSell Price:"},
