[236878] = {name = "[q2]Mysterious Relic", additional_info = "Conjured Item\nBinds when picked up\n[q]\"Shadowy, yet unbroken. A relic of encroaching darkness.\""},
[236879] = {name = "[q2]Mysterious Relic", additional_info = "Conjured Item\nBinds when picked up\n[q]\"Discordant withering screams echo a harmonius bloom. The silvered edge outpours horror.\""},
[236880] = {name = "[q2]Mysterious Relic", additional_info = "Conjured Item\nBinds when picked up\n[q]\"False eidolons cling to the unexposed hilt clamoring for the grip of an ancient king.\""},
