[239246] = {name = "Fizzlefuse's Shopping List", additional_info = "Binds when picked up\nUnique\n[q]\"A list of items hastily scribbled down whenever it crossed the author's mind.\"\n[q2]<Right Click to Read>"},
[239292] = {name = "Forgewright's Notes", additional_info = "Quest Item\nUnique\n\"Contains the collected thoughts and works of Franclorn Forgewright.\""},
