[239316] = {name = "Triangulation Samophlange", additional_info = "Quest Item\nRequires Engineering (1)\n\n[q2]Use: Use the device at a designated triangulation point to aid Fizzlefuse in his teleporter's calibration. (10 Sec Cooldown)"},
[239512] = {name = "[q4]Lightbreaker Wrists", additional_info = "Sanctified\nBinds when picked up\n{Wrist} {Plate}\n477 Armor\n+29 Strength\n+10 Agility\n+13 Stamina\nDurability 55 / 55\nClasses: Warrior\nRequires Level 60\n[q2]Equip: Improves your chance to hit with all spells and attacks by 1%.\n\n[q2]Equip: Increases your attack speed by 1%.\n\n[q]Lightbreaker's Warplate (0/8)\n[q0]Lightbreaker Greathelm\nLightbreaker Shoulders\nLightbreaker Cuirass\nLightbreaker Belt\nLightbreaker Tassets\nLightbreaker Greaves\nLightbreaker Wrists\nLightbreaker Grips\n[q0](2) Set : Your Heroic Strike, Cleave, and Quick Strike damage is increased by 20% while in Battle Stance or Berserker Stance. Your Cleave strikes 1 additional target and can trigger Blood Surge.\n(4) Set : Each time you hit a target with Whirlwind, Heroic Strike, Quick Strike, or Cleave, the damage of your next Slam is increased by 20%, stacking up to 5 times.\n(6) Set : Each time Deep Wounds deals damage, it reduces the remaining cooldown on your Whirlwind by 3 sec. Whirlwind deals 100% increased damage to targets afflicted with your Deep Wounds.\nSell Price:"},
[239513] = {name = "[q4]Lightbreaker Belt", additional_info = "Sanctified\nBinds when picked up\n{Waist} {Plate}\n613 Armor\n+36 Strength\n+10 Agility\n+18 Stamina\nDurability 55 / 55\nClasses: Warrior\nRequires Level 60\n[q2]Equip: Improves your chance to get a critical strike with all spells and attacks by 1%.\n\n[q2]Equip: Increases your attack speed by 2%.\n\n[q]Lightbreaker's Warplate (0/8)\n[q0]Lightbreaker Greathelm\nLightbreaker Shoulders\nLightbreaker Cuirass\nLightbreaker Belt\nLightbreaker Tassets\nLightbreaker Greaves\nLightbreaker Wrists\nLightbreaker Grips\n[q0](2) Set : Your Heroic Strike, Cleave, and Quick Strike damage is increased by 20% while in Battle Stance or Berserker Stance. Your Cleave strikes 1 additional target and can trigger Blood Surge.\n(4) Set : Each time you hit a target with Whirlwind, Heroic Strike, Quick Strike, or Cleave, the damage of your next Slam is increased by 20%, stacking up to 5 times.\n(6) Set : Each time Deep Wounds deals damage, it reduces the remaining cooldown on your Whirlwind by 3 sec. Whirlwind deals 100% increased damage to targets afflicted with your Deep Wounds.\nSell Price:"},
[239514] = {name = "[q0]Lightbreaker Grips", additional_info = "Sanctified\nBinds when picked up\n{Hands} {Plate}\n681 Armor\n+35 Strength\n+8 Agility\n+13 Stamina\nDurability 55 / 55\nClasses: Warrior\nRequires Level 60\n[q2]Equip: Improves your chance to get a critical strike with all spells and attacks by 1%.\n\n[q2]Equip: Reduces the chance for your attacks to be dodged or parried by 1%.\n\n[q2]Equip: Increases your attack speed by 2%.\n\n[q]Lightbreaker's Warplate (0/8)\n[q0]Lightbreaker Greathelm\nLightbreaker Shoulders\nLightbreaker Cuirass\nLightbreaker Belt\nLightbreaker Tassets\nLightbreaker Greaves\nLightbreaker Wrists\nLightbreaker Grips\n[q0](2) Set : Your Heroic Strike, Cleave, and Quick Strike damage is increased by 20% while in Battle Stance or Berserker Stance. Your Cleave strikes 1 additional target and can trigger Blood Surge.\n(4) Set : Each time you hit a target with Whirlwind, Heroic Strike, Quick Strike, or Cleave, the damage of your next Slam is increased by 20%, stacking up to 5 times.\n(6) Set : Each time Deep Wounds deals damage, it reduces the remaining cooldown on your Whirlwind by 3 sec. Whirlwind deals 100% increased damage to targets afflicted with your Deep Wounds.\nSell Price:"},
[239515] = {name = "[q4]Lightbreaker Greaves", additional_info = "Sanctified\nBinds when picked up\n{Feet} {Plate}\n749 Armor\n+35 Strength\n+10 Agility\n+11 Stamina\nDurability 75 / 75\nClasses: Warrior\nRequires Level 60\n[q2]Equip: Improves your chance to hit with all spells and attacks by 1%.\n\n[q2]Equip: Increases your attack speed by 2%.\n\n[q2]Equip: Improves your chance to get a critical strike with all spells and attacks by 1%.\n\n[q]Lightbreaker's Warplate (0/8)\n[q0]Lightbreaker Greathelm\nLightbreaker Shoulders\nLightbreaker Cuirass\nLightbreaker Belt\nLightbreaker Tassets\nLightbreaker Greaves\nLightbreaker Wrists\nLightbreaker Grips\n[q0](2) Set : Your Heroic Strike, Cleave, and Quick Strike damage is increased by 20% while in Battle Stance or Berserker Stance. Your Cleave strikes 1 additional target and can trigger Blood Surge.\n(4) Set : Each time you hit a target with Whirlwind, Heroic Strike, Quick Strike, or Cleave, the damage of your next Slam is increased by 20%, stacking up to 5 times.\n(6) Set : Each time Deep Wounds deals damage, it reduces the remaining cooldown on your Whirlwind by 3 sec. Whirlwind deals 100% increased damage to targets afflicted with your Deep Wounds.\nSell Price:"},
