[241169] = {name = "Prototype Nitro Boosts", additional_info = "Quest Item\n[q2]Use: Insert a variable amount of gunpowder into the device and press the button.\n\n Your speed and likelihood of serious injury or death will increase based on the amount of gunpowder added.\n\n Can only be used in New Avalon."},
[241190] = {name = "[q2]Bird Whistle", additional_info = "Binds when used\n[q2]Use: Summon Pepe to join you on your adventures!"},
[241191] = {name = "[q3]Formula: Enchant Weapon - Grand Crusader", additional_info = "Binds when picked up\nRequires Enchanting (280)\n\n[q2]Permanently enchant a melee weapon so that often when attacking in melee it heals for 350 to 450 and increases Strength by 120 for 20 sec.\n[q]\"Teaches you how to permanently enchant a weapon to occasionally bless the wielder with incredible strength.\"\nSell Price:"},
[241195] = {name = "[q3]Formula: Enchant 2H Weapon - Grand Arcanist", additional_info = "Binds when picked up\nRequires Enchanting (280)\n\n[q2]Permanently enchant a two-handed melee weapon so that often when striking with a spell it restores 350 to 450 mana and increases Spell Power by 140 for 20 sec.\n[q]\"Teaches you how to permanently enchant a two-handed melee weapon to occasionally bless the wielder with enhanced spell power.\"\nSell Price:"},
[241201] = {name = "[q3]Formula: Enchant Weapon - Grand Sorcerer", additional_info = "Binds when picked up\nRequires Enchanting (280)\n\n[q2]Permanently enchant a melee weapon so that often when striking with a spell it restores 350 to 450 mana and increases Spell Power by 70 for 20 sec.\n[q]\"Teaches you how to permanently enchant a melee weapon to occasionally bless the wielder with enhanced spell power.\"\nSell Price:"},
[241613] = {name = "[q3]No Longer Used", additional_info = "Binds when picked up"},
[241650] = {name = "Major Discolored Healing Potion", additional_info = "Requires Level 60\n\n[q2]Use: Restores 3750 to 4250 health instantly, however you also suffer 75% of that amount over time.\n\n The symptoms of this effect can manifest as either a 6 sec poison or a 12 sec disease. (2 Min Cooldown)\nSell Price:"},
[241651] = {name = "[q2]Recipe: Major Discolored Healing Potion", additional_info = "Binds when picked up\nRequires Alchemy (250)\n[q]\"Teaches you how to craft Major Discolored Healing Potion.\"\nSell Price:"},
[241652] = {name = "Discolored Beast Heart", additional_info = "Sell Price:"},
[241655] = {name = "Mishandled Healing Potion", additional_info = "This Item Begins a Quest\nRequires Level 60\n[q]\"A truly disgusting potion.\"\nSell Price:"},
[241656] = {name = "Mishandled Healing Potion", additional_info = "This Item Begins a Quest\nRequires Level 60\n[q]\"A truly disgusting potion.\"\nSell Price:"},
[242018] = {name = "Plaguelands Bleeding Heart", additional_info = "Quest Item\n[q]\"An unusually gorgeous flower given the region it is native to. It is capable of thriving despite the plague.\""},
[242224] = {name = "Basket of Hearts", additional_info = "Quest Item\n[q]\"Perhaps not the best container one could pick for the situation.\""},
[242266] = {name = "[q2]World of Wardcraft", additional_info = "Binds when picked up\n[q]\"Filled cover to cover with thorough documentation of all things related to magical wards. Curiously, the book carries a subtle glow.\""},
[242267] = {name = "[q2]From Arcanist to Archmage", additional_info = "Binds when picked up\n[q]\"A self-promoting autobiography written by an author too irrelevant to be named. Interestingly, the book also thrums with an attention seeking spell.\""},
[242268] = {name = "[q2]If You Give a Crusader an Enchant", additional_info = "Binds when picked up\n[q]\"An entertaining short story that quickly descends into madness before culminating in giving the antagonist everything he wants. Amusingly, the book shimmers with power.\""},
[242269] = {name = "[q3]Brilliance of the Grand Sorcerer", additional_info = "Binds when picked up\nRequires Enchanting (280)\n\n[q2]Use: Combine 15 Illusion Dust and 1 Righteous Orb at a Mote of Possibility in pursuit of a new discovery."},
[242270] = {name = "[q3]Brilliance of the Grand Arcanist", additional_info = "Binds when picked up\nRequires Enchanting (280)\n\n[q2]Use: Combine 15 Illusion Dust and 1 Righteous Orb at a Mote of Possibility in pursuit of a new discovery."},
[242271] = {name = "[q3]Brilliance of the Grand Crusader", additional_info = "Binds when picked up\nRequires Enchanting (280)\n\n[q2]Use: Combine 15 Illusion Dust and 1 Righteous Orb at a Mote of Possibility in pursuit of a new discovery."},
[242361] = {name = "[q3]Formula: Enchant 2H Weapon - Grand Inquisitor", additional_info = "Binds when picked up\nRequires Enchanting (280)\n\n[q2]Permanently enchant a two-handed melee weapon so that often when attacking in melee it heals for 350 to 450 and increases Strength by 200 for 20 sec.\n[q]\"Teaches you how to permanently enchant a two-handed melee weapon to occasionally bless the wielder with immense strength.\"\nSell Price:"},
[242362] = {name = "[q3]Brilliance of the Grand Inquisitor", additional_info = "Binds when picked up\nRequires Enchanting (280)\n\n[q2]Use: Combine 15 Illusion Dust and 1 Righteous Orb at a Mote of Possibility in pursuit of a new discovery."},
[242363] = {name = "[q2]Who, What, Where, When, and Die! Five Keys to a Good Inquisition", additional_info = "Binds when picked up\n[q]\"Reading this left you with more questions than answers. What was this book even about? And why is it rumbling with great anticipation?\""},
[243065] = {name = "[q2]Broken Wand", additional_info = "Binds when picked up\nUnique\n[q2]Use: Imbue with wild magic.\nSell Price:"},
[243177] = {name = "[q3]Ingenious Toy", additional_info = "Binds when picked up\nUnique\nSell Price:"},
[243203] = {name = "Humongous Crystal", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 50\n[q]\"A fist-sized hunk of crystal with a pale blue luster.\""},
[243266] = {name = "Fel-Tainted Giblets", additional_info = "Quest Item"},
