[245983] = {name = "Ursine Heirloom", additional_info = "Quest Item\n[q]\"Well-worn and smoothed from age, this burl wood has the imprint of a bear paw carved into its surface. You have a strong desire to pass this on to another kindred spirit in need.\""},
[246055] = {name = "[q0]Inquisition Grips", additional_info = "Sanctified\nBinds when picked up\n{Hands} {Plate}\n681 Armor\n+13 Stamina\n+38 Intellect\nDurability 55 / 55\nClasses: Paladin\nRequires Level 60\n[q2]Equip: Improves your chance to get a critical strike with all spells and attacks by 1%.\n\n[q2]Equip: Reduces the chance for your attacks to be dodged or parried by 1%.\n\n[q2]Equip: Increases your attack speed by 2%.\n\n[q]Inquisition Shockplate (0/8)\n[q0]Inquisition Faceguard\nInquisition Epaulets\nInquisition Cuirass\nInquisition Cord\nInquisition Plate Pants\nInquisition Stompers\nInquisition Armbraces\nInquisition Grips\n[q0](2) Set : While Shock and Awe is active, Crusader Strike and Exorcism grant you Holy Power, increasing all Holy damage you deal by 10%, stacking up to 3 times. (100ms cooldown)\n(4) Set : Divine Storm, Holy Shock, and Holy Wrath consume all your Holy Power, dealing 100% increased damage per Holy Power you have accumulated, 50% effective against player controlled targets.\n(6) Set : Consuming Holy Power increases your Spell Power by 8 to 18% per Holy Power consumed for 10 sec.\nSell Price:"},
[246056] = {name = "[q4]Inquisition Armbraces", additional_info = "Sanctified\nBinds when picked up\n{Wrist} {Plate}\n477 Armor\n+13 Stamina\n+29 Intellect\nDurability 55 / 55\nClasses: Paladin\nRequires Level 60\n[q2]Equip: Reduces the chance for your attacks to be dodged or parried by 1%.\n\n[q2]Equip: Improves your chance to hit with all Holy spells by 3%.\n\n[q]Inquisition Shockplate (0/8)\n[q0]Inquisition Faceguard\nInquisition Epaulets\nInquisition Cuirass\nInquisition Cord\nInquisition Plate Pants\nInquisition Stompers\nInquisition Armbraces\nInquisition Grips\n[q0](2) Set : While Shock and Awe is active, Crusader Strike and Exorcism grant you Holy Power, increasing all Holy damage you deal by 10%, stacking up to 3 times. (100ms cooldown)\n(4) Set : Divine Storm, Holy Shock, and Holy Wrath consume all your Holy Power, dealing 100% increased damage per Holy Power you have accumulated, 50% effective against player controlled targets.\n(6) Set : Consuming Holy Power increases your Spell Power by 8 to 18% per Holy Power consumed for 10 sec.\nSell Price:"},
