[249469] = {name = "Frozen Heart of the Mountain", additional_info = "[q3]Frozen Heart of the Mountain\nBinds when picked up\nUnique-Equipped\nTrinket\n+7 Fire Resistance\n+7 Nature Resistance\n+7 Frost Resistance\n+7 Shadow Resistance\nRequires Level 50\n[q2]Equip: Improves your chance to hit by 0.9%.\n\n[q2]Use: Increases Frost and Shadow spell damage done by up to 29 for 15 sec. This effect is doubled in Snowy areas. (5 Min Cooldown)\nSell Price:"},
[249470] = {name = "Molten Heart of the Mountain", additional_info = "[q3]Molten Heart of the Mountain\nBinds when picked up\nUnique-Equipped\nTrinket\n+7 Fire Resistance\n+7 Nature Resistance\n+7 Frost Resistance\n+7 Shadow Resistance\nRequires Level 50\n[q2]Equip: + 2 Weapon Damage.\n\n[q2]Use: Increases Attack Power by 55 for 15 sec. This effect is doubled in Volcanic areas. (5 Min Cooldown)\nSell Price:"},
[249473] = {name = "Dormant Heart of the Mountain", additional_info = "[q3]Dormant Heart of the Mountain\nBinds when picked up\nUnique-Equipped\nTrinket\n+7 Fire Resistance\n+7 Nature Resistance\n+7 Frost Resistance\n+7 Shadow Resistance\nRequires Level 50\n[q2]Equip: Your casts of Greater Heal, Healing Touch, Healing Wave, or Holy Light in combat grant up to 40 increased healing and up to 13 increased damage for 15 sec.\nSell Price:"},
[249474] = {name = "[q2]Formula: Enchant Bracer - Minor Intellect", additional_info = "Binds when picked up\nRequires Enchanting (70)\n\n[q2]Permanently enchant bracers to give +3 Intellect.\n[q]\"Teaches you how to permanently enchant bracers to give +3 Intellect.\"\nSell Price:"},
[249475] = {name = "[q2]Formula: Enchant Bracer - Minor Healing Power", additional_info = "Binds when picked up\nRequires Enchanting (90)\n\n[q2]Permanently enchant bracers so they increase the wearer's healing spells by up to 8 and damage spells by up to 3.\n[q]\"Teaches you how to permanently enchant bracers to increase Healing Power by up to 8 and Spell Damage by up to 3.\"\nSell Price:"},
[249476] = {name = "[q3]Formula: Mystic Mushroom", additional_info = "Binds when picked up\nRequires Enchanting (130)\n\n[q2]Creates a mystic mushroom.\n[q]\"Teaches you how to craft a Mystic Mushroom.\"\nSell Price:"},
[249477] = {name = "[q3]Formula: Tenets of the Silver Hand", additional_info = "Binds when picked up\nRequires Enchanting (130)\n\n[q2]Creates a copy of the Tenets of the Silver Hand.\n[q]\"Teaches you how to craft Tenets of the Silver Hand.\"\nSell Price:"},
[249478] = {name = "[q3]Formula: Polished Driftwood Icon", additional_info = "Binds when picked up\nRequires Enchanting (130)\n\n[q2]Creates a polished driftwood icon.\n[q]\"Teaches you how to craft a Polished Driftwood Icon.\"\nSell Price:"},
[249479] = {name = "[q2]Formula: Enchant Weapon - Insight", additional_info = "Binds when picked up\nRequires Enchanting (140)\n\n[q2]Permanently enchant a Melee Weapon to have a chance to grant Insight when you cast a spell, increasing Spirit by 100% for 10 sec.\n[q]\"Teaches you how to permanently enchant a weapon to grant a chance to gain Insight when you cast a spell, which gives +5% Spirit for a short duration.\"\nSell Price:"},
[249480] = {name = "[q2]Formula: Enchant Weapon - Recovery", additional_info = "Binds when picked up\nRequires Enchanting (140)\n\n[q2]Permanently enchant a Melee Weapon to trigger Recovery when you are Parried or Dodged, healing you for 5% of your maximum health. Cannot occur more often than once every 10 sec.\n[q]\"Teaches you how to permanently enchant a weapon to grant a chance to trigger Recovery when your attacks are dodged or parried, which heals you for 5% of your maximum health. Cannot occur more than once every 10 sec.\"\nSell Price:"},
[249481] = {name = "[q2]Formula: Enchant Weapon - Revelation", additional_info = "Binds when picked up\nRequires Enchanting (140)\n\n[q2]Permanently enchant a Melee Weapon to have a chance to trigger Revelation when a non-periodic spell fails to critically strike. Revelation grants 100% increased critical strike chance to the next non-periodic spell cast. Revelation's chance to trigger is diminished as your critical strike chance increases.\n[q]\"Teaches you how to permanently enchant a weapon to grant a chance to trigger Revelation when your direct spells fail to deal a critical strike. Revelation grants 100% increased critical strike chance to your next spell cast.\"\nSell Price:"},
