[253258] = {name = "The Hum Gun", additional_info = "Quest Item\n[q2]Use: Emits a short blast of sound that can only be heard by animals, beasts, and non-speaking beings. (20 Sec Cooldown)\n[q]\"You can almost make out the sigil of the alliance, barely visible under heavy corrosion.\""},
[253259] = {name = "Cool Heat", additional_info = "Binds when picked up\nUnique\nDuration: 20 min\n[q2]Use: Makes the air around the target uncomfortable, regardless of ambient temperature or weather. (20 Sec Cooldown)\n[q]\"Slowly boils the frog, but in a gentle breeze of directed air!\"\nSell Price:"},
[253260] = {name = "Miniature Morphologic Mimic Encabulator", additional_info = "Binds when picked up\nDuration: 20 min\nRequires Level 61\n\n[q2]Use: Temporarily gives the user an enchantment disguising them as their target. (1 Min, 15 Sec Cooldown)\n[q]\"Experimental device which wraps the user in a veiling enchantment of limited size.\"\nSell Price:"},
[253341] = {name = "Hyjal Owl Feather", additional_info = "Quest Item"},
[253378] = {name = "[q2]Tenn's Road-Worn Flute", additional_info = "Binds when used\n[q2]Use: Right Click to summon and dismiss Wimdy."},
[253399] = {name = "Sealed Letter", additional_info = "Quest Item\nUnique"},
