[260704] = {name = "[q0]Polished Bronze Safety Goggles", additional_info = "Binds when picked up\n{Head} {Cloth}\n2 Armor\nSell Price:"},
[260784] = {name = "SAF-T Tabs", additional_info = "Crafting Reagent\n[q]\"SAF-T brand tabs make it SAF to hand out dynamite to all your friends!\"\nSell Price:"},
[260792] = {name = "SAF-T Dynamite", additional_info = "[q2]Use: Inflicts 26 to 34 Fire damage in a 5 yd radius. (1 Min Cooldown)\n[q]\"Easy to throw, and SAF-T too!\"\nSell Price:"},
[260793] = {name = "SAF-T Copper Bomb", additional_info = "[q2]Use: Inflicts 22 to 28 Fire damage and stuns targets in a 3 yd radius for 1 sec. Any damage will break the effect. (1 Min Cooldown)\n[q]\"SAF-T Brand bombs *almost* never blow up in your hands (or your paws!)\"\nSell Price:"},
[260794] = {name = "EZ-Thro Wrap", additional_info = "Crafting Reagent\nSell Price:"},
[260795] = {name = "EZ-Thro Copper Bomb XL", additional_info = "[q2]Use: Inflicts 43 to 57 Fire damage and stuns targets in a 5 yd radius for 1 sec. Any damage will break the effect. (1 Min Cooldown)\nSell Price:"},
[260796] = {name = "No Slip SAF-T Padding", additional_info = "Crafting Reagent\n[q]\"SAF-T Padding prevents those easy throwing accidents.\"\nSell Price:"},
[260797] = {name = "SAF-T Bronze Bomb", additional_info = "[q2]Use: Inflicts 73 to 97 Fire damage and stuns targets in a 3 yd radius for 2 sec. Any damage will break the effect. (1 Min Cooldown)\nSell Price:"},
[260798] = {name = "SAF-T Jumbo Dynamite", additional_info = "[q2]Use: Inflicts 128 to 172 Fire damage in a 5 yd radius. (1 Min Cooldown)\n[q]\"If it's easy to throw, it's not SAF-T!\"\nSell Price:"},
[260799] = {name = "SAF-T Bell", additional_info = "Crafting Reagent\n[q]\"Do you know where your Sheep is?! SAF-T Knows.\"\nSell Price:"},
[260800] = {name = "Shafety Sheep", additional_info = "[q2]Use: Summons an Explosive Sheep which will charge at a nearby enemy and explode for 135 to 165 damage. Lasts for 3 min or until it explodes. (1 Min Cooldown)\n[q]\"Guaranteed to blow up only where it's SAF!\"\nSell Price:"},
[260801] = {name = "EZ-Thro Fireproof Fuse", additional_info = "Crafting Reagent\n[q]\"Guaranteed not to burn!\"\nSell Price:"},
[260802] = {name = "EZ-Thro Bronze Mortar", additional_info = "Binds when equipped\nUnique-Equipped\nTrinket\n[q2]Use: Inflicts 85 to 115 Fire damage and stuns targets in a 5 yd radius for 2 sec. Any damage will break the effect. (10 Min Cooldown)\n8 Charges\n[q]\"Thro mo mo tar!\"\nSell Price:"},
[260803] = {name = "EZ-Thro Grenade", additional_info = "[q2]Use: Inflicts 213 to 287 Fire damage in a 5 yd radius. (1 Min Cooldown)\n[q]\"Who needs safety when it's this easy to throw?\"\nSell Price:"},
[260804] = {name = "SAF-T Casing", additional_info = "Crafting Reagent\n[q]\"Extra padding for SAF-T!\"\nSell Price:"},
[260805] = {name = "SAF-T Bomb", additional_info = "[q2]Use: Inflicts 149 to 201 Fire damage and stuns targets in a 5 yd radius for 3 sec. Any damage will break the effect. (1 Min Cooldown)\n[q]\"S. A. F. T. B. O. M. B. SAF-T. Bomb.\"\nSell Price:"},
[260806] = {name = "Emergency Field Cloak", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n[q2]Use: Gives invisibility for 10 sec. (1 Hour Cooldown)\n3 Charges\n[q]\"SAF-T means not getting caught.\"\nSell Price:"},
[260807] = {name = "Compact Critter Carrier", additional_info = "Classes: Hunter\nRequires Level 40\n\n[q2]Use: Place a Compact Critter Carrier for 3 min that allows Hunters in your group to access their stabled pets. (30 Min Cooldown)\nSell Price:"},
[260808] = {name = "EZ-Thro Tru-Trigger", additional_info = "Crafting Reagent\n[q]\"EZ to use and almost never misfires!\"\nSell Price:"},
[260809] = {name = "Tru-Trigger Frag Bomb", additional_info = "[q2]Use: Inflicts 149 to 201 Fire damage and stuns targets in an 8 yd radius for 2 sec. Any damage will break the effect. (1 Min Cooldown)\n[q]\"Tru-Trigger frags enemies, not in your hands.\"\nSell Price:"},
[260810] = {name = "SAF-T Disposable Parachute", additional_info = "Binds when equipped\nBack\n31 Armor\n[q2]Use: Reduces your fall speed for 10 sec. (30 Min Cooldown)\n3 Charges\n[q]\"SAF-T in case you need to jump.\"\nSell Price:"},
[260811] = {name = "Gnomish Army Knife", additional_info = "Requires Level 45\n[q]\"It's got everything: a spanner, a wrench, a hammer... even a mining pick.\"\nSell Price:"},
[260812] = {name = "[q3]Loot-A-Rang", additional_info = "Binds when used\nRequires Level 50\nRequires Engineering (250)\n\n[q2]Use: Retrieves the loot from a nearby corpse. (3 Sec Cooldown)\nSell Price:"},
[260813] = {name = "SAF-T Tube", additional_info = "Crafting Reagent\n[q]\"Prevents accidental oxygen exposure. That wouldn't be SAF.\"\nSell Price:"},
[260814] = {name = "SAF-T Clever Dynamite", additional_info = "[q2]Use: Inflicts 340 to 460 Fire damage in a 5 yd radius. (1 Min Cooldown)\n[q]\"SAF-T isn't dense. It's clever!\"\nSell Price:"},
[260815] = {name = "EZ-Thro Shell", additional_info = "Crafting Reagent\n[q]\"Encase your explosives in EZ to Thro thorium-plated shells.\"\nSell Price:"},
[260816] = {name = "EZ-Thro Thorium Grenade", additional_info = "[q2]Use: Inflicts 300 to 500 Fire damage and stuns targets for 3 sec in a 3 yd radius. Any damage will break the effect. (1 Min Cooldown)\n[q]\"Anyone can use grenades with EZ-Thro!\"\nSell Price:"},
[260817] = {name = "EZ-Thro Dark Bomb", additional_info = "[q2]Use: Inflicts 225 to 675 Fire damage and stuns targets in a 5 yd radius for 4 sec. Any damage will break the effect. (1 Min Cooldown)\n[q]\"So EZ, you can Thro it in the dark.\"\nSell Price:"},
[260818] = {name = "EZ-Thro Mana Bomb", additional_info = "[q2]Use: Burns 675 to 1125 mana from those in the blast radius and deals 50% of the mana drained in damage to the target. Also Silences targets in the blast for 5 sec. (1 Min Cooldown)\nSell Price:"},
[260819] = {name = "[q2]EZ-Thro Field Transporter: Gadgetzan", additional_info = "Binds when used\nUnique-Equipped\nTrinket\nRequires Level 55\n[q2]Use: Safely transport yourself to Gadgetzan in Tanaris!  Emphasis on Safe!  Yup, nothing bad could ever happen while using this device! (4 Hrs Cooldown)\n3 Charges\nSell Price:"},
[260820] = {name = "[q2]SAF-T Emergency Ripper: Everlook", additional_info = "Binds when used\nUnique-Equipped\nTrinket\nRequires Level 55\nUse: Rips the dimensional walls asunder and transports you to Everlook in Winterspring.  There are technical problems that sometimes occur, but that's what Goblin Engineering is all about! (4 Hrs Cooldown)\n3 Charges\nSell Price:"},
[260821] = {name = "[q2]EZ and SAF Field Transporter: Mt. Hyjal", additional_info = "Binds when used\nUnique-Equipped\nTrinket\nRequires Level 60\n[q2]Use: Rips the dimensional walls asunder and transports you to Kaylaena's Workshop on Mount Hyjal. Technical problems have a high chance to occur with this mad combination of goblin and gnomish engineering. (4 Hrs Cooldown)\n3 Charges\n[q]\"Not only combining Goblin and Gnome tech, but also combining plans from the EZ-Thro and SAF-T corporations. Who knows if this will even work?\"\nSell Price:"},
[260822] = {name = "[q2]Ultrasafe Rechargeable Battery", additional_info = "Requires Level 60\n\n[q2]Use: Restores 3 charges to a SAF-T or EZ-Thro brand device in your possession that does not involve explosions. It would be completely Unsafe with explosives. (1 Min Cooldown)\nSell Price:"},
[260823] = {name = "[q2]Dimensional Transporter - Mt. Hyjal", additional_info = "Binds when used\nRequires Level 60\nRequires Engineering (300)\n\n[q2]Use: Rips the dimensional walls asunder and transports you to Kaylaena's Workshop on Mount Hyjal. Technical problems have a high chance to occur with this mad combination of goblin and gnomish engineering. (4 Hrs Cooldown)\n[q]\"A dangerous amalgamation of Goblin and Gnome engineering techniques.\"\nSell Price:"},
[260824] = {name = "[q3]Gnomish Poultryizer", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\nRequires Level 60\n[q2]Use: Turns the target into a chicken for 15 sec. Well, that is assuming the transmogrification polarity has not been reversed... (5 Min Cooldown)\nSell Price:"},
[260825] = {name = "[q2]Ultralight Goblin Glider", additional_info = "Binds when used\nRequires Engineering (250)\n\n[q2]Use: Glide downward through the air for 10 sec while controlling your direction of travel. (3 Min Cooldown)"},
[260826] = {name = "[q2]Gnomish Weather Machine NYI", additional_info = "Binds when used\nRequires Level 60\nRequires Engineering (300)\nSell Price:"},
[260827] = {name = "[q2]Stealthman 52", additional_info = "Requires Level 55\nRequires Engineering (250)\n\n[q2]Use: Cloaks the user in a stealth field for up to 1 min. Cannot be used in combat. The field lasts for up to 6 sec after moving. (5 Min Cooldown)\n[q]\"Used by real secret agents.\"\nSell Price:"},
[260828] = {name = "[q2]SAF-T Nitro Boosts", additional_info = "Binds when equipped\nWaist\nRequires Level 55\n[q2]Use: Activate a set of jets to increase your movement speed by up to 160%, for up to 8 sec.\n3 Charges\n[q]\"Rocket to safety with SAF-T.\"\nSell Price:"},
[260829] = {name = "[q2]EZ-Thro Magnetic Displacer", additional_info = "Binds when equipped\nWaist\nRequires Level 55\n[q2]Use: Disrupt a magnetic field between you and your nearby enemy target, knocking you both away.\n\n Can only affect targets up to 2 levels higher than you. Some targets cannot be displaced. Targets can only be affected by this effect once every 2 min.\n3 Charges\n[q]\"EZ-Thro corporation not responsible for magnets preventing grenades from being thrown.\"\nSell Price:"},
[260830] = {name = "[q2]SAF-T Teleport", additional_info = "Binds when equipped\nWaist\nRequires Level 55\n[q2]Use: Teleport forward 20 yds.\n3 Charges\n[q]\"Teleport to SAF-T!\"\nSell Price:"},
[260880] = {name = "Air Construct Core", additional_info = "Quest Item\nUnique\n[q]\"The glowing orb seems to be looking at you, following your movements with quiet curiosity.\""},
[260881] = {name = "Crystallized Lightning", additional_info = "Quest Item\nUnique\n[q]\"The surface of this object is smooth to the touch and makes the hair on the back of your neck stand up when you hold it.\""},
[260883] = {name = "Enchanted Gyrozephyr", additional_info = "Quest Item\nUnique\n[q]\"This object softly vibrates, constantly in a state of perpetual motion. If you try to hold it still, the force it exerts increases greatly in intensity.\""},
