[268912] = {name = "Expiring Crab Cake", additional_info = "Conjured Item\nUnique (5)\nRequires Level 5\n\n[q2]Use: Restores 234 health over 21 sec. Must remain seated while eating. If you spend at least 10 sec eating, you will become well fed and gain 3 Stamina for 15 min. Additionally, experience gained from kills is increased by 5%."},
