[268967] = {name = "Token of the Wild King", additional_info = "Quest Item\nUnique\n[q]\"This crude necklace bears a passing resemblance to a... bear? Stag? Eagle? Steaglebear?\""},
[268990] = {name = "Pristine Fel-Slime Crystal", additional_info = "Quest Item\nUnique\n[q]\"This flawless crystal hums softly in your hands and emits a faint light. An ashen hue seems to cover its dull surface and fel ash veins create an intricate pattern within.\""},
