[274273] = {name = "[q2]Flask of Natural Accuracy", additional_info = "Requires Level 55\n\n[q2]Use: Increases your Stamina by 60. While in Mount Hyjal, Hyjal Summit, and the Barrow Deeps, you also gain 5% Hit Chance.\n\n\n Lasts for 2 hrs. You can only have the effect of one flask at a time. This effect persists through death. (3 Sec Cooldown)\nSell Price:"},
[274274] = {name = "[q2]Flask of Natural Aggression", additional_info = "Requires Level 55\n\n[q2]Use: Increases your Stamina by 60. While in Mount Hyjal, Hyjal Summit, and the Barrow Deeps, you also gain 4% Critical Strike Chance.\n\n\n Lasts for 2 hrs. You can only have the effect of one flask at a time. This effect persists through death. (3 Sec Cooldown)\nSell Price:"},
[274275] = {name = "[q2]Flask of Natural Precision", additional_info = "Requires Level 55\n\n[q2]Use: Increases your Stamina by 60. While in Mount Hyjal, Hyjal Summit, and the Barrow Deeps, you also gain 5% reduced chance to be dodged or parried.\n\n\n Lasts for 2 hrs. You can only have the effect of one flask at a time. This effect persists through death. (3 Sec Cooldown)\nSell Price:"},
[274276] = {name = "[q2]Flask of Natural Swiftness", additional_info = "Requires Level 55\n\n[q2]Use: Increases your Stamina by 60. While in Mount Hyjal, Hyjal Summit, and the Barrow Deeps, you also gain 5% Haste.\n\n\n Lasts for 2 hrs. You can only have the effect of one flask at a time. This effect persists through death. (3 Sec Cooldown)\nSell Price:"},
