[279938] = {name = "Trapper's Workbench", additional_info = "Requires Skinning (300)\n\n[q2]Use: Places a Trapper's Workbench containing 1 trap, and provides all the benefits of a Camp Chair. Requires a Campfire nearby.\n\n May be placed over a Camp Chair to replace it.\n\n All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279939] = {name = "Collecting Basket", additional_info = "Binds when picked up\n6 Slot Bag\nSell Price:"},
[279940] = {name = "Toxin Study", additional_info = "Requires First Aid (140)\n\nUse: Places a Toxin Study that contains healing potions and anti-venom, and provides all of the benefits of a First Aid Kit. Requires a Campfire nearby.\n\n May be placed over a First Aid Kit to replace it.\n All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279941] = {name = "Tanning Rack", additional_info = "Requires Leatherworking (140)\n\n[q2]Use: Places a Tanning Rack that allows the creation of certain reagents, and provides all of the benefits of a Camp Tent. Requires a Campfire nearby.\n\n May be placed over a Camp Tent to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279943] = {name = "Spinning Wheel", additional_info = "Requires Tailoring (140)\n\n[q2]Use: Places a Spinning Wheel that allows the creation of certain reagents, and provides all the benefits of a Faction Banner. Requires a Campfire nearby.\n\n May be placed over a Faction Banner to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279944] = {name = "Sharpening Wheel", additional_info = "Requires Blacksmithing (20)\n\n[q2]Use: Constructs a sharpening wheel that grants you and others sitting nearby [6][11][20][34] increased Strength, mutually exclusive with Strength of Earth Totem.\n\n Requires a Campfire nearby. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279945] = {name = "Sewing Machine", additional_info = "Requires Leatherworking (300)\n\n[q2]Use: Places a Sewing Machine usable for recipes that require it, and provides all of the benefits of a Camp Tent. Requires a Campfire nearby.\n\n May be placed over a Camp Tent to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279947] = {name = "Seed Hybridizer", additional_info = "Requires Herbalism (300)\n\n[q2]Use: Places a Seed Hybridizer that allows seeds to be multiplied or combined into rarer tiers, and provides all of the benefits of an Incense Candle. Requires a Campfire nearby.\n\n May be placed over an Incense Candle to replace it.\n All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279948] = {name = "Rock Garden", additional_info = "Requires Mining (140)\n\n[q2]Use: Places a Rock Garden that spawns a common mining node over time, and provides all the benefits of a Lodestone. Requires a Campfire nearby.\n\n May be placed over a Lodestone to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279949] = {name = "Repair Bot", additional_info = "Requires Engineering (140)\n\n[q2]Use: Summons a Repair Bot that allows you and others nearby to buy reagents and repair gear. Requires a Campfire nearby.\n\n May be placed over a Reagent Bot to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279950] = {name = "Reagent Bot", additional_info = "Requires Engineering (20)\n\n[q2]Use: Summons a Reagent Bot that allows you and others nearby to purchase reagents. Requires a Campfire nearby. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279951] = {name = "Plague Doctor's Laboratory", additional_info = "Requires First Aid (300)\n\nUse: Places a Plague Doctor's Laboratory that contains healing potions and poultices, and provides all of the benefits of a First Aid Kit. Requires a Campfire nearby.\n\n May be placed over a First Aid Kit to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279952] = {name = "Molten Foundry", additional_info = "Requires Mining (300)\n\n[q2]Use: Places a Molten Foundry usable for recipes that require it, and provides all the benefits of a Lodestone. Requires a Campfire nearby.\n\n May be placed over a Lodestone to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279955] = {name = "Master Forge", additional_info = "Requires Blacksmithing (300)\n\nUse: Places a Master Forge usable for recipes that require it, and provides all of the benefits of a Sharpening Wheel. Requires a Campfire nearby.\n\n May be placed over a Sharpening Wheel to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279956] = {name = "Mana Well", additional_info = "Requires Alchemy (20)\n\n[q2]Use: Constructs a mana well that allows you and others sitting nearby to regenerate [10][15][20][24][29] Mana every 5 sec, muutally exclusive with Blessing of Wisdom.\n\n Requires a Campfire nearby. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279957] = {name = "Cookie's Feast", additional_info = "Requires Cooking (140)\n\nUse: Lay out Cookie's Feast that contains Stamina-boosting food. Requires a Cooking Fire nearby. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279959] = {name = "Loom", additional_info = "Requires Tailoring (300)\n\n[q2]Use: Places a Loom usable for recipes that require it, and provides all the benefits of a Faction Banner. Requires a Campfire nearby.\n\n May be placed over a Faction Banner to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279960] = {name = "Lodestone", additional_info = "Requires Mining (20)\n\n[q2]Use: Erects a lodestone that allows you and others sitting nearby to gain [12][20][32][49][67][90] increased melee Attack Power, mutually exclusive with Blessing of Might.\n\n Requires a Campfire nearby. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279961] = {name = "Journeyman Campfire Kit", additional_info = "Requires Cooking (140)\n\n[q2]Use: Builds a journeyman campfire that allows cooking and the placement of up to 5 additional camp features. Players sitting or crafting nearby for 1 min will gain benefits from other camp features. (5 Min Cooldown)"},
[279962] = {name = "Incense Candle", additional_info = "Requires Herbalism (20)\n\n[q2]Use: Ignites an incense candle that allows you and others sitting nearby to gain [2][6][12][18][25] increased Intellect, mutually exclusive with Arcane Intellect.\n\n Requires a Campfire nearby. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279964] = {name = "Greenhouse", additional_info = "Requires Herbalism (140)\n\n[q2]Use: Places a Greenhouse that will grow herbs over time from seeds planted, and provides all of the benefits of an Incense Candle. Requires a Campfire nearby.\n\n May be placed over an Incense Candle to replace it.\n All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279965] = {name = "Fishing Rack", additional_info = "Requires Fishing (140)\n\nUse: Places a Fishing Rack that grants the ability to catch uncommon fish for 1 hour, provides Fishing Skill lures, and provides all of the benefits of a Fish Bowl. Requires a Campfire nearby.\n\n May be placed over a Fish Bowl to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279966] = {name = "Fishing Hut", additional_info = "Requires Fishing (300)\n\nUse: Places a Fishing Hut that grants the ability to catch rare fish for 1 hour, provides Fishing Skill lures, and provides all of the benefits of a Fish Bowl. Requires a Campfire nearby.\n\n May be placed over a Fish Bowl to replace it.\n All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279967] = {name = "Fish Bowl", additional_info = "Requires Fishing (20)\n\n[q2]Use: Places a small fish bowl that allows you and others sitting nearby to gain 8% increased stats, mutually exclusive with Blessing of Kings.\n\n Requires a Campfire nearby. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279968] = {name = "First Aid Kit", additional_info = "Requires First Aid (20)\n\n[q2]Use: Unpacks a first aid kit that allows you and others sitting nearby to gain [3][8][21][34][45][56] increased Stamina, mutually exclusive with Power Word: Fortitude.\n\n Requires a Campfire nearby. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279969] = {name = "Field Guide", additional_info = "Requires Skinning (140)\n\n[q2]Use: Places a Field Guide that allows players to read it and gain Track Beasts, and provides all the benefits of a Camp Chair. Requires a Campfire nearby.\n\n May be placed over a Camp Chair to replace it.\n\n All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279970] = {name = "Fermenter", additional_info = "Requires Alchemy (140)\n\n[q2]Use: Places a fermenter that allows the creation of certain reagents, and provides all of the benefits of a Mana Well. Requires a Campfire nearby. May be placed over a Mana Well to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279972] = {name = "Faction Banner", additional_info = "Requires any Horde race\nRequires Tailoring (20)\n\n[q2]Use: Unrolls a banner that allows you and other members of the Horde sitting nearby to gain [14][19][27][32] increased Spirit, mutually exclusive with Divine Spirit.\n\n Requires a Campfire nearby. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279973] = {name = "Faction Banner", additional_info = "Requires any Alliance race\nRequires Tailoring (20)\n\n[q2]Use: Unrolls a banner that allows you and other members of the Alliance sitting nearby to gain [14][19][27][32] increased Spirit, mutually exclusive with Divine Spirit.\n\n Requires a Campfire nearby. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279974] = {name = "Expert Campfire Kit", additional_info = "Requires Cooking (220)\n\n[q2]Use: Builds an expert campfire that allows cooking and the placement of up to 10 additional camp features. Players sitting or crafting nearby for 1 min will gain benefits from other camp features. (5 Min Cooldown)"},
[279976] = {name = "Enchanted Lute", additional_info = "Requires Enchanting (20)\n\n[q2]Use: Summons an enchanted lute that allows you and others sitting nearby to gain [28][71][114][163][211][260][308] Armor[][and][,][13][12][9][7][4][2][increase to all stats][, and 22][, and 16][, and 12][, and 6][increase to all resistances], mutually exclusive with Mark of the Wild.\n\n Requires a Campfire nearby. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279978] = {name = "Camp Tent", additional_info = "Requires Leatherworking (20)\n\n[q2]Use: Builds a tent that allows you and others sitting nearby to increase Rested experience to 5% of a level. No effect if Rested experience already exceeds that value.\n\n Requires a Campfire nearby. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279979] = {name = "Camp Chair", additional_info = "Requires Skinning (20)\n\n[q2]Use: Assembles a camp chair that allows you and others sitting nearby to gain 2% increased critical strike chance with all spells and attacks, mutually exclusive with Moonkin Aura.\n\n Requires a Campfire nearby. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279981] = {name = "Basic Campfire Kit", additional_info = "Requires Cooking (1)\n\n[q2]Use: Builds a basic campfire that allows cooking and the placement of up to 3 additional camp features. Players sitting or crafting nearby for 1 min will gain benefits from other camp features. (5 Min Cooldown)"},
[279982] = {name = "Iron Oven", additional_info = "Requires Cooking (300)\n\nUse: Places an Iron Oven required for the most advanced cooking recipes. Requires a Cooking Fire nearby. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279985] = {name = "Arcane Salvager", additional_info = "Requires Enchanting (140)\n\n[q2]Use: Places an Arcane Salvager that enables more efficient disenchanting, and provides all the benefits of an Enchanted Lute. Requires a Campfire nearby.\n\n May be placed over an Enchanted Lute to replace it.\n All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279987] = {name = "Arcane Forge", additional_info = "Requires Enchanting (300)\n\nUse: Places an Arcane Forge usable for recipes that require it, and provides all the benefits of an Enchanted Lute. Requires a Campfire nearby.\n\n May be placed over an Enchanted Lute to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279988] = {name = "Anvil", additional_info = "Requires Blacksmithing (140)\n\n[q2]Use: Places an anvil, and provides all of the benefits of a Sharpening Wheel. Requires a Campfire nearby.\n\n May be placed over a Sharpening Wheel to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279989] = {name = "Anarchist's Workbench", additional_info = "Requires Engineering (300)\n\n[q2]Use: Places an Anarchist's Workbench usable for recipes that require it. Requires a Campfire nearby. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[279990] = {name = "Alchemy Laboratory", additional_info = "Requires Alchemy (300)\n\nUse: Places an Alchemy Laboratory usable for recipes that require it, and provides all of the benefits of a Mana Well. Requires a Campfire nearby.\n\n May be placed over a Mana Well to replace it.\n All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
